import java.io.{BufferedReader, InputStream, InputStreamReader}
import java.util.StringTokenizer

import scala.collection.mutable
import scala.util.Sorting
import math.{abs, max, min}

object Main {
  def solve(): Unit = {
    val sc = new InputReader(System.in)
    val N = sc.nextInt()
    val W = sc.nextInt()
    val w = Array.ofDim[Int](N + 1)
    val v = Array.ofDim[Int](N + 1)
    val w1 = sc.nextInt()
    v(1) = sc.nextInt()
    (2 to N) foreach { i =>
      w(i) = sc.nextInt() - w1
      v(i) = sc.nextInt()
    }

    val dp = Array.ofDim[Int](N + 1, N + 1, 3 * N + 1)
    for {
      i <- 1 to N
      j <- 0 to i  // 選んだ個数
      k <- 0 to 3 * i // w1との差
    } {
      val pre_k = k - w(i)
      dp(i)(j)(k) =
        if (j >= 1 && pre_k >= 0) max(dp(i - 1)(j - 1)(pre_k) + v(i), dp(i -1)(j)(k))
        else dp(i -1)(j)(k)
    }

    val ans = (for {
      j <- 0 to N
      k <- 0 to 3 * N
      if j.toLong * w1 + k <= W
    } yield dp(N)(j)(k)).max
    println(ans)
  }

  def main(args: Array[String]): Unit = {
    solve()
  }



  private class InputReader(val stream: InputStream) {
    private val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer = null

    def next: String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = next.toInt
    def nextLong(): Long = next.toLong
    def nextChar(): Char = next.charAt(0)
  }

}

