int main(){
    ll n, w;
    cin >> n >> w;
    vector<p> vp;
    ll MIN = 1e+11, MAX = 0;
    for(ll i = 0; i < n; i++){
        ll a, b;
        cin >> a >> b;
        vp.push_back(p(a, b));
        MAX = max(MAX, a); MIN = min(MIN, a);
    }
    vector<ll> x, y, z;
    for(ll i = 0; i < n; i++){
        if(vp[i].first==MAX) x.push_back(vp[i].second);
        else if(vp[i].first==MIN) z.push_back(vp[i].second);
        else  y.push_back(vp[i].second);
    }
    sort(x.begin(), x.end(), greater<ll>());
    sort(y.begin(), y.end(), greater<ll>());
    sort(z.begin(), z.end(), greater<ll>());
    //cout << x.size() << " " << y.size() <<" " << z.size() << endl;
    vector<p> a, b, c;
    a.push_back(p(0,0)); b.push_back(p(0,0)); c.push_back(p(0,0));
    for(ll i = 0; i < x.size(); i++){
        if(i==0) a.push_back(p((i+1)*MAX, x[i]));
        else  a.push_back(p((i+1)*MAX, a[i].second+x[i]));
    }
    for(ll i = 0; i < y.size(); i++){
        if(i==0) b.push_back(p((i+1)*(MIN+1), y[i]));
        else  b.push_back(p((i+1)*(MIN+1), b[i].second+y[i]));
       // cout << b[i].first << " " << b[i].second << endl;
    }
    for(ll i = 0; i < z.size(); i++){
        if(i==0) c.push_back(p((i+1)*MIN, z[i]));
        else  c.push_back(p((i+1)*MIN, c[i].second+z[i]));
        //cout << c[i].first << " " << c[i].second << endl;
    }
    ll ans = 0;
   // cout << a.size() << " " << b.size() << " " << c.size() << endl;
    for(ll i = 0; i < a.size(); i++){
        for(ll j = 0; j < b.size(); j++){
            for(ll k = 0; k < c.size(); k++){
                //cout << i << " " << j << " " << k << " " <<  a[i].second+b[j].second+c[k].second << endl;
                if(a[i].first+b[j].first+c[k].first <= w)
                    ans = max(ans, a[i].second+b[j].second+c[k].second);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

