typedef long long ll;
typedef pair<ll, ll> P;

int n;
ll w_max;
vector<ll> w;
vector<ll> v;
vector<P> plist;



int main()
{
	cin >> n >> w_max;

	for (int i = 0; i < n; i++) {
		ll tmpw, tmpv;
		cin >> tmpw >> tmpv;
		w.push_back(tmpw);
		v.push_back(tmpv);
		plist.push_back(P(tmpv,tmpw));
	}

	if (w[0]>w_max) {
		cout << 0 << "\n";
		return 0;
	}

	sort(plist.begin(),plist.end());

	ll idx = 0;
	ll ret = 0;
	while (true) {
		if (w_max>=(w[0]+3+3)) {
			ret += plist[idx].first;
			w_max -= plist[idx].second;
			idx++;
		} else {
			break;
		}
		if (idx==n) {
			cout << ret << "\n";
			return 0;
		}
	}
	ll nn = n-idx;
	ll W = w_max;
//	cout << "d_: " << w_max << " " << nn << endl;

	ll dp[nn+1][W+1];
	for (ll i = 0; i <= nn; i++) {
		for (ll j = 0; j <= W; j++) {
			dp[i][j] = 0;
		}
	}
	for (ll i = 1; i <= nn; i++) {
		for (ll j = 1; j <= W; j++) {
			if (j<plist[idx+i-1].second) {
				dp[i][j] = dp[i-1][j];
			} else {
				dp[i][j] = max(dp[i-1][j], dp[i-1][j-plist[idx+i-1].second]+plist[idx+i-1].first);
			}
		}
	}

	// for (ll i = 0; i <= n; i++) {
	// 	for (ll j = 0; j <= W; j++) {
	// 		cout << dp[i][j] << " ";
	// 	}
	// 	cout  << "\n";
	// }


	ret += dp[nn][W];
	cout << ret << "\n";

}

