int main()
{
    int n, bag;
    cin >> n >> bag;
    vector<int> w(n), v(n);
    for(int i=0; i<n; ++i)
        cin >> w[i] >> v[i];

    vector<vector<long long> > dp(n+1, vector<long long>(3*n+1, -INF));
    dp[0][0] = 0;
    for(int i=0; i<n; ++i){
        for(int a=n; a>=0; --a){
            for(int b=0; b<=3*n; ++b){
                if(dp[a][b] >= 0){
                    int b2 = b + w[i] - w[0];
                    dp[a+1][b2] = max(dp[a+1][b2], dp[a][b] + v[i]);
                }
            }
        }
    }

    long long ans = -INF;
    for(int a=0; a<=n; ++a){
        for(int b=0; b<=3*n; ++b){
            if(a * w[0] + b <= bag)
                ans = max(ans, dp[a][b]);
        }
    }
    cout << ans << endl;

    return 0;
}

