ll N, W;
ll w[110], v[110];
//wは最大で４種類
//よって重さw1,w2,w3,w4の重りを何個使うか元から決めて全探索する。
//各重さごとに価値の高い順に使う
//
int main() {
	cin >> N >> W;
	vector<vector<int>>V;
	V.resize(4);
	REP(i, N) {
		cin >> w[i] >> v[i];
	}
	V[0].push_back(v[0]);
	for (int i = 1; i < N; ++i) {
		if (w[i] == w[0]) {
			V[0].push_back(v[i]);
		}
		else if (w[i] == w[0] + 1) {
			V[1].push_back(v[i]);
		}
		else if (w[i] == w[0] + 2) {
			V[2].push_back(v[i]);
		}
		else {
			V[3].push_back(v[i]);
		}
	}
	for (int i = 0; i < 4; ++i) {
		sort(V[i].begin(), V[i].end(), greater<int>());
	}
	vector<vector<ll>>sum;
	REP(i, 4)sum[i].push_back(0);
	for (int i = 0; i < 4; ++i) {
		for (int j = 0; j < V[i].size(); ++i) {
			sum[i].push_back(sum[i][j] + V[i][j]);
		}
	}
	ll ans = 0;
	for (int i = 0; i <= V[0].size(); ++i) {
		for (int j = 0; j <= V[1].size(); ++j) {
			for (int k = 0; k <= V[2].size(); ++k) {
				for (int l = 0; l <= V[3].size(); ++l) {
					ll x = w[0] * i + (w[0] + 1)*j + (w[0] + 2)*k + (w[0] + 3)*l;
					if (x > W)continue;
					ll key = sum[0][i] + sum[1][j] + sum[2][k] + sum[3][l];
					ans = max(ans, key);
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

