int main(){
  ll N,W; cin>>N>>W;
  vector<ll> A(1,0),B(1,0),C(1,0),D(1,0);
  ll w1,v1; cin>>w1>>v1; A.emplace_back(v1);
  for(ll i=1; i<N; i++){
    ll a,b; cin>>a>>b;
    if(a==w1) A.emplace_back(b);
    else if(a==w1+1) B.emplace_back(b);
    else if(a==w1+2) C.emplace_back(b);
    else if(a==w1+3) D.emplace_back(b);
  }
  sort(A.begin(), A.end(), greater<ll>());
  sort(B.begin(), B.end(), greater<ll>());
  sort(C.begin(), C.end(), greater<ll>());
  sort(D.begin(), D.end(), greater<ll>());
  //累積和にする
  ll asz=A.size(), bsz=B.size(), csz=C.size(), dsz=D.size();
  for(ll i=1; i<asz; i++) A[i]+=A[i-1];
  for(ll i=1; i<bsz; i++) B[i]+=B[i-1];
  for(ll i=1; i<csz; i++) C[i]+=C[i-1];
  for(ll i=1; i<dsz; i++) D[i]+=D[i-1];
  ll ans=0;
  for(ll a=0; a<asz; a++){
    for(ll b=0; b<bsz; b++){
      for(ll c=0; c<csz; c++){
        for(ll d=0; d<dsz; d++){
          ll w=a*w1+b*(w1+1)+c*(w1+2)+d*(w1+3);
          if(w>W) continue;
          ll val=0;
          if(a>0) val+=A[a-1];
          if(b>0) val+=B[b-1];
          if(c>0) val+=C[c-1];
          if(d>0) val+=D[d-1];
          ans=max(ans,val);
        }
      }
    }
  }
  cout<<ans<<endl;
}

