using namespace std;

int N, W;
int w0;
int w[100];
int v[100];
int dp[100 + 1][300 + 1][100 + 1];
int ERROR = -1000000000000;
int INIT =  -10000000000000000;

int func(int i, int j, int k) //i番目までのものを使って強度の総和がj以下となるように選ぶ、ただし全部でk個使う
{
	if (k < 0)
	{
		return ERROR;
	}
	if (i < 0 && k > 0)
	{
		return ERROR;
	}
	if (i < 0)
	{
		return 0;
	}
	if (j < 0)
	{
		return ERROR;
	}
	if (dp[i][j][k] > INIT)
	{
		return dp[i][j][k];
	}
	if (j < w[i])
	{
		return func(i - 1, j, k);
	}

	int a = func(i - 1, j, k);
	int b = func(i - 1, j - w[i], k - 1) + v[i];
	int res = MAX(a, b);
	dp[i][j][k] = res;
	return res;
}

