typedef long long LL;

LL KnapSackDP(LL wt[], int val[], int W, int n)
{
    LL K[n + 1][W + 1];

    for (int i = 0; i <= n; i++)
    {
        for (LL w = 0; w <= W; w++)
        {
            if (!w || !i)
                K[i][w] = 0;

            else if (wt[i - 1] <= w)
                K[i][w] = max(val[i - 1] + K[i - 1][w - wt[i - 1]], K[i - 1][w]);
            else
                 K[i][w] = K[i - 1][w];
        }
    }

    return K[n][W];
}

