int main(int argc, char const *argv[]) {
	ios_base::sync_with_stdio(false);
	cin >> n >> wmax;
	map<int, int> mp;

	ll w0, v0;
	cin >> w0 >> v0;
	mp[0]++;
	value[0].push(v0);
	FOR(i, n-1) {
		ll w, v;
		cin >> w >> v;
		w -= w0;
		value[w].push(v);
		mp[w]++;
	}
	ll dp[mp[0]+1][mp[1]+1][mp[2]+1][mp[3]+1];
	dp[0][0][0][0] = 0;
	int i0 = 0, i1 = 0, i2 = 0, i3 = 0;
	FOR(i0, mp[0]+1) {
		if (i0 > 0) {
			dp[i0][i1][i2][i3] = dp[i0-1][i1][i2][i3] + value[0].top();
			value[0].pop();
		}
		FOR(i1, mp[1]+1) {
			if (i1 > 0) {
				dp[i0][i1][i2][i3] = dp[i0][i1-1][i2][i3] + value[1].top();
				value[1].pop();	
			}
			FOR(i2, mp[2]+1) {
				if (i2 > 0) {
					dp[i0][i1][i2][i3] = dp[i0][i1][i2-1][i3] + value[2].top();
					value[2].pop();	
				}
				FOR(i3, mp[3]+1) {
					if (i3 > 0) {
						dp[i0][i1][i2][i3] = dp[i0][i1][i2][i3-1] + value[3].top();
						value[3].pop();
					}
				}
			}
		}
	}
	ll ma = 0;
	FOR(i0, mp[0]+1) {
		FOR(i1, mp[1]+1) {
			FOR(i2, mp[2]+1) {
				FOR(i3, mp[3]+1) {
					if (i0*w0 + i1*(w0+1) + i2*(w0+2) + i3*(w0+3) <= wmax) {
						ma = max(ma, dp[i0][i1][i2][i3]);
					}
				}
			}
		}
	}
	cout << ma << endl;
	return 0;
}

