int dp(int layer, int curw, vector<int> vis) {
  int& ans = d[curw];
  if (ans >= 0) { return ans; }
  if (layer < 0) { return 0;}
  ans = 0;
  for (int i = 0; i < n; i++) {
    if (curw - ws2[i] >= 0 && vis[i] == 0) {
      vis[i] = 1;
      ans = max(dp(layer-1, curw, vis), dp(layer-1, curw - ws2[i], vis) + vs2[i]);
    }
  }
  return ans;
}

