	LL w,c;
}num[maxn+5];
bool cmp(point a,point b){
	if(a.w==b.w) return a.c > b.c;
	else return a.w < b.w;
}
void Dfs(char x){
	if(c > ans) ans = c;
	for(int i = 0;i<n;i++){
		if(!vis[i]){
			sum += num[i].w;
			c += num[i].c;
			if(sum > w){
				sum -= num[i].w;
				c -= num[i].c;
				break;
			}
			vis[i] = 1;
			Dfs(x + 1);
			vis[i] = 0;
			sum -= num[i].w;
			c -= num[i].c;
		}
		if(x == 'a')
			vis[i] = 1;
	}
}
