					alv = 0;
					if (i) alv += V[0][i - 1];
					if (j) alv += V[1][j - 1];
					if (k) alv += V[2][k - 1];
					if (l) alv += V[3][l - 1];
					//cout << alv << endl;
					ans = max(ans, alv);
				}
			}
		}
	}
	cout << ans << endl;
}

