long long high[5][MAIN];
long long hand[5];
long long que[5][MAIN];
bool cmp(const long long &a,const long long &b)
{
    return a>b;
}
int main()
{
    SCC(n,c);
    num=0;
    CL(hand,0);
    CL(high,0);
    CL(que,0);
    FF(i,1,n)
    {
        SCC(w[i],v[i]);
        if(!num)
        {
            num++;
            wei[num]=w[i];
            hand[num]++;
            high[num][hand[num]]=v[i];
        }
        else
        {
            int judge=0;
            FF(j,1,num)
            {
                if(wei[j]==w[i])
                {
                    judge=j;
                    break;
                }
            }
            if(!judge)
            {
                num++;
                wei[num]=w[i];
                hand[num]++;
                high[num][hand[num]]=v[i];
            }
            else
            {
                hand[judge]++;
                high[judge][hand[judge]]=v[i];
            }
        }
    }
    FF(i,1,num)
        sort(high[i]+1,high[i]+hand[i]+1,cmp);
    FF(i,1,num)
    {
        FF(j,1,hand[i])
        {
            if(j==1) que[i][j]=high[i][j];
            else que[i][j]=que[i][j-1]+high[i][j];
        }
    }
    long long ans=0;
    FF(i,0,hand[1])
    {
        if(num==1)
        {
            if(i*wei[1]<=c) ans=max(ans,que[1][i]);
            continue;
        }
        FF(j,0,hand[2])
        {
            if(num==2)
            {
                if(i*wei[1]+j*wei[2]<=c) ans=max(ans,que[1][i]+que[2][j]);
                continue;
            }
            FF(k,0,hand[3])
            {
                if(num==3)
                {
                    if(i*wei[1]+j*wei[2]+k*wei[3]<=c) ans=max(ans,que[1][i]+que[2][j]+que[3][k]);
                    continue;
                }
                FF(h,0,hand[4])
                    if(i*wei[1]+j*wei[2]+k*wei[3]+h*wei[4]<=c) ans=max(ans,que[1][i]+que[2][j]+que[3][k]+que[4][h]);
            }
        }
    }
    PR(ans);
    return 0;
}

