const int N = 105;
const int M = 305;
int n, v[N], dp[N][N][M];
ll total, w[N];

void update(int &x, int y) { if (x == -1 || x < y) x = y; }

int main() {
	scanf("%d%lld", &n, &total);
	for (int i = 1; i <= n; ++i) scanf("%lld%d", &w[i], &v[i]);
	memset(dp, -1, sizeof(dp));
	dp[0][0][0] = 0;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			for (int k = 0; k < M-5; ++k) {
				if (dp[i][j][k] == -1) continue;
				update(dp[i + 1][j][k], dp[i][j][k]);
				if (k + w[i + 1] - w[1] < M-5)
					update(dp[i + 1][j + 1][k + w[i + 1] - w[1]], dp[i][j][k] + v[i + 1]);
			}
		}
	}
	int res = -1;
	for (int j = 0; j <= n; ++j) for (int k = 0; k <= M-5; ++k)
		if (w[1] * (ll)j + (ll)k <= total)
			update(res, dp[n][j][k]);
	printf("%d", res);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
using ll=long long;
const ll mn=107;
const ll mnn=407;
ll w[mn];
ll v[mn];
ll dp[mn][mnn];
ll dp2[mn][mnn];

int main(){
	ll N,W;cin>>N>>W;
	ll wfirst=-1;
	for(ll a=0;a<N;++a){
		cin>>w[a]>>v[a];
		if(wfirst==-1)wfirst=w[a];
		w[a]-=(wfirst-1);
	}
	for(ll a=0;a<N;++a){
		for(ll b=0;b<mnn;++b){
			if(w[a]>b){
				dp[a+1][b]=dp[a][b];
				dp2[a+1][b]=dp2[a][b];
				continue;
			}
			if(dp[a][b]>=dp[a][b-w[a]]+v[a]){
				dp[a+1][b]=dp[a][b];
				dp2[a+1][b]=dp2[a][b];
			}
			else{
				dp[a+1][b]=dp[a][b-w[a]]+v[a];
				dp2[a+1][b]=dp2[a][b-w[a]]+1;
			}
		}
	}
	ll ret=0;
	for(ll a=0;a<mnn;++a){
		ll W2=W;
		if((W2-(dp2[N][a])*(wfirst-1))>=a)ret=max(ret,dp[N][a]);
	}
	cout<<ret<<endl;
}

