const int maxn = 1e2 + 5;
int n, w;
int a[maxn];
int b[maxn];
long long dp[maxn][maxn * 3];

void solve() {
	cin >> n >> w;
	FOR(i, 0, n) cin >> a[i] >> b[i];
	FOR(l, 0, n) {
		FORd(i, n + 1, 0) FOR(j, 0, 3 * n + 1) {
			chkmax(dp[i + 1][j + a[l] - a[0]], dp[i][j] + b[l]);
		}
	}
	long long ans = 0;
	FOR(l, 1, n + 1) {
		if (w < (long long) a[0] * l) continue;
		FOR(j, 0, min(w - a[0] * l + 1, maxn * 3)) {
			chkmax(ans, dp[l][j]);
		}
	}
	cout << ans << "\n";
}

