#define REP(i, n) for (int i = 0; i < (int)(n); ++i)
#define FOR(i, a, b) for (int i = (a); i < (int)(b); ++i)
#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, w;
    cin >> n >> w;
    vector<vector<ll>> g(4), f(4);
    int idx = 0;
    REP(i, n) {
        int a, b;
        cin >> a >> b;
        if (i == 0)
            idx = a;
        g[a - idx].push_back(b);
    }
    for (auto &x : g) {
        sort(ALLR(x));
    }
    REP(i, 4) {
        ll sum = 0;
        f[i].push_back(0);
        for (auto &x : g[i]) {
            sum += x;
            f[i].push_back(sum);
        }
    }
    int fin = w / idx + 1;
    ll maxv = 0;
    REP(i, min(fin, (int)f[0].size()))
    REP(j, min(fin, (int)f[1].size()))
    REP(k, min(fin, (int)f[2].size())) REP(l, min(fin, (int)f[3].size())) {
        ll weight = i * idx + j * (idx + 1) + k * (idx + 2) + l * (idx + 3);
        ll value = f[0][i] + f[1][j] + f[2][k] + f[3][l];
        if (weight > w)
            break;
        maxv = max(maxv, value);
    }
    cout << maxv << endl;

    return 0;
}

