    for(int i = 0; i < 110; i++) dp2[i][0] = 0;
    for(int i = 1; i < N; i++){
      for(int j = 0; j <= W; j++){
        if(j - w[i] >= 0) dp2[i][j] = max(dp2[i-1][j-w[i]]+v[i], dp2[i-1][j]);
        else dp2[i][j] = dp2[i-1][j];
      }
    }
    int ma = 0;
    for(int i = 0; i <= W; i++){
      ma = max(dp2[N-1][i], ma);
    }
