    ll sumV =0;
    ll sumW =0;
    for(int i=0;i<N;i++){
        cin >> w[i] >> v[i];
        sumV += v[i];
        sumW += w[i];
    }
    ll standard = w[0];
    for(int i=0;i<N;i++){
        w[i] -= standard;
    }
    if(W>=sumW){
        cout << sumV << endl;
        return 0;
    }

    ll k =1;
    ll s = sumW - standard *N;
    // cerr <<"s=" << s << endl;
    // 先頭i個からj個を選んだ時の最大値;
    ll dp[N+1][N+1][s+1];
    memset(dp,0,sizeof(dp));
    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            if(i<j){
                continue;
            }
            for(int k=0;k<=s;k++){
                if(w[i] >k){
                    dp[i+1][j+1][k] = dp[i][j+1][k];
                }else{
                    dp[i+1][j+1][k] = max(dp[i][j+1][k],dp[i][j][k-w[i]] + v[i]);
                    // cerr << "w[i]=" << w[i] << endl;
