using namespace std;

int DFS(const vector<vector<int> >& ws, int depth, int value, int w, int w0, int W) {
	if (depth >= ws.size()) {
		if (w > W) {
			return 0;
		}
		else {
			return value;
		}
	}
	int res = DFS(ws, depth + 1, value, w, w0, W);
	for (int i = 0; i < ws[depth].size(); ++i) {
		int newW = w + (w0 + depth)*(i+1);
		int newValue = value + ws[depth][i];
		res = max(res, DFS(ws, depth + 1, newValue, newW, w0, W));
	}
	return res;
}

