using Graph = vector<vector<int>>;

vector<bool> seen;
vector<ll> step;
void dfs(const Graph &G, int v , ll now) {
    seen[v] = true; // v を訪問済にする
    step[v] = now;
    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) { 
        if (seen[next_v] && (now+1 >= step[next_v]) ) continue; // next_v が探索済だったらスルー
        dfs(G, next_v, now+1); // 再帰的に探索
    }
}
