int dp(int idx, int take, int curw)
{
	if(curw<0)
		return -1e15;
	if(take==0)
		return 0;
	if(idx==n+1)
		return -1e15;
	int &ans=cache[idx][take][curw];
	if(ans!=-1)
		return ans;
	ans=max(dp(idx+1, take, curw), v[idx] + dp(idx+1, take-1, curw-w[idx]));
	return ans;
}

