using namespace std;
typedef long long LL;
LL wt[101],val[101],W,boss;    //kompresija mi podatak :/
int n,k,o;
int calc1(int k){
    return 3*(k*(k+1))/2+k+1;
}
int sredi(){
    if(o==3*k){
        o=0;
        k++;
    }
    else
        o++;
}
int racun(LL ja){
    int o2=boss%ja;
    if(o2>o)
        return calc1(k-2);
    else
        return calc1(k-2)+1+o-o2;
}
LL P(){
    return (LL)((LL)(k*boss)+o);
}

LL knapSack()
{
    LL i, w;
    LL K[n + 1][calc1(n)];

    for (i = 0; i <= n; i++)
    {
        k=0;
        o=0;
        for (w = 0; w <calc1(n); w++)
        {
            if (i == 0 || w== 0)  // za nulu
                K[i][w] = 0;
            else {
                sredi();
                if (wt[i - 1] <=P())
                    K[i][w]= max(val[i - 1] + K[i - 1][racun(wt[i-1])], K[i - 1][w]);
                else
                    K[i][w] = K[i - 1][w];
            }
        }
    }

    return K[n][W];
}

int main()
{
    scanf("%d %I64d",&n,&W);
    scanf("%I64d %I64d",&wt[0],&val[0]);
    boss=wt[0];
    for(int i=1;i<n;i++){
        scanf("%I64d %I64d",&wt[i],&val[i]);
    }
    printf("%I64d",knapSack());
    return 0;
}
