#include <bits/stdc++.h>
using namespace std;

int main(){
  int N, W; cin >> N >> W;
  vector<int> w(N), v(N);
  for (int i = 0; i < N; i++) {
    cin >> w.at(i) >> v.at(i) ;
  }

  int ans = 0;

  for(int bit = 0; bit < (1 << 2*N); bit++){
    int sum = 0; 
    int weight = 0;
    for(int i = 0; i < N; i++){

      if ((bit & (1 << 2*i)) && (bit & (1 << (2*i + 1)))){
        sum += v.at(i);
        weight += w.at(i);
      }
    }
    if (weight <= W) {
      ans = max(ans, sum);
    }
  }
  cout << ans << endl;
}

