template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}


void solve(istream& in, ostream& out) {
    int n = next<int>(in);
    int W = next<int>(in);
    vector<int> ws(n);
    vector<int> vs(n);
    FOR(i, n) {
        ws[i] = next<int>(in);
        vs[i] = next<int>(in);
    }
    int val = ws[0];
    FOR(i, n) {
        ws[i] -= val;
    }
    auto dp = make_vec<int64>(n + 1, n + 1, 3 * n + 1);
    dp.fill(F3(-1));
    dp(0, 0, 0) = 0;
    FOR(i, n) {
        FOR(j, n) {
            FOR(k, 3 * n + 1) {
                if (dp(i, j, k) != -1) {
                    dp(i + 1, j, k) = max( dp(i + 1, j, k), dp(i, j, k));
                    dp(i + 1, j + 1, k + ws[i]) = max(vs[i] + dp(i, j, k), dp(i + 1, j + 1, k + ws[i]));
                }
            }
        }
    }
    int64 res = 0;
    FOR(j, n + 1) {
        FOR(k, 3 * n + 1) {
            if (dp(n, j, k) != -1) {
                int64 v = val * 1LL * j + k;
                if (v <= W) {
                    res = max(res, dp(n, j, k));
                }
            }
        }
    }
    out << res << endl;
}


