using namespace std;

int SimpleKnapSack(long long w[], int val[], int W, int n)
{
    if (!W || !n)
        return 0;

    if (w[n - 1] > W)
        return SimpleKnapSack(w, val, W, n - 1);

    else
        return (max(val[n - 1] + SimpleKnapSack(w, val, W - w[n - 1], n - 1), SimpleKnapSack(w, val, W, n - 1)));
}

int KnapSackDP(long long wt[], int val[], int W, int n)
{
    int K[n + 1][W + 1];

    for (int i = 0; i <= n; i++)
    {
        for (long long w = 0; w <= W; w++)
        {
            if (!w || !i)
                K[i][w] = 0;

            else if (wt[i - 1] <= w)
                K[i][w] = max(val[i - 1] + K[i - 1][w - wt[i - 1]], K[i - 1][w]);
            else
                 K[i][w] = K[i - 1][w];
        }
    }

    return K[n][W];
}

