#define MAX_N (100)

using namespace std;

int dp[MAX_N + 1][MAX_N + 1][3 * MAX_N + 1] = {};

int main(int argc, char *argv[]) {
  // read inputs
  int N, W, ws[MAX_N], vs[MAX_N];
  scanf("%d %d", &N, &W);
  for (int i = 0; i < N; i++) {
    scanf("%d %d", &ws[i], &vs[i]);
  }

  // subtract w1 from all wis
  const int w0 = ws[0];
  for (int i = 0; i < N; i++) {
    ws[i] -= w0;
  }

  // solve dp
  for (int n = 1; n <= N; n++) {
    for (int i = 0; i < N; i++) {
      const int w_i = ws[i], v_i = vs[i];
      for (int j = 0; j < w_i; j++) {
        dp[n][i + 1][j] = dp[n][i][j];
      }
      for (int j = w_i; j <= 3 * N; j++) {
        dp[n][i + 1][j] = max(dp[n][i][j], dp[n - 1][i][j - w_i] + v_i);
      }
    }
  }

  // print answer
  int ans = 0;
  for (int n = 1; n <= N && W - n * w0 >= 0; n++) {
    ans = max(ans, dp[n][N][W - n * w0]);
  }
  printf("%d\n", ans);

  return 0;
}

