    }
    if(a2 < C[1].size()){
        ans = max(ans , C[1][a2] + dp(a1,a2+1,a3,a4));
    }
    if(a3 < C[2].size()){
        ans = max(ans , C[2][a3] + dp(a1,a2,a3+1,a4));
    }
    if(a4 < C[3].size()){
        ans = max(ans , C[3][a4] + dp(a1,a2,a3,a4+1));
    }

    M[h] = ans;
