void solve() {
    i64 N; RD(N);
    i64 WMAX; RD(WMAX);

    vector<vector<i64>> vs(4);
    i64 w_base; RD(w_base);
    {
        i64 v; RD(v);
        vs[0].emplace_back(v);
    }
    FOR(_, 1, N) {
        i64 w,v; RD(w); RD(v);
        vs[w-w_base].emplace_back(v);
    }
    for(auto& e : vs) {
        ALL(sort, e, greater<>());
    }

    vector<vector<i64>> ss(4);
    REP(i, 4) {
        ss[i] = vector<i64>(SIZE(vs[i])+1, 0);
        ALL(partial_sum, vs[i], begin(ss[i])+1);
    }

    i64 ans = 0;
    FOR(k0, 0, SIZE(vs[0])+1) {
        i64 w0 = w_base*k0;
        if(w0 > WMAX) continue;
        i64 v0 = ss[0][k0];
        FOR(k1, 0, SIZE(vs[1])+1) {
            i64 w1 = (w_base+1)*k1;
            if(w0+w1 > WMAX) continue;
            i64 v1 = ss[1][k1];
            FOR(k2, 0, SIZE(vs[2])+1) {
                i64 w2 = (w_base+2)*k2;
                if(w0+w1+w2 > WMAX) continue;
                i64 v2 = ss[2][k2];
                FOR(k3, 0, SIZE(vs[3])+1) {
                    i64 w3 = (w_base+3)*k3;
                    if(w0+w1+w2+w3 > WMAX) continue;
                    i64 v3 = ss[3][k3];
                    chmax(ans, v0+v1+v2+v3);
                }
            }
        }
    }

    // * 小さいケースで試した?
    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

