  for (int i = 0; i < N; i++) {
    cin >> w.at(i) >> v.at(i) ;
  }
  int omega = w.at(0); 
  vector<vector<int>> ww(4);
  ww.assign(4, vector<int>(1, 0));
  for(int i = 0; i < N; i++) {
    ww.at(w.at(i)-omega).push_back(v.at(i));
  }

  for(int i = 0; i< 4; i++){
    if( ww.at(i).size()> 1)
      sort(ww.at(i).begin()+1, ww.at(i).end(), greater<int>());
  }

  int ans = 0;
  vector<int> curr = {0,0,0,0};
  vector<int> weight = {0,0,0,0};
  for(auto itr1 = begin(ww.at(0)); itr1 != end(ww.at(0)); ++itr1){
    curr.at(0) += *itr1;
    if(*itr1) weight.at(0) += omega;
    curr.at(1) = 0;
    weight.at(1) = 0;
    for(auto itr2 = begin(ww.at(1)); itr2 != end(ww.at(1)); ++itr2){
      curr.at(1) += *itr2;
      if(*itr2) weight.at(1) += omega+1;
      curr.at(2) = 0;
      weight.at(2) = 0;
      for(auto itr3 = begin(ww.at(2)); itr3 != end(ww.at(2)); ++itr3){
        curr.at(2) += *itr3;
        if(*itr3) weight.at(2) += omega+2;
        curr.at(3) = 0;
        weight.at(3) = 0;
        for(auto itr4 = begin(ww.at(3)); itr4 != end(ww.at(3)); ++itr4){
          curr.at(3) += *itr4;
          if(*itr4)  weight.at(3) += omega+3;
          if (accumulate(weight.begin(), weight.end(), 0) <= W ){
            ans = max(ans,accumulate(curr.begin(), curr.end(), 0));
        }
        }
      }

    }

  }
  cout << ans << endl;
}

#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const int N = 50;
const long long INF = 0x3fffffff;
typedef long long LL;
int n;
LL w[N], v[N];
LL W;
pair <LL, LL> pi[1 << (N / 2)];

void solve() {
    int n2 = n / 2;
    for(int i = 0; i < (1 << n2); i++) {
        LL sw = 0, sv = 0;
        for(int j = 0; j < n2; j++) {
            if((i >> j) & 1) {
                sw += w[j];
                sv += v[j];
            }
        }
        pi[i] = make_pair(sw, sv);
    }

    sort(pi, pi + (1 << n2));
    int m = 1;
    for(int i = 1; i < (1 << n2); i++) {
        if(pi[m-1].second < pi[i].second) {
            pi[m++] = pi[i];
        }
    }

    LL res = 0;
    for(int i = 0; i < (1 << (n - n2)); i++) {
        LL sw = 0, sv = 0;
        for(int j = 0; j < n - n2; j++) {
            if((i >> j) & 1) {
                sw += w[n2 + j];
                sv += v[n2 + j];
            }
        }
        if(sw <= W) {
            LL tv = (lower_bound(pi, pi + m, make_pair(W - sw, INF)) - 1)->second;
            res = max(res, sv + tv);
        }
    }
    printf("%lld\n", res);
}

int main() {
    while(~scanf("%d%lld", &n, &W)) {
        for(int i = 0; i < n; i++) {
            scanf("%lld%lld", &w[i], &v[i]);
        }
        solve();
    }
    return 0;
}

