vector<int> res[4];
int w, n, W;
int ans;
void solve(ll i, ll j, ll k)
{
  ll tot = (i+j+k)*2+j+2*k;
  if (tot > W)
    return;
  ll left = W-tot;
  ll l = min((ll)res[3].size()-1, left/(w+3));
  ans = max(ans, res[0][i]+res[1][j]+res[2][k]+res[3][l]);
}
int main()
{
  scanf("%d %d", &n, &W);
  int a, b;
  scanf("%d %d", &a, &b);
  for (int i = 0; i < 4; ++i)
    res[i].push_back(0);
  w = a;
  res[0].push_back(b);
  for (int i = 1; i < n; ++i)
    {
      scanf("%d %d", &a, &b);
      res[a-w].push_back(b);
    }
  for (int i = 0; i < 4; ++i)
    {
      sort(res[i].begin(), res[i].end());
      for (int j = 1; j < res[i].size(); ++j)
	res[i][j] += res[i][j-1];
    }
  ans = 0;
  for (int i = 0; i < res[0].size(); ++i)
    {
      for (int j = 0; j < res[1].size(); ++j)
	{
	  for (int k = 0; k < res[2].size(); ++k)
	    {
	      solve(i, j, k);
	    }
	}
    }
  printf("%d\n", ans);
}

