long trace(const vector<vector<long>>& values, long W, long w)
{
  vector<vector<long>> sums(4);
  for (int i = 0; i < 4; ++i) {
    sums[i].push_back(0);
    for (int j = 0; j < values[i].size(); ++j) {
      sums[i].push_back(sums[i][j] + values[i][j]);
    }
  }
  long max_w = 0;
  for (int c3 = values[3].size(); c3 >= 0; --c3) {
    auto w3 = c3 * (w + 3);
    if (w3 > W) continue;
    for (int c2 = values[2].size(); c2 >= 0; --c2) {
      auto w2 = c2 * (w + 2);
      if (w3 + w2 > W) continue;
      for (int c1 = values[1].size(); c1 >= 0; --c1) {
        auto w1 = c1 * (w + 1);
        if (w3 + w2 + w1 > W) continue;
        for (int c0 = values[0].size(); c0 >= 0; --c0) {
          auto w0 = c0 * w;
          if (w3 + w2 + w1 + w0 > W) continue;
          long w = sums[0][c0] + sums[1][c1] + sums[2][c2] + sums[3][c3];
          if (max_w < w) max_w = w;
        }
      }
    }
  }
  return max_w;
}


