					f[i][j][k] = f[i - 1][j][k];
			for (int j = 1; j <= i; j++)
				for (int k = v[i] - v[1]; k <= sum; k++)
					f[i][j][k] = max(f[i - 1][j][k], f[i - 1][j - 1][k - (v[i] - v[1])] + w[i]);
