int n, W;

int w[111], v[111];

ll ans;

vector <ll> it[4], sum[4];

void calc(int id) {
    sum[id].resize(it[id].size() + 1);
    sum[id][0] = 0;
    for (int i = 1; i <= (int)it[id].size(); ++i) {
        sum[id][i] = sum[id][i - 1] + it[id][i - 1];
    }
}

void relax(int i1, int i2, int i3, int i4) {
    if (i1 > (int)it[0].size())
        return;
    if (i2 > (int)it[1].size())
        return;
    if (i3 > (int)it[2].size())
        return;
    if (i4 > (int)it[3].size())
        return;
    ll cur = sum[0][i1] + sum[1][i2] + sum[2][i3] + sum[3][i4];
    ll ww = w[0] * 1LL * i1 + ((w[0] + 1) * 1LL * i2) + ((w[0] + 2) * 1LL * i3) + ((w[0] + 3) * 1LL * i4);
    if (cur > ans && ww <= W)
        ans = cur;
}

