long long dpV[101][301][303];

long long calc(int depth,int space, int cap) {
	long long& V = dpV[depth][space][cap];
	long long result = 0;
	if (V != -1)return V;
	else if (depth == N - 1) {
		if (space) {
			if (cap >= itemW[depth]) {
				return V = itemV[depth];
			}
			else if (space >= 2) {
				return V = calc(depth, space - 1, min(cap + Wbase, 300));
			}
		}
		else {
			return (V=0);
		}
	}
	else {
		if (space) {
			if (cap >= itemW[depth]) {
				result = itemV[depth] + calc(depth + 1, space - 1, cap - itemW[depth]);
			}
			else  if (space >= 2) {
				result = calc(depth, space - 1, min(cap + Wbase, 300));
			}
		}
		else result = 0;
		return V = max(calc(depth + 1, space, cap), result);
	}
}
