			dp_n[0][j] = 0;
		}
		for (i = 0; i < N + 1; i++){
			dp[i][0] = 0;
			dp_n[i][0] = 0;
		}
		for (i = 1; i < N + 1; i++){
			for (j = 1; j < mW + 1; j++){
				if (w[i - 1]-w[0] <= j){
					dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - w[i - 1] - w[0]] + v[i - 1]);
					if (dp[i - 1][j] < dp[i - 1][j - w[i - 1] - w[0]] + v[i - 1]){
						dp_n[i][j] = dp_n[i - 1][j - w[i - 1] - w[0]] + 1;
					}
					else{
						dp_n[i][j] = dp_n[i - 1][j];
					}
