int sums[4][MAX_N];
vector< int > values[4];

int calc_value(int cnt, int w) {
	return sums[w][values[w].size() - cnt];
}

int main() {
	int n, w;
	scanf(" %d %d", &n, &w);

	int delta;
	for(int i = 0; i < n; i++) {
		int weight, value;
		scanf(" %d %d", &weight, &value);

		if(i == 0) {
			delta = weight;
		}

		values[weight - delta].pb(value);
	}

	for(int i = 0; i <= 3; i++) {
		sort(values[i].begin(), values[i].end());

		sums[i][values[i].size()] = 0;
		for(int j = values[i].size() - 1; j >= 0; j--) {
			sums[i][j] = sums[i][j + 1] + values[i][j];
		}
	}

	int ans = 0;
	for(int a = 0; a <= values[0].size(); a++) {
		for(int b = 0; b <= values[1].size(); b++) {
			for(int c = 0; c <= values[2].size(); c++) {
				for(int d = 0; d <= values[3].size(); d++) {
					if(1ll * delta * a + 1ll * (delta + 1) * b + 1ll * (delta + 2) * c + 1ll * (delta + 3) * d <= 1ll * w) {
						ans = max(ans, calc_value(a, 0) + calc_value(b, 1) + calc_value(c, 2) + calc_value(d, 3));
					}
				}
			}	
		}
	}

	printf("%d\n", ans);
	return 0;
