long long val(int a,int b,int c,int d){
  long long sum=0;
  for(int i=1;i<=a;i++){
    sum=sum+vec[0][i-1];
  }
  for(int i=1;i<=b;i++){
    sum=sum+vec[1][i-1];
  }
  for(int i=1;i<=c;i++){
    sum=sum+vec[2][i-1];
  }
  for(int i=1;i<=d;i++){
    sum=sum+vec[3][i-1];
  }
  return sum;
}

int main(){
  long long N,W; cin >> N >> W;
  long long w_1,v_1; cin >> w_1 >> v_1;
  vec[0].push_back(v_1);
  for(int i=2;i<=N;i++){
    long long w,v; cin >> w >> v;
