  }
  for(int i=0;i<4;i++) sort(vec[i].begin(),vec[i].end(),greater<int>());
  long long ans=0;
  for(int a=0;a<=vec[0].size();a++){
    for(int b=0;b<=vec[1].size();b++){
      for(int c=0;c<=vec[2].size();c++){
        for(int d=0;d<=vec[3].size();d++){
          if(a*w_1+b*(w_1+1)+c*(w_1+2)+d*(w_1+3)<=W){
            long long v=val(a,b,c,d);
            ans=max(ans,v);
          }
        }
      }
    }
  }
  cout << ans << endl;
}

