#include <bits/stdc++.h>
using namespace std;
#define int long long
// 商品の重さの種類
constexpr int N = 4;
// 商品の数、ナップサックの許容重さ
int n, total_w;
// 最初の商品の重さ -1は数値代入前を意味する
int w1 = -1;
// それぞれ重さ{w1,w1+1,w1+2,w1+3}の商品の価値
array<vector<int>, N> goods;

// 現在重さwgt, 現在価値val、重さ{w1,w1+1,w1+2,w1+3}の商品をgs詰めたナップサックが取りうる最大価値を返す
int dfs(int wgt, int val, array<int, N> gs)
{
    // 重さ超過
    if (wgt > total_w)
        return -1;

    int max_rtn_val = val;

    // ナップサックに{w1,w1+1,w1+2,w1+3}の商品を一つつめたときの最大価値を再帰探索
    for (int i = 0; i < N; i++)
    {
        // 重さw1+iの商品はもう無い
        if (gs[i] >= goods[i].size())
            continue;

        auto ngs = gs;
        ngs[i]++;
        int rtn_val = dfs(wgt + w1 + i, val + goods[i][gs[i]], ngs);
        max_rtn_val = max(rtn_val, max_rtn_val);
    }

    return max_rtn_val;
}

signed main()
{
    cin.tie(0);
    ios::sync_with_stdio(0);
    cout << fixed << setprecision(16);

    cin >> n >> total_w;
    for (auto &&x : goods)
        x.reserve(n);

    // goods配列に重さ毎の価値をプッシュ
    for (int i = 0; i < n; i++)
    {
        int w, v;
        cin >> w >> v;
        if (w1 < 0)
            w1 = w;

        goods[w - w1].push_back(v);
    }

    // 価値降順にソート
    for (auto &&x : goods)
    {
        sort(x.rbegin(), x.rend());
    }

    const int ans = dfs(0, 0, {0, 0, 0, 0});

    cout << ans << endl;
}

