const int MAXN = 110;

int N;
ll W;
ll wm;
pair <int, int> p[MAXN];

vector <int> v[4];

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> N >> W;
    for (int i = 0; i < N; i++)
    {
        cin >> p[i].first >> p[i].second;
    }

    wm = p[0].first;
    for (int i = 0; i < N; i++)
    {
        p[i].first -= wm;
        v[p[i].first].push_back(p[i].second);
    }

    int pt = 1;
    for (int i = 0; i < 4; i++)
    {
        sort (v[i].begin(), v[i].end());
        reverse (v[i].begin(), v[i].end());
        pt *= v[i].size() + 1;
    }

    ll ans = 0;
    for (int z = 0; z < pt; z++)
    {
        int tz = z;
        ll ttot = W;
        ll bval = 0;
        for (int i = 0; i < 4; i++)
        {
            int ng = tz % (v[i].size() + 1);
            ttot -= ng * (wm + i);
            for (int j = 0; j < ng; j++)
                bval += v[i][j];

            tz /= (v[i].size() + 1);
        }
        if (ttot >= 0) ans = max (ans, bval);
    }
    cout << ans << "\n";
}

