int N, G;
int V[105], W[105];
int w;
int DP[105][105][405];
void Read()
{
    cin >> N >> G;
    for(int i = 1; i <= N; i++)
        cin >> W[i] >> V[i];
    w = W[1];
    for(int i = 1; i <= N; i++)
        W[i] -= w - 1;
}

void Solve()
{
    memset(DP, -1, sizeof(DP));
    DP[0][0][0] = 0;
    int g = 4 * N;
    for(int i = 1; i <= N; i++)
    {
        DP[i][0][0] = 0;
        for(int j = 1; j <= N; j++)
        {
            for(int k = 1; k <= g; k++)
                DP[i][j][k] = DP[i - 1][j][k];
            for(int k = W[i]; k <= g; k++)
            {
                int val = DP[i - 1][j - 1][k - W[i]];
                if(val == -1)
                    continue;
                DP[i][j][k] = max(DP[i][j][k], val + V[i]);
            }
        }
    }
    int ans = 0;
    for(int i = 1; i <= N; i++)
        for(int j = 1; j + (w - 1) * i <= G && j <= g; j++)
        {
            ans = max(ans, DP[N][i][j]);
        }
    cout << ans << "\n";
}
int main()
{
    Read();
    Solve();
    return 0;
}

