using namespace std;
typedef long long ll;
typedef pair<ll, ll> pll;

int main() {
    ll N, W;
    cin >> N >> W;
    vector<pll> P(N);

    map<int, int> cnt;
    vector<ll> acc1(1), acc2(1), acc3(1), acc4(1);

    for(int i = 0; i < N; i++) {
        int w, v;
        cin >> w >> v;
        P[i] = {w, -v};
        cnt[w]++;
    }
    vector<int> ws;
    for(auto e : cnt) {
        ws.push_back(e.first);
    }

    sort(all(P));
    for(int i = 0; i < N; i++) {
        P[i].second *= -1;
        if (P[i].first == ws[0]) acc1.push_back(acc1.back() + P[i].second);
        if (ws.size() >= 2 && P[i].first == ws[1]) acc2.push_back(acc2.back() + P[i].second);
        if (ws.size() >= 3 && P[i].first == ws[2]) acc3.push_back(acc3.back() + P[i].second);
        if (ws.size() >= 4 && P[i].first == ws[3]) acc4.push_back(acc4.back() + P[i].second);
    }

    ll ans = 0;
    if (ws.size() == 1) {
        int i = min({(ll)acc1.size() - 1, W / ws[0]});
        ans = max(ans, acc1[i]);
    } else if (ws.size() == 2) {
        for(int i = 0; i <= N && i < acc1.size(); i++) {
            if (i * ws[0] > W) continue;
            int j = min({N - i, (ll)acc2.size() - 1, (W - i * ws[0]) / ws[1]});
            ans = max(ans, acc1[i] + acc2[j]);
        }
    } else if (ws.size() == 3) {
        for(int i = 0; i <= N && i < acc1.size(); i++) {
            for(int j = 0; i + j <= N && j < acc2.size(); j++) {
                if (i * ws[0] + j * ws[1] > W) continue;
                int k = min({(ll)acc3.size() - 1, N - i - j, (W - i * ws[0] - j * ws[1]) / ws[2]});
                ans = max(ans, acc1[i] + acc2[j] + acc3[k]);
            }
        }
    } else {
        for(int i = 0; i <= N && i < acc1.size(); i++) {
            for(int j = 0; i + j <= N && j < acc2.size(); j++) {
                for(int k = 0; i + j + k <= N && k < acc3.size(); k++) {
                    if (i * ws[0] + j * ws[1] + k * ws[2] > W) continue;
                    int l = min({(ll)acc4.size() - 1, N - i - j - k, (W - (i * ws[0] + j * ws[1] + k * ws[2])) / ws[3]});
                    ans = max(ans, acc1[i] + acc2[j] + acc3[k] + acc4[l]);
                }
            }
        }
    }

    cout << ans << endl;
	return 0;
}

