priority_queue<ll> que[4];
ll sum[4][101];
int N, W, w0;
int sz[4];

void solve() {
	cin >> N >> W;
	for (int i = 0; i < N; i++) {
		int w, v;
		cin >> w >> v;
		if (i == 0) w0 = w;
		que[w - w0].push(v);
	}

	for (int i = 0; i < 4; i++) {
		sz[i] = que[i].size();
	}

	for (int i = 1; i <= sz[0]; i++) {
		sum[0][i] += que[0].top() + sum[0][i-1];
		que[0].pop();
	}
	for (int i = 1; i <= sz[1]; i++) {
		sum[1][i] += que[1].top() + sum[1][i - 1];
		que[1].pop();
	}
	for (int i = 1; i <= sz[2]; i++) {
		sum[2][i] += que[2].top() + sum[2][i - 1];
		que[2].pop();
	}
	for (int i = 1; i <= sz[3]; i++) {
		sum[3][i] += que[3].top() + sum[3][i - 1];
		que[3].pop();
	}

	ll ans = 0LL;

	for(int i = 0; i <= sz[0]; i++)
		for (int j = 0; j <= sz[1]; j++)
			for (int k = 0; k <= sz[2]; k++)
				for (int l = 0; l <= sz[3]; l++) 
					if (W >= i*w0 + j*(w0 + 1) + k*(w0 + 2) + l*(w0 + 3))
						ans = max(ans, (ll)sum[0][i] + sum[1][j] + sum[2][k] + sum[3][l]);

	cout << ans << endl;

}

