#define in std::cin
#define out std::cout
#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

LL N, W, w[112], v[112];
std::pair<LL, LL>res[1 << 20];
LL N2, ans;

int main()
{
	in >> N >> W;
	rep(i, N) { in >> w[i] >> v[i]; }

	N2 = N / 2;
	rep(i, (1 << N2))
	{
		LL sum_w = 0, sum_v = 0;
		rep(j, N2)
		{
			if (i >> j & 1) { sum_w += w[j], sum_v += v[j]; }
		}
		res[i] = std::make_pair(sum_w, sum_v);
	}
	std::sort(res, res + (1 << N2));
	LL seek = 1;
	for (LL i = 1; i < (1 << N2); ++i)
	{
		if (res[seek - 1].second < res[i].second) { res[seek++] = res[i]; }
	}
	rep(i, (1 << (N - N2)))
	{
		LL sum_w = 0, sum_v = 0;
		rep(j, N - N2)
		{
			if (i >> j & 1)
			{
				sum_w += w[N2 + j];
				sum_v += v[N2 + j];
			}
		}
		if (sum_w <= W)
		{
			LL iter = (std::lower_bound(res, res + seek, std::make_pair(W - sum_w, INF)) - 1)->second;
			ans = std::max(ans, sum_v + iter);
		}
	}

	out << ans << std::endl;
	return 0;
}

