pair<LL, LL> CalSum(vector<pair<LL, LL>> ls, LL count) {
	LL w, v;
	w = v = 0;

	LL i, j, k;
	for (i = 0; i < count; i++) {
		w += ls[i].first;
		v += ls[i].second;
	}

	return make_pair(w, v);
}

pair<LL, LL> CalSum(vector<vector<pair<LL, LL>>> const& ls, VLL count) {
