void bubbleSort(vector<vector<int>> & vec, int N)
{
    int temp_0, temp_1;
    for (int i = 0; i < (N - 1); i++) 
    {
        for (int j = (N - 1); j > i; j--) 
        {
            //if (vec[j-1] > vec[j]) {
            if ((vec[j-1][1]/vec[j-1][0]) > (vec[j][1]/vec[j][0])) {
                temp_0 = vec[j-1][0];
                temp_1 = vec[j-1][1];
                vec[j-1][0] = vec[j][0];
                vec[j-1][1] = vec[j][1];
                vec[j][0] = temp_0;
                vec[j][1] = temp_1;

            }

        }

    }
    //for(int i = 0; i < N; i++)
    //{
    //    cout << vec[i][0] << " " <<  vec[i][1] <<endl;
