{
    int  n,W;

    scanf("%d%d",&n,&W);

    int val[n],wt[n];

    for(int i = 0;i < n;i++)
        scanf("%d%d",&wt[i],&val[i]);
    printf("%d", knapSack(W, wt, val, n));
    return 0;
}

