			for(ll k=0;k<=int(t[2].size());++k){
				if(k) sum[2]+=t[2][k-1];
				sum[3]=0;
				for(ll g=0;g<=int(t[3].size());++g){
					if(g) sum[3]+=t[3][g-1];
					ll weights=i*w0+j*(w0+1LL)+k*(w0+2LL)+g*(w0+3LL);
					if(weights<=W)
						res=max(res,sum[0]+sum[1]+sum[2]+sum[3]);
				}
			}
		}
	}
	cout<<res<<'\n';
}

