void solve(){
	int N;
	LL Wmax;
	cin >> N >> Wmax;
	vector<LL> W(N),V(N);
	for(int i=0;i<N;++i){
		cin >> W[i] >> V[i];
	}
	LL Wbase = W[0]-1;
	for(int i=0;i<N;++i){
		W[i] -= Wbase;
	}
	//int WLim = Wmax-Wbase;
	int WLim = 3*N;
	vector<vector<LL> > dp(N+1,vector<LL>(WLim+1,-1));//中に価値
	dp[0][0] = 0;
	for(int i=0;i<N;++i){
		for(int k=N;k>=0;--k){
			for(int w=WLim;w>=0;--w){
				if( dp[k][w] < 0 ) continue;
				LL temp = Wbase*k+ w;
				if( temp >= Wmax ) continue;
				dp[k+1][w+W[i]] = max(dp[k+1][w+W[i]],dp[k][w]+V[i]);
			}
		}
	}
	LL ans =0;
	for(int k=0;k<=N;++k){
		for(int i=0;i<=WLim;++i){
			LL temp = Wbase*k + i;
			if( temp <= Wmax ){
				ans = max(ans,dp[k][i]);
			}
		}
	}
	cout << ans << endl;
}

