int main() {
    int n, wmax;
    cin >> n >> wmax;
    vector<int> w(n), v(n);
    int w0;
    int kmax = 0;
    for (int i = 0; i < n; ++i) {
        cin >> w[i] >> v[i];

        if (i == 0)
            w0 = w[0];

        w[i] -= w0;
        kmax += w[i];
    }

    vector<vector<vector<int>>> dp(n, vector<vector<int>>(n + 1, vector<int>(4 * n)));
    for (int i = 0; i < n; ++i) {
        for (int j = 1; j <= i + 1; ++j) {
            for (int k = 0; k < 4 * n; ++k) {
                if (i > 0) {
                    if (k - w[i] >= 0) {
                        dp[i][j][k] = max(dp[i - 1][j][k], dp[i - 1][j - 1][k - w[i]] + v[i]);
                    } else {
                        dp[i][j][k] = dp[i - 1][j][k];
                    }
                } else if (k - w[i] >= 0) {
                    dp[i][j][k] = v[i];
                }
            }
        }
    }

    int ans = 0;
    for (int j = 0; j <= n; ++j) {
        ans = max(ans, dp[n - 1][j][max(min(kmax, (int)((ll)wmax - (ll)w0 * (ll)j)), 0)]);
    }

    cout << ans << endl;
    return 0;
}

