std::uint64_t run(std::vector<std::pair<std::uint64_t, std::uint64_t>>const& data, int index,std::uint64_t weight, std::uint64_t value, std::uint64_t limit)
{
	std::vector<std::map<std::uint64_t, std::uint64_t>> memo(data.size());
	if (limit < weight)
	{
		return 0;
	}
	if (index == data.size())
	{
		return value;
	}
	if (memo[index].count(weight))
	{
		return memo[index][weight];
	}
	return memo[index][weight] = std::max(
		run(data, index + 1, weight + data[index].first, value + data[index].second, limit),
		run(data, index + 1, weight, value, limit));
}

void Main()
{
	int N;
	std::uint64_t W;
	std::cin >> N >> W;
	std::vector<std::pair<std::uint64_t, std::uint64_t>> data(N);
	for (int i{}; i < N; ++i)
	{
		std::cin >> data[i].first >> data[i].second;
	}
	std::cout << run(data, 0, 0, 0, W) << std::endl;

}

