  ll N, W;
  cin >> N >> W;
  vector<ll> w(N), v(N);
  REP(i, N) cin >> w[i] >> v[i];

  ll w0 = w[0];
  // w0, w0 + 1, w0 + 2, w0 + 3 only
  vector<deque<ll>> vs(4);
  REP(i, N) vs[w[i] - w0].push_back(v[i]);
  REP(i, 4) sort(all(vs[i]), greater<ll>());
  REP(i, 4) vs[i].push_front(0);
  REP(i, 4) {
    for (int j = 1; j < vs[i].size(); j++) {
      vs[i][j] += vs[i][j - 1];
    }
  }

  ll ans = 0;
  for (int a = 0; a < vs[0].size(); a++) {
    for (int b = 0; b < vs[1].size(); b++) {
      for (int c = 0; c < vs[2].size(); c++) {
        for (int d = 0; d < vs[3].size(); d++) {
          ll sw = w0 * a + (w0 + 1) * b + (w0 + 2) * c + (w0 + 3) * d;
          if (sw > W) continue;
          ll sv = vs[0][a] + vs[1][b] + vs[2][c] + vs[3][d];
          ans = max(ans, sv);
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

