struct Node{
    //vector<set<int>> used;
    ll w;
    ll v;
    vector<int> rightEnds;
    int rightW;
    bool operator< (const Node &r) const{
        return v < r.v;
    }
};


int main(){
    int n;
    ll maxw;
    cin >> n >> maxw;
    vector<ll> w(n);
    vector<ll> v(n);
    rep(i, n){
        cin >> w[i] >> v[i];
    }

    vector<vector<ll>> list(4, vector<ll>());
    rep(i, n)   list[w[i]-w[0]].push_back(v[i]);
    rep(i, 4){
        sort(list[i].begin(), list[i].end(), greater<ll>());
    }

    priority_queue<Node> que;
    que.push({0, 0, vector<int>(4, -1), 0});

    ll maxv = 0;
    while(!que.empty()){
        Node node = que.top(); que.pop();
        maxv = max(node.v, maxv);

        ll border = 0;
        for(int wx = node.rightW; wx <= wx+1 && wx <= 3; wx++){
            int index = node.rightEnds[wx]+1;
            if(index == (int)list[wx].size()){
                if(wx+1 <= 3){
                    que.push({node.w, node.v, node.rightEnds, wx+1});
                }
                continue;
            }
            if(list[wx][index] <= border)   continue;

            border = list[wx][index];
            vector<int> r = node.rightEnds;
            r[wx]++;
            if(wx == node.rightW+1){
                que.push({node.w, node.v, r, wx});
            }

            if(node.w+wx+w[0] <= maxw){
                que.push({node.w+wx+w[0], node.v+list[wx][index], r, wx});
            }
        }


    }

    cout << maxv << endl;



    return 0;
}

