void update(map<int, int>& tab, int w, int v)
{
    tab[w] = max(tab[w], v);
}

int main()
{
    int N, W;
    cin >> N >> W;
    map<int, vector<int>> weightValues;
    for (int i = 0; i < N; ++i) {
        int w, v;
        cin >> w >> v;
        weightValues[w].push_back(v);
    }

    map<int, int> tab;
    tab.insert(make_pair(0, 0));

    for (auto iter : weightValues) {
        map<int, int> ntab;

        vector<int>& vv = iter.second;
        sort(vv.begin(), vv.end(), greater<int>());

        int w = iter.first;

        for (auto titer : tab) {
            int tabw = titer.first;
            int tabv = titer.second;

            update(ntab, tabw, tabv);

            for (int v : vv) {
                tabw += w;
                tabv += v;
                if (tabw > W)
                    break;
                update(ntab, tabw, tabv);
            }
        }

        ntab.swap(tab);
    }

    int ans = 0;
    for (auto iter : tab) {
        ans = max(ans, iter.second);
    }

    cout << ans << endl;
    return 0;
}

