ll calcW(vector<obj> &objs, int i, int j, int k, int l, vector<int> &start){
    ll totalW = 0;
    for (int m=start[0];m<start[0]+i;m++){
        totalW += objs[m].w;
    }
    for (int m=start[1];m<start[1]+j;m++){
        totalW += objs[m].w;
    }
    for (int m=start[2];m<start[2]+k;m++){
        totalW += objs[m].w;
    }
    for (int m=start[3];m<start[3]+l;m++){
        totalW += objs[m].w;
    }
    return totalW;
}

ll calcV(vector<obj> &objs, int i, int j, int k, int l, vector<int> &start){
    ll totalV = 0;
    for (int m=start[0];m<start[0]+i;m++){
        totalV += objs[m].v;
    }
    for (int m=start[1];m<start[1]+j;m++){
        totalV += objs[m].v;
    }
    for (int m=start[2];m<start[2]+k;m++){
        totalV += objs[m].v;
    }
    for (int m=start[3];m<start[3]+l;m++){
        totalV += objs[m].v;
    }
    return totalV;
}

