    for(int i=j;i<N;i++) start[i] = N;

    ll res = -1;
    for(int i=0;i<=start[1]-start[0];i++){
        for(int j=0;j<=start[2]-start[1];j++){
            for(int k=0;k<=start[3]-start[2];k++){
