  cin >> N >> W;
  for(int i = 0; i < N; i++)  cin >> w[i] >> v[i];

  if(w[0] > 300){
    for(int i = 0; i < 110; i++){
      for(int j = 0; j < 110; j++)  fill(dp[i][j], dp[i][j]+310, -1e9-1);
    }

    for(int i = 0; i < 110; i++)  dp[i][0][0] = 0;
    dp[0][1][0] = v[0];

    for(int i = 1; i < N; i++){
      for(int j = 1; j <= i; j++){
        for(int k = 0; k < 310; k++){
          int wr = w[i] - w[0];
          if(k >= wr) dp[i][j][k] = max(dp[i-1][j-1][k-wr]+v[i], dp[i-1][j][k]);
          else dp[i][j][k] = dp[i-1][j][k];
        }
      }
    }

    int ma = 0;
    for(int i = 0; i < N; i++){
      for(int j = 0; j < 310; j++){
        if(i * w[0] + j <= W) ma = max(ma, dp[N-1][i][j]);
      }
    }
    cout << ma << endl;
  }
  else if(W >= 30010){
    cout << 0 << endl;
  }
  else{
    for(int i = 0; i < 110; i++)  fill(dp2[i], dp2[i]+W, -1e9-1);
