        else dp2[i][j] = dp2[i-1][j];
      }
    }
    int ma = 0;
    for(int i = 0; i <= W; i++){
      ma = max(dp2[N-1][i], ma);
    }
    cout << ma << endl;
  }

  return 0;
}

