    REP(j,4) REP(i,val[j].size()) sum[j][i+1] += sum[j][i] + val[j][i];

    ll ans = 0LL;
    REP(i1,val[0].size()+1) REP(i2,val[1].size()+1) REP(i3,val[2].size()+1) REP(i4,val[3].size()+1){
        if(w1*i1+(w1+1)*i2+(w1+2)*i3+(w1+3)*i4 > W) continue;

        ll ans_tmp= 0LL;
        ans_tmp += sum[0][i1];
        ans_tmp += sum[1][i2];
        ans_tmp += sum[2][i3];
        ans_tmp += sum[3][i4];

        chmax(ans,ans_tmp);
    }

    pl(ans)

    return 0;
}

