                ll w_off = items[n-1].w - items[0].w;
                if (m >= 1 && w >= w_off) {
                    dp[n%2][m][w] = max(dp[n%2][m][w], dp[(n-1)%2][m-1][w-w_off] + items[n-1].v);
                }
            }
        }
    }
    ll ans = numeric_limits<ll>::min();
    rep(m,0,N+1) {
        rep(w,0,3*N+1) {
