int dp[MAX_N + 1][MAX_N + 1][3 * MAX_N + 1] = {};

int main() {
  // read inputs
  int N, W, ws[MAX_N], vs[MAX_N];
  scanf("%d %d", &N, &W);
  for (int i = 0; i < N; i++) {
    scanf("%d %d", &ws[i], &vs[i]);
  }

  // subtract ws[0] from all elements of ws
  const int w0 = ws[0];
  for (int i = 0; i < N; i++) {
    ws[i] -= w0;
  }

  // solve dp
  for (int i = 0; i < N; i++) {
    const int w = ws[i], v = vs[i];
    // printf("i = %d, w = %d, v = %d\n", i, w, v);
    for (int n = 1; n <= i + 1; n++) {
      for (int j = 0; j <= 3 * N; j++) {
        dp[i + 1][n][j] =
            max(dp[i][n][j], j >= w ? dp[i][n - 1][j - w] + v : 0);
        // printf("%d ", dp[i + 1][n][j]);
      }
      //   printf("\n");
    }
  }
  int ans = 0;
  for (int n = 0; n <= N; n++) {
    if (W - n * w0 >= 0) {
      ans = max(ans, dp[N][n][min(W - n * w0, 3 * N)]);
    }
  }
  printf("%d\n", ans);
}

