    if (left_w < 0) return;
    int n = (int)min((ll)ww[ws[k]].size(), left_w / ws[k]);
    tot_v += sum[n];
    res = max(res, tot_v);
  } else {
    dfs(ws, k+1, left_w, tot_v);
    for (int i = 0; i < ww[ws[k]].size(); ++i){
      left_w -= ws[k];
      if (left_w < 0) break;
      tot_v += ww[ws[k]][i];
      dfs(ws, k+1, left_w, tot_v);
    }
  }
}

