  m[{0, 0, 0, 0}] = 0;
  rep(i, N) {
    ll w, v;
    cin >> w >> v;
    if (i == 0) w1 = w;
    map<tuple<ll, ll, ll, ll>, ll> next;
    for (auto mm : m) {
      tuple<ll, ll, ll, ll> f = mm.first;
      ll a = get<0>(f);
      ll b = get<1>(f);
      ll c = get<2>(f);
      ll d = get<3>(f);

      ll weight = a * w1 + b * (w1 + 1) + c * (w1 + 2) + d * (w1 + 3);
      if (weight > W) continue;

      if (next[{a, b, c, d}] < mm.second) next[{a, b, c, d}] = mm.second;

      if (w == w1 and next[{a + 1, b, c, d}] < mm.second + v)
        next[{a + 1, b, c, d}] = mm.second + v;

      if (w == w1 + 1 and next[{a, b + 1, c, d}] < mm.second + v)
        next[{a, b + 1, c, d}] = mm.second + v;

      if (w == w1 + 2 and next[{a, b, c + 1, d}] < mm.second + v)
        next[{a, b, c + 1, d}] = mm.second + v;

      if (w == w1 + 3 and next[{a, b, c, d + 1}] < mm.second + v)
