#include <bits/stdc++.h>
using namespace std ;
const int N = 100 + 5 ;
typedef long long LL ;
typedef pair<int,int> pii;

pii a[N];
LL ans;
int n, w;

bool cmp(pii a , pii b) {
    return 1LL*a.first*b.second > 1LL*a.second*b.first;
}

LL get(LL k, int w, LL res) {
    for(int i = k; ~i; i--) {
        if(a[i].first <= w) {
            w -= a[i].first;
            res += a[i].second;
        }
        else {
            res += 1.0*a[i].second/a[i].first*w;
            break;
        }
    }
    return res;
}

void dfs(int k, int w, LL res) {
    ans = max(ans, res);
    if(k < 0 || get(k,w,res) <= ans) return;
    if(a[k].first <= w) dfs(k-1, w-a[k].first,res+a[k].second);
    dfs(k-1, w, res);
}

int main() {
    scanf("%d%d", &n, &w);
    for(int i = 0; i < n; i++) {
        scanf("%d%d" , &a[i].first, &a[i].second);
        if(a[i].first > w) n--, i--;
    }
    sort(a, a+n, cmp);
    ans = 0;
    dfs(n-1, w, 0);
    printf("%lld\n", ans);
    return 0;
}

