void _main()
{
    ll n; llin(n);
    ll capa; llin(capa);
    V<t2> wvlist; llinl2(wvlist, n);

    S ll dp[102][302];
    memset(dp, 0, sizeof(dp));
    S ll dp_prev[102][302];
    ll wbase = get<0>(wvlist[0]);

    for (auto wv : wvlist) {
        ll w = get<0>(wv);
        ll v = get<1>(wv);

        memcpy(dp_prev, dp, sizeof(dp_prev));

        rep (i, 102) {
            rep (j, 302) {
                ll ni = i + 1LL;
                ll nj = j + (w - wbase);
                if (ni < 102 && nj < 302) {
                    dp[ni][nj] = max(dp_prev[ni][nj], dp_prev[i][j] + v);
                }
            }
        }
    }

    ll ans = 0LL;

    rep (i, 102) rep (j, 302) {
        ll total = i * wbase + j;
        if (total > capa) continue;
        ans = max(ans, dp[i][j]);
    }

    cout << ans << endl;
}

