#define _int64 long long

vector<int> a[4];
vector<_int64> sum[4];

int main()
{
  int i,j,k,l;
  int n,w,ww,vv,x,y;
  _int64 ans,tot,tmp;
  scanf("%d%d",&n,&w);
  scanf("%d%d",&ww,&vv);
  for (i=0;i<4;i++)
    a[i].clear();
  a[0].push_back(vv);
  for (i=1;i<n;i++)
  {
    scanf("%d%d",&x,&y);
    a[x-ww].push_back(y);
  }
  //cout<<"a"<<endl;
  for (i=0;i<4;i++)
  {
    sort(a[i].begin(),a[i].end());
    reverse(a[i].begin(),a[i].end());
    sum[i].clear();
    sum[i].push_back(0);
    for (j=0;j<a[i].size();j++)
      sum[i].push_back(sum[i][j]+a[i][j]);
  }
  ans=0;
  //cout<<"b"<<endl;
  for (i=0;i<=a[0].size();i++)
    for (j=0;j<=a[1].size();j++)
      for (k=0;k<=a[2].size();k++)
      {
        tot=(_int64)i*ww+(_int64)j*(ww+1)+(_int64)k*(ww+2);
        if (tot>w) continue;
        l=(w-tot)/(ww+3);
        tmp=sum[0][i]+sum[1][j]+sum[2][k];
        if (l<sum[3].size()) tmp+=sum[3][l];
        else tmp+=sum[3][sum[3].size()-1];
        if (tmp>ans) ans=tmp;
      }
  printf("%lld\n",ans);
  return 0;
}

