#define ITEM_SIZE 100

int dp(int * itemW, int * itemV, int N, int W)
{
    int table[ITEM_SIZE + 1][ITEM_SIZE + 1] = {};
    for(int i = 1; i < N+1; ++i )
    {
        for(int j = 1; j < W+1; ++j)
        {
            int tw = itemW[i-1];
            int tv = itemV[i-1];
            int v1 = 0;
            int v2 = 0;
            v1 = table[i-1][j];
            if(tw <= j)
            {
                v2 = table[i-1][j-tw] +tv;
            }
            table[i][j] = v1 > v2 ? v1 : v2;
        }
    }

    return table[N][W];
}

int main()
{
    int N, W;
    int v, w;
    int itemW[ITEM_SIZE];
    int itemV[ITEM_SIZE];

    cin >> N >> W;

    for(int i = 0; i < N; ++i)
    {
        cin >> w >> v;
        itemW[i] = w;
        itemV[i] = v;
    }
    cout << dp(itemW, itemV, N, W) << endl;
}

