ll f(int x,int ww)
{
    if(x==0) return 0;
    if(dp[x][ww]!=0) return dp[x][ww];
    ll a,b=0;
    a=f(x-1,ww);
    if(ww-w[x]>=0) b=f(x-1,ww-w[x])+v[x];
    dp[x][ww]=max(a,b);
    return dp[x][ww];
}
