// dp[i][j][k][l]:
// n 番目の物まで見て (w_1, w_1+1, ...) の4種類の物が
// それぞれ (i, j, k, l) 個入っているときの価値の最大値
long long dp[102][102][102][102] = {};

int main()
{
    int N, W;
    cin >> N >> W;
    vector<long long> w(N), v(N);
    for(int i = 0; i < N; ++i) cin >> w[i] >> v[i];

    vector<int> num_w(4);
    for(int i = 0; i < N; ++i) ++num_w[w[i]-w[0]];

    dp[1][0][0][0] = v[0];
    for(int n = 1; n < N; ++n){
        for(int i = 0; i <= num_w[0]; ++i){
            for(int j = 0; j <= num_w[1]; ++j){
                for(int k = 0; k <= num_w[2]; ++k){
                    for(int l = 0; l <= num_w[3]; ++l){
                        if(w[n]-w[0] == 0){
                            dp[i+1][j][k][l] = max(dp[i][j][k][l]+v[n], dp[i+1][j][k][l]);
                        }
                        if(w[n]-w[0] == 1){
                            dp[i][j+1][k][l] = max(dp[i][j][k][l]+v[n], dp[i][j+1][k][l]);
                        }
                        if(w[n]-w[0] == 2){
                            dp[i][j][k+1][l] = max(dp[i][j][k][l]+v[n], dp[i][j][k+1][l]);
                        }
                        if(w[n]-w[0] == 3){
                            dp[i][j][k][l+1] = max(dp[i][j][k][l]+v[n], dp[i][j][k][l+1]);
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for(int i = 0; i <= num_w[0]; ++i){
        for(int j = 0; j <= num_w[1]; ++j){
            for(int k = 0; k <= num_w[2]; ++k){
                for(int l = 0; l <= num_w[3]; ++l){
                    if(w[0]*(i+j+k+l) + j + 2*k + 3*l <= W){
                        ans = max(ans, dp[i][j][k][l]);
                    }
                }
            }
        }
    }
    cout << ans << endl;

    return 0;
}

#include<iostream>
