using LL = long long;
int N,w;
LL W, V;
int size[4],ww[4];
LL ans;
std::vector<LL> dp[4];
void value(int x,int y,int z,int q) {
	LL sum=0;
	for (int i = 0; i < x; i++) {
		sum += dp[0][i];
	}
	for (int i = 0; i < y; i++) {
		sum += dp[1][i];
	}
	for (int i = 0; i < z; i++) {
		sum += dp[2][i];
	}
	for (int i = 0; i <q; i++) {
		sum += dp[3][i];
	}
	ans = std::max(ans, sum);
	sum = 0;
}
void solve() {
	for (int i = 0; i <= size[0]; i++) {
		for (int j = 0; j <= size[1]; j++) {
			for (int k = 0; k <= size[2]; k++) {
				for (int l = 0; l <= size[3]; l++) {
					ww[0] = i*w;
					ww[1] = j*(w + 1);
					ww[2] = k*(w + 2);
					ww[3] = l*(w + 3);
					if (ww[0] + ww[1] + ww[2] + ww[3] > W) {
						break;
					}
						value(i, j, k, l);
				}
			}
		}
	}
}
int main() {
	std::cin >> N >> W;
	std::cin >> w>> V;
	dp[0].push_back(V);
	for (int i = 1; i < N; i++) {
		int tmp;
		std::cin >> tmp >> V;
		dp[tmp-w].push_back(V);
	}
	for (int i = 0;  i < 4; i++) {
		std::sort(dp[i].begin(), dp[i].end());
		size[i] = dp[i].size();
	}
	solve();
	std::cout << ans << std::endl;
	return 0;
}

