#include <algorithm>
using namespace std;

int N, W;
int w[110], v[110];
long long num[40010];
int n;
long long num2[40010];
int n2;
int memo[110][30010];

int bsrch(long long ww)
{
	int l = 0;
	int r = n2-1;
	int mm;
	while(l<=r){
		mm = (l+r)/2;
		if(ww > num2[mm])
			l = mm+1;
		else if(ww < num2[mm])
			r = mm-1;
		else
			return mm;
	}
}

void solve()
{
	int i, j;
	n = 0;
	for(i=0; i<N; i++){
		for(j=0; j<=300; j++){
			num[n] = i*w[0] + j;
			n ++;
		}
	}
	sort(num, num+n);
	n2 = 1;
	num2[0] = num[0];
	for(i=1; i<n; i++){
		if(num[i] != num[i-1]){
			num2[n2] = num[i];
			n2 ++;
		}
	}
	for(i=0; i<N; i++){
		for(j=0; j<n2; j++)
			memo[i][j] = -1000000010;
	}
	memo[0][0] = 0;
	for(i=0; i<N; i++){
		for(j=0; j<n2; j++){
			int val = memo[i][j];
			if(val > memo[i+1][j])
				memo[i+1][j] = val;
			long long ww = num2[j]+w[i];
			if(ww > W)
				continue;
			int jj = bsrch(ww);
			val += v[i];
			if(val > memo[i+1][jj])
				memo[i+1][jj] = val;
		}
	}
	int res = 0;
	for(i=0; i<n2; i++){
		if(memo[N][i] > res)
			res = memo[N][i];
	}
	printf("%d\n", res);
}

int main()
{
	int i;
	scanf("%d%d", &N, &W);
	for(i=0; i<N; i++)
		scanf("%d%d", &w[i], &v[i]);
	solve();
	return 0;
}

