int n, wsum;
int w[101], v[101];
int dp[101][301][101];
int base;

int func(int cur,int wc, int cou) {
	if (dp[cur][wc][cou] != -1) return dp[cur][wc][cou];
	if (cur == n) {
		if (wc > (wsum - base*cou))
			return INT_MIN;
		return 0;
	}
	int ret = INT_MIN;
	ret = max(ret,func(cur+1, wc,cou));
	ret = max(ret,func(cur+1, wc + w[cur], cou + 1) + v[cur]);

	return dp[cur][wc][cou] = ret;
}

