	while (~scanf("%d%d", &n, &W))
	{		
		for (int i = 1; i <= n; i++)
		{
			rec[i].input();
		}

		ll sum[4] = {0};
		int c = 0;
		int nid[4] = {0};
		nid[0] = 1;
		for (int i = 2; i <= n; i++)
		{
			if (rec[i].w != rec[i-1].w)
			{
				nid[++c] = i;
			}
		}
		if (c == 0)
			nid[1] = n + 1;
		else if (c == 1)
			nid[2] = n + 1;
		else if (c == 2)
			nid[3] = n + 1;

		ll ans = 0;

		for (int i = nid[0] - 1; i < nid[1]; i++)
		{
			if (i >= nid[0])
				sum[0] += rec[i].v;
			else
				sum[0] = 0;
			if (c == 0)
			{
				ll V = (i - nid[0] + 1)*rec[nid[0]].w;
				if (V <= W)
					ans = max(ans, sum[0]);
				continue;
			}
			for (int j = nid[1] - 1; j < nid[2]; j++)
			{
				if (j >= nid[1])
					sum[1] += rec[j].v;
				else
					sum[1] = 0;
				if (c == 1)
				{
					ll V = (i - nid[0] + 1)*rec[nid[0]].w;
					V += (j - nid[1] + 1)*rec[nid[1]].w;
					if (V <= W)
						ans = max(ans, sum[0] + sum[1]);
					continue;
				}
				for (int h = nid[2] - 1; h < nid[3]; h++)
				{
					if (h >= nid[2])
						sum[2] += rec[h].v;
					else
						sum[2] = 0;

					if (c == 2)
					{
						ll V = (i - nid[0] + 1)*rec[nid[0]].w;
						V += (j - nid[1] + 1)*rec[nid[1]].w;
						V += (h - nid[2] + 1)*rec[nid[2]].w;
						if (V <= W)
							ans = max(ans, sum[0] + sum[1] + sum[2]);
						continue;
					}
					for (int d = nid[3] - 1; d <= n; d++)
					{
						if (d >= nid[3])
							sum[3] += rec[d].v;
						else
							sum[3] = 0;
						ll V = (i - nid[0] + 1)*rec[nid[0]].w;
						V += (j - nid[1] + 1)*rec[nid[1]].w;
						V += (h - nid[2] + 1)*rec[nid[2]].w;
						V += (d - nid[3] + 1)*rec[nid[3]].w;
						if (V <= W)
						{
							ans = max(ans, sum[0] + sum[1] + sum[2] + sum[3]);
						}
					}
