using namespace std;

int DFS(const vector<vector<int> >& ws, int depth, int value, int w, int w0, int W) {
	if (depth >= ws.size()) {
		if (w > W) {
			return 0;
		}
		else {
			return value;
		}
	}
	int res = DFS(ws, depth + 1, value, w, w0, W);
	for (int i = 0; i < ws[depth].size(); ++i) {
		int newW = w + (w0 + depth)*(i+1);
		int newValue = value + ws[depth][i];
		if (newW > W) break;
		res = max(res, DFS(ws, depth + 1, newValue, newW, w0, W));
	}
	return res;
}

int main(void) {
	int N, W; cin >> N >> W;

	vector<vector<int>> ws(4);
	int w0, v0; cin >> w0 >> v0;
	ws[0].push_back(v0);
	for (int i = 0; i < N - 1; ++i) {
		int w, v; cin >> w >> v;
		ws[w - w0].push_back(v);
	}

	for (auto &w : ws) {
		sort(w.begin(), w.end(), greater<int>());
		for (int i = 1; i < w.size(); ++i) {
			w[i] = w[i] + w[i - 1];
		}
	}

	cout << DFS(ws, 0, 0, 0, w0, W) << endl;;
	system("pause");
}

