    for (auto &i : w){
        i -= C;
    }
    std::vector<std::vector<std::vector<unsigned>>> dp(N + 1,
            std::vector<std::vector<unsigned>>(N + 1,
            std::vector<unsigned>(3 * N, 0)));
    for (unsigned i = 1; i < N + 1; ++i) {
        for (unsigned j = 1; j < N + 1; ++j) {
