                    dp[i][j][k] = dp[i-1][j][k];
                }
            }
        }
    }
    unsigned max = 0;
    for (unsigned i = 1; i <= N; ++i) {
        if (i * C <= W) {
            max = std::max(max, dp[N][i][std::min(3 * N - 1, W - i * C)]);
        }
    }
    std::cout << max << std::endl;
