	cin.tie(0);
	ios::sync_with_stdio(false);

    ll N, W;
    cin >> N >> W;
    ll w[N], v[N];
    vector<ll> v1, v2, v3, v4;
    rep(i, 0, N) {
        cin >> w[i] >> v[i];
        if(w[i] == w[0]) v1.push_back(v[i]);
        else if(w[i] == w[0] + 1) v2.push_back(v[i]);
        else if(w[i] == w[0] + 2) v3.push_back(v[i]);
        else if(w[i] == w[0] + 3) v4.push_back(v[i]);
    }

    vsort(v1);
    reverse(v1.begin(), v1.end());
    vsort(v2);
    reverse(v2.begin(), v2.end());
    vsort(v3);
    reverse(v3.begin(), v3.end());
    vsort(v4);
    reverse(v4.begin(), v4.end());
    rep(i, 1, v1.size()) v1[i] += v1[i - 1];
    rep(i, 1, v2.size()) v2[i] += v2[i - 1];
    rep(i, 1, v3.size()) v3[i] += v3[i - 1];
    rep(i, 1, v4.size()) v4[i] += v4[i - 1];

    ll rsl = 0;
    rep(a, 0, v1.size() + 1) {
        ll va = (a == 0) ? 0 : v1[a - 1];
        rep(b, 0, v2.size() + 1) {
            ll vb = (b == 0) ? 0 : v2[b - 1];
            rep(c, 0, v3.size() + 1) {
                ll vc = (c == 0) ? 0 : v3[c - 1];
                rep(d, 0, v4.size() + 1) {
                    if(a * w[0] + b * (w[0] + 1) + c * (w[0] + 2) + d * (w[0] + 3) > W) continue;
                    ll vd = (d == 0) ? 0 : v4[d - 1];
                    ll tmp_w = va + vb + vc + vd;
                    rsl = max(rsl, tmp_w);
                }
                if(a * w[0] + b * (w[0] + 1) + c * (w[0] + 2) > W) continue;
                ll tmp_w = va + vb + vc;
                rsl = max(rsl, tmp_w);
            }
            if(a * w[0] + b * (w[0] + 1) > W) continue;
            ll tmp_w = va + vb;
            rsl = max(rsl, tmp_w);
        }
        if(a * w[0] > W) continue;
        ll tmp_w = va;
        rsl = max(rsl, tmp_w);
    }

    cout << rsl << endl;
}

