typedef long long ll;
struct dta{
    int val,cost;
};
using namespace std;

int n,W,F[maxn][maxm],sum,res,Q[maxn][maxm];
dta A[maxn];
ll P[maxn];

int main(){
    scanf("%d%d",&n,&W);
    P[0]=0;
    scanf("%d%d",&A[1].cost,&A[1].val);
    P[1]=A[1].cost;
    A[1].cost=1;
    FOR(i,2,n) {
        scanf("%d%d",&A[i].cost,&A[i].val);
        P[i]=P[i-1]+P[1];
        A[i].cost=A[i].cost-P[1]+1;
        sum+=A[i].cost;
    }
    sum+=1;
    memset(F,0,sizeof(F));
    memset(Q,0,sizeof(Q));
    FOR(i,1,n){
        FOR(j,0,sum){
            F[i][j]=F[i-1][j];
