            if (j-A[i].cost>=0&&F[i][j]<F[i-1][j-A[i].cost]+A[i].val) {
                F[i][j]=F[i-1][j-A[i].cost]+A[i].val;
                Q[i][j]=Q[i-1][j-A[i].cost]+1;
            }
        }
    }
    res=0;
    FOR(i,0,sum)
        if (P[Q[n][i]]+i-Q[n][i]<=(ll)W) res=max(res,F[n][i]);
