int rec_dp(int i, int j) {
  if (dp[i][j] != -1) {

    return dp[i][j];
  }
  int res;
  if (i == n) {

    res = 0;
  } else if (j < w[i]) {

    res = rec_dp(i + 1, j);
  } else {

    res = max(
        rec_dp(i + 1, j),
        rec_dp(i + 1, j - w[i]) + v[i]
    );
  }

  return dp[i][j] = res;
}

void solve_dp() {
  memset(dp, -1, sizeof(dp)); 
  cout << rec_dp(0, W) << endl;
}




