bool chmin(T &a, T b)
{
	if (a > b)
	{
		a = b;
		return false;
	}
	return true;
}

template<class T>
bool chmax(T &a, T b)
{
	if (a < b)
	{
		a = b;
		return false;
	}
	return true;
}

template<class T>
bool chmax(T &a, initializer_list<T> l)
{
	return chmax(a, *max_element(l.begin(), l.end()));
}

template<class T>
bool chmin(T &a, initializer_list<T> l)
{
	return chmin(a, *min_element(l.begin(), l.end));
}

ll N, W;
ll w0{-1};
map<ll, vector<ll>> m;

ll solve(ll i, ll w, ll v, vector<ll>& vec)
{
	if (i == 3)
	{
		if (w <= W) return v;
		else return 0;
	}

	ll res{0};
	for (ll k = 0; k <= vec[i]; ++k)
	{
		ll ww = (w0+i);
		ll tmp = solve(i+1, w+ww*k,
					   v+accumulate(m[ww].begin(),
									m[ww].begin()+k, 0ll), vec);
		chmax(res, tmp);
	}
	return res;
}

