LL N, K;
int main() {
	cin >> N >> K;
	map<LL, vector<LL>> M;

	REP(i, 0, N) {
		int a, b;
		cin >> a >> b;
		M[a].push_back(b);
	}

	int w0 = M.begin()->first;
	vector<LL> V[4];
	REP(c, 0, 4) {
		V[c] = M[w0 + c];
	}

	LL mx = 0;
	REP(i, 0, V[0].size() + 1) {
		REP(j, 0, V[1].size() + 1) {
			REP(k, 0, V[2].size() + 1) {
				REP(l, 0, min(N - (i + j + k) + 1, (LL)V[3].size()) + 1) {
					if (l < 0) continue;
					if (w0 * i + (w0 + 1) * j + (w0 + 2) * k + (w0 + 3) * l > K) continue;
					LL sum = 0;

					REP(ii, 0, i) sum += V[0][ii];
					REP(jj, 0, j) sum += V[1][jj];
					REP(kk, 0, k) sum += V[2][kk];
					REP(ll, 0, l) sum += V[3][ll];
					mx = max(mx, sum);
				}
			}
		}
	}
	cout << mx << endl;
	return 0;
}

