    cin >> N >> W;
    vector<ll> ws(4, 0);
    vector< vector<ll> > vs(4);
    REP(i, N){
        ll w, v;
        cin >> w >> v;
        int j = 0;
        while(j<ws.size()){
            if(ws[j]==w || ws[j]==0) break;
            j++;
        }
        ws[j]=w;
        vs[j].push_back(v);
    }
    REP(i, 4) sort(vs[i].begin(), vs[i].end(), greater<int>());
    ll ma = 0;
    REP(i, vs[0].size()+1) REP(j, vs[1].size()+1) REP(k, vs[2].size()+1) REP(l, vs[3].size()+1){
        ll w_sum = ws[0]*i+ws[1]*j+ws[2]*k+ws[3]*l;
