typedef long long ll;
const int N = 450;
typedef pair<ll, ll> pll;
pll items[N];
ll max_v[N][N];
ll tmp_max_v[N][N];

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(nullptr);
    ll n, w;
    cin >> n >> w;
    for (int i = 0; i < n; i++) {
        cin >> items[i].first >> items[i].second;
    }
    ll w1 = items[0].first;
    for (int a = 0; a < N; a++) {
        for (int b = 0; b < N; b++) {
            max_v[a][b] = -1;
            tmp_max_v[a][b] = -1;
        }
    }
    max_v[0][0] = 0;
    tmp_max_v[0][0] = 0;
    for (int i = 0; i < n; i++) {
        for (int a = 0; a < N; a++) {
            for (int b = 0; b < N; b++) {
                if (max_v[a][b] < 0)
                    continue;
                ll num = a * w1 + b;
                num += items[i].first;
                ll new_a = num / w1;
                ll new_b = num % w1;
                tmp_max_v[new_a][new_b] = max(max_v[new_a][new_b], max_v[a][b] + items[i].second);
            }
        }
        for (int a = 0; a < N; a++) {
            for (int b = 0; b < N; b++) {
                max_v[a][b] = tmp_max_v[a][b];
            }
        }
    }
    ll res = 0;
    for (int a = 0; a < N; a++) {
        for (int b = 0; b < N; b++) {
            ll num = a * w1 + b;
            if (num > w)
                continue;
            res = max(max_v[a][b], res);
        }
    }
    cout << res << endl;
    return 0;
}

