const int N = 105;
const int M = 3;
int w[N],v[N];

ll dp[N][N*M][N];

ll solveDp(int ind,int weight,int k,int n,int W) {
    ll R = (ll)k*w[0] + weight;
    if(R>W) {
        return -1e18;
    }
    if(ind>n) {
        return 0;
    }
    ll &ret = dp[ind][weight][k];
    if(ret!=-1) {
        return ret;
    }
    ret = v[ind] + solveDp(ind+1,weight + w[ind]-w[1],k+1,n,W);
    ret = max(ret, solveDp(ind+1,weight,k,n,W));
    return ret;
}

void solve() {
    int n,W;
    scanf("%d%d",&n,&W);
    for(int i=1;i<=n;++i) {
        scanf("%d%d",&w[i],&v[i]);
    }
    memset(dp,-1,sizeof(dp));
    printf("%lld\n", solveDp(1,0,0,n,W));
}

int main() {
   //freopen("input.txt","r",stdin);
   solve();
}

