/**** main function ****/

ll N, W, w[100], v[100], w1;
vector<ll> d[4], sum[4];

ll search(ll now, ll restw) {
  if (now == 3) {
    return sum[3][lmin(restw / (w1 + 3), sum[3].size()-1)];
  }
  ll ans = 0;
  for (ll i = 0; i < sum[now].size(); i++) {
    if (i * (w1 + now) > restw) break;
    ans = lmax(ans, sum[now][i] + search(now+1, restw - i * (w1 + now)));
  }
  return ans;
}

int main() {
  scanf("%lld%lld", &N, &W);
  for (ll i = 0; i < N; i++) {
    scanf("%lld%lld", &w[i], &v[i]);
    d[w[i] - w[0]].push_back(v[i]);
  }
  w1 = w[0];
  for (ll i = 0; i < 4; i++) sort(d[i].begin(), d[i].end(), greater<ll>());
  for (ll i = 0; i < 4; i++) {
    ll temp = 0;
    sum[i].push_back(temp);
    for (ll j = 0; j < d[i].size(); j++) temp += d[i][j], sum[i].push_back(temp);
  }
  printf("%lld\n", search(0, W));
}

