using vi = std::vector<int64_t>;
using vvi = std::vector<vi>;
struct N { int64_t w; int64_t v; };
using vN = std::vector<N>;

int main() {
    int n; int64_t w; std::cin >> n >> w;
    vN items(n);
    for (auto &u : items) std::cin >> u.w >> u.v;

    auto w1 = items.front().w;
    vvi k(4, {0}); // will contain summed values for selecting n items of weight w1 + x (0..3)
    for (const auto &u : items) k[u.w - w1].push_back(u.v);
    for (auto &u : k) std::sort(next(u.begin()), u.end(), std::greater<int64_t>());
    for (auto &u : k) for (auto it = next(u.begin()); it != u.end(); ++it) *it += *prev(it);
    int64_t vmax = 0;
    for (int i0 = 0; i0 < k[0].size(); i0++) {
        for (int i1 = 0; i1 < k[1].size(); i1++) {
            for (int i2 = 0; i2 < k[2].size(); i2++) {
                for (int i3 = 0; i3 < k[3].size(); i3++) {
                    auto wsum = i0 * (w1 + 0) + i1 * (w1 + 1) + i2 * (w1 + 2) + i3 * (w1 + 3);
                    if (wsum <= w) {
                        auto vsum = k[0][i0] + k[1][i1] + k[2][i2] + k[3][i3];
                        vmax = std::max(vmax, vsum);
                    }
                }
            }
        }
    }
    std::cout << vmax << std::endl;
}

