int n;
int maxw;
int wt[110];
int val[110];
int offset;
int memo[100][500][100];

int f(int i, int w, int num) {
    if (i == n or w + offset * num > maxw)
        return 0;
    int& ret = memo[i][w][num];
    if (ret != -1)
        return ret;
    int a = f(i + 1, w, num);
    int b = 0;
    if (w + wt[i] + offset * (num + 1) <= maxw)
        b = val[i] + f(i + 1, w + wt[i], num + 1);
    return ret = max(a, b);
}

