#define SREP(s,i,m) for(unsigned int i = s; i < m; ++i)
#define REP(i,m) SREP(0,i,m)

using namespace std;
#ifdef _MSC_VER
using LONG = __int64;
using ULONG = unsigned __int64;
#else
using LONG = long long int;
using ULONG = unsigned long long int;
#endif

struct Item {
	int w, v;
};

int main(void) {
	int N, W;
	cin >> N >> W;
	vector<Item> items(N);
	REP(i, N) {
		cin >> items[i].w >> items[i].v;
	}
	vector<vector<int>> eitems(4);
	REP(i, items.size()) {
		REP(j, eitems.size()) {
			if (items[0].w + j == items[i].w) {
				eitems[j].push_back(items[i].v);
			}
		}
	}
	REP(i, eitems.size()) {
		sort(eitems.begin(), eitems.end());
	}

	if (W >= (items[0].w + 3) * N) {
		LONG sum = 0;
		REP(i, N) {
			sum += items[i].v;
		}
		cout << sum << endl;
	}
	else if (items[0].w > 3 * N) {
		int take = W / items[0].w;
		int take2 = W / (items[0].w + 3);
		if (take != take2) throw runtime_error("ERROR");
		int remainW = W;
		LONG sum = 0;
		REP(i, N) {
			int idx = 0;
			int maxV = 0;
			REP(j, eitems.size()) {
				if (eitems[j].size() > 0 && remainW - (items[0].w + idx) >= 0 &&
					eitems[j][eitems[j].size() - 1] >= maxV) {
					idx = j;
					maxV = eitems[j][eitems[j].size() - 1];
				}
			}
			if (maxV == 0) break;
			sum += eitems[idx][eitems.size() - 1];
			remainW -= items[0].w + idx;
			eitems[idx].erase(eitems[idx].end() - 1);
		}
		cout << sum << endl;
	}
	else {
		vector<LONG> dp(W + 1);
		REP(i, W) {
			dp[i] = 0;
		}
		REP(j, N) {
			for (int i = W; i >= 0; i--) {
				if (i - items[j].w >= 0) {
					dp[i] = max(dp[i], dp[i - items[j].w] + items[j].v);
				}
			}
		}
		LONG ans = 0;
		REP(i, W + 1) {
			ans = max(dp[i], ans);
		}
		cout << ans << endl;
	}
	return 0;
}

