using namespace std;

/* constant */

const int MAX_N = 100;
const int MAX_DW = 3;
const int MAX_K = MAX_DW * MAX_N;

/* typedef */

typedef long long ll;
typedef vector<int> vi;
typedef queue<int> qi;
typedef pair<int,int> pii;

/* global variables */

int wis[MAX_N], vis[MAX_N];
int dp[MAX_N + 1][MAX_N + 1][MAX_K + 1];

/* subroutines */

inline void setmax(int &a, int b) { if (a < b) a = b; }

/* main */

int main() {
  int n;
  ll w;
  scanf("%d%lld", &n, &w);

  for (int i = 0; i < n; i++) scanf("%d%d", &wis[i], &vis[i]);
  ll w0 = wis[0];
  int maxj = w / w0;
  for (int i = 0; i < n; i++) wis[i] -= w0;

  memset(dp[0], -1, sizeof(dp[0]));
  dp[0][0][0] = 0;

  for (int i = 0; i < n; i++) {
    int &wi = wis[i], &vi = vis[i];
    memcpy(dp[i + 1], dp[i], sizeof(dp[i]));
    for (int j = 0; j <= i && j <= maxj; j++) {
      int maxk = MAX_DW * j;
      for (int k = 0; k <= maxk; k++)
	if (dp[i][j][k] >= 0 && w0 * (j + 1) + (k + wi) <= w)
	  setmax(dp[i + 1][j + 1][k + wi], dp[i][j][k] + vi);
    }
  }

  int maxdp = 0;
  for (int j = 0; j <= n; j++)
    for (int k = 0; k <= MAX_K; k++)
      setmax(maxdp, dp[n][j][k]);
  printf("%d\n", maxdp);
  return 0;
}

