					if (w > 0) {num1 += s[3][a[3].size() - 1] - s[3][w - 1]; num2 += (a[3].size() - w + 1) * (t1[0] + 3);}
					if (num2 <= m) mx = max(mx, num1);
				}
			}
		}
	}
