			vector<vector<vector<int> > >(vss[1].size()+1,
				vector<vector<int> >(vss[2].size()+1,
					vector<int>(vss[3].size()+1))));
		dp[0][0][0][0] = 0;
		rep(i0, vss[0].size()) {
			rep(i1, vss[1].size()) {
				rep(i2, vss[2].size()) {
					rep(i3, vss[3].size()) {
						int w = i0 * ws[0] + i1 * (ws[0] + 1) + i2 * (ws[0] + 2) + i3 * (ws[0] + 3);
						int a = dp[i0][i1][i2][i3];
						if (w + ws[0] <= maxW) {
							dp[i0 + 1][i1][i2][i3] = max(dp[i0 + 1][i1][i2][i3], dp[i0][i1][i2][i3] + vss[0][i0]);
						}

						if (w + ws[0] + 1 <= maxW) {
							dp[i0][i1 + 1][i2][i3] = max(dp[i0][i1 + 1][i2][i3], dp[i0][i1][i2][i3] + vss[1][i1]);
						}

						if (w + ws[0] + 2 <= maxW) {
							dp[i0][i1][i2 + 1][i3] = max(dp[i0][i1][i2 + 1][i3], dp[i0][i1][i2][i3] + vss[2][i2]);
						}

						if (w + ws[0] + 3 <= maxW) {
							dp[i0][i1][i2][i3 + 1] = max(dp[i0][i1][i2][i3 + 1], dp[i0][i1][i2][i3] + vss[3][i3]);
						}
					}
				}
			}
		}

		int maxDp = 0;
		rep(i0, vss[0].size() + 1) {
			rep(i1, vss[1].size() + 1) {
				rep(i2, vss[2].size() + 1) {
					rep(i3, vss[3].size() + 1) {
						maxDp = max(maxDp, dp[i0][i1][i2][i3]);
					}
				}
			}
		}

		return maxDp;

	}
};

