void value(LL x, LL y, LL z, LL q) {
	LL sum = 0;
	for (LL aa = 0; aa < x; aa++) {
		sum += dp[0][aa];
	}
	for (LL aa = 0; aa < y; aa++) {
		sum += dp[1][aa];
	}
	for (LL aa = 0; aa < z; aa++) {
		sum += dp[2][aa];
	}
	for (LL aa = 0; aa < q; aa++) {
		sum += dp[3][aa];
	}
	ans = std::max(ans, sum);
	sum = 0;
}
