using namespace std;

int solve(int N, int W, vector<int>& w, vector<int>& v, map<pair<int, int>, int>& Memo) {
	if (W <= 0 || N < 0) return 0;
	if (Memo.find({ N,W }) != Memo.end()) return Memo[{N, W}];
	Memo[{N, W}] = max((W - w[N] >= 0 ? solve(N - 1, W - w[N], w, v, Memo) + v[N] : 0), solve(N - 1, W, w, v, Memo));
	return Memo[{N, W}];
}

