        ans = max(ans,
          (i == 0 ? 0 : mp[ws[0]][i - 1])
          + (j == 0 ? 0 : mp[ws[1]][j - 1])
        );
      }
    }
  } else if (ws.size() == 3) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      for (int j = 0; j <= mp[ws[1]].size(); j++) {
        for (int k = 0; k <= mp[ws[2]].size(); k++) {
          if (i * ws[0] + j * ws[1] + k * ws[2] > W) {
            break;
          }
          ans = max(ans,
            (i == 0 ? 0 : mp[ws[0]][i - 1])
            + (j == 0 ? 0 : mp[ws[1]][j - 1])
            + (k == 0 ? 0 : mp[ws[2]][k - 1])
          );
        }
      }
    }
  } else if (ws.size() == 4) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      for (int j = 0; j <= mp[ws[1]].size(); j++) {
        for (int k = 0; k <= mp[ws[2]].size(); k++) {
          int cur_w = i * ws[0] + j * ws[1] + k * ws[2];
          int rem_w = W - cur_w;
          if (rem_w < 0) {
            continue;
          }
          int l = min(n - i - j - k, rem_w / ws[3]);
          if (l < 0 || l > (int) mp[ws[3]].size()) {
            continue;
          }
          if (i * ws[0] + j * ws[1] + k * ws[2] + l * ws[3] > W) {
            continue;
          }
          ans = max(ans, 
            (i == 0 ? 0 : mp[ws[0]][i - 1]) 
            + (j == 0 ? 0 : mp[ws[1]][j - 1]) 
            + (k == 0 ? 0 : mp[ws[2]][k - 1]) 
            + (l == 0 ? 0 : mp[ws[3]][l - 1])
          );
        }
      }
    }
  } else {
    assert(false);
  }
  cout << ans << '\n';
  return 0;
}

