template<class T> string deb_tos(const vector<T> &a, ll W = inf) {
    stringstream ss;
    if (W == inf)W = min(sz(a), DEB_LEN);
    if (sz(a) == 0)return ss.str();
    rep(i, W) {
        ss << deb_tos(a[i]);
        if (typeid(a[i]) == typeid(P)) { ss << endl; } else { ss << " "; }
