using bint =__int128;
std::ostream &operator<<(std::ostream &dest, __int128_t value) {
    std::ostream::sentry s(dest);
    if (s) {
        __uint128_t tmp = value < 0 ? -value : value;
        char buffer[128];
        char *d = std::end(buffer);
        do {
            --d;
            *d = "0123456789"[tmp % 10];
            tmp /= 10;
        } while (tmp != 0);
        if (value < 0) {
            --d;
            *d = '-';
        }
        ll len = std::end(buffer) - d;
        if (dest.rdbuf()->sputn(d, len) != len) { dest.setstate(std::ios_base::badbit); }
    }
    return dest;
}
__int128 to_bint(string &s) {
    __int128 ret = 0;
    for (ll i = 0; i < (ll) s.length(); ++i) if ('0' <= s[i] && s[i] <= '9') ret = 10 * ret + s[i] - '0';
    return ret;
}
void operator>>(istream &iss, bint &v) {
    string S;
    iss >> S;
    v = 0;
    rep(i, sz(S)) {
        v *= 10;
        v += S[i] - '0';
    }
}

