			for(int i=0;i<N;i++){
				for(int num=u-1;num>=0;num--){
					for(int j=rest;j>=0;j--){
						if(dp[num][j] == -1) continue;
						if(j + w[i] > rest) continue;
						dp[num+1][j+w[i]] = max(dp[num+1][j+w[i]], dp[num][j]+v[i]);
					}
				}
			}
			for(int i=0;i<500;i++) res = max(res, dp[u][i]);
		}
		cout << res << endl;
	}
}

