typedef double Real;
const Real EPS = 1e-11;
#define EQ0(x) (abs(x)<EPS)
#define EQ(a,b) (abs(a-b)<EPS)
int n, wmax;
int w[125];
int v[125];
vi yo[4];
vl sm[4];

int main() {
	//入力受け取り
	cin >> n >> wmax;
	REP(i, n) cin >> w[i] >> v[i];

	//重さの基準を格納
	int base = w[0];

	//重さごとに分類して格納。
	REP(i, n) {
		yo[w[i] - base].push_back(v[i]);
	}

	//重さごとに、価値の降順でソート
	REP(i, 4)sort(ALL(yo[i]));
	REP(i, 4)reverse(ALL(yo[i]));

	//価値の累積和。
	//個数を指定すると、価値が高い順にとった時の結果が返ってくる

	REP(x, 4) {
		ll sum = 0;
		sm[x].push_back(0);
		REP(i, yo[x].size()) {
			sum += yo[x][i];
			sm[x].push_back(sum);
		}
	}
	//前処理終了

	//演算、グループごとにa個、ｂ個、c個とるとして個数で全探索
	//a,b,cが決まれば、dも決まるので価値を計算して結果の更新。

	ll ans = 0;
	REP(a, sm[0].size())REP(b, sm[1].size())REP(c, sm[2].size()) {
		ll wsum = (ll)a*base + (ll)b*(base + 1) + (ll)c*(base + 2);
		if (wsum > wmax)break;
		int rest = wmax - wsum;
		int d = min((int)yo[3].size(), rest / (base + 3));
		ll tmp = sm[0][a] + sm[1][b] + sm[2][c] + sm[3][d];
		CHMAX(ans, tmp);
	}
	printf("%lld\n", ans);
	return 0;
}

