vvl cart_product (const vvl& v) {
  vvl s = {{}};
  for (auto& u : v) {
    vvl r;
    for (auto& x : s) {
      for (auto y : u) {
        r.push_back(x);
        r.back().push_back(y);
      }
    }
    s.swap(r);
  }
  return s;
}

