    rep(k, 4) {
      // cout << c[k] << " ";
      rep(i, c[k]) {
        curW += w[0] + k;
        curV += mp[k][i];
      }
    }
    // cout << endl;
    if (curW <= W) {
      ans = max(ans, curV);
    }
  }
  cout << ans << endl;
  return 0;
}

