vector<ll> d[4], sum[4];

ll search(ll now, ll restw) {
  if (now == 3) {
    return sum[3][lmin(restw / (w1 + 3), sum[3].size())];
  }
  ll ans = 0;
  for (ll i = 0; i < sum[now].size(); i++) {
    if (i * (w1 + now) > restw) break;
    ans = lmax(ans, sum[now][i] + search(now+1, restw - i * (w1 + now)));
  }
  return ans;
}

