using namespace std;
using LLONG = long long;
const LLONG MOD = 1000000007;

LLONG weights[101];
LLONG values[101];

// dp[i][n][w']:i番目まで考えたとき，n個の物を入れた
//              総重量がw'（wi'=wi-w1）となるときの最大価値
LLONG dp[101][101][300];

int main()
{
    int N, W; cin >> N >> W;
    for (int i = 1; i <= N; ++i)
    {
        cin >> weights[i] >> values[i];
    }
    // 普通にdp[i][w]とするとメモリがO(NW)だけ必要となり容量オーバー
    // w1 <= wi <= w1 + 3 より全ての重量から w1 を引く
    // これによりそれぞれの重量を 0 ~ 3 の範囲で考えれ，
    // 正味の重量は w1 * (選んだ個数) + (余剰の総和) で計算すれば
    // 個数幅は 0 ~ 100, 余剰の総和幅は 0 ~ 300 でメモリに乗る
    LLONG w1 = weights[1];
    for (int i = 1; i <= N; ++i)
    {
        weights[i] -= w1;
    }
    for (int i = 1; i <= N; ++i)
    {
        LLONG wi = weights[i];
        for (int n = 1; n <= i; ++n)
        {
            for (int w = 0; w < wi; ++w)
            {
                dp[i][n][w] = dp[i - 1][n][w];
            }
            for (int w = wi; w <= 300; ++w)
            {
                dp[i][n][w] = max(
                    dp[i - 1][n - 1][w - wi] + values[i],
                    dp[i - 1][n][w]);
            }
        }
    }
    LLONG ans = 0;
    for (int n = 1; n <= N; ++n)
    {
        for (int w = 0; w <= 300; ++w)
        {
            if (w1 * n + w <= W)
            {
                ans = max(ans, dp[N][n][w]);
            }
        }
    }
    cout << ans << endl;
}

