    int w, v;
    cin >> w >> v;
    if (i == 0) {
      w0 = w;
      list_dw[i] = 0;
    } else {
      list_dw[i] = w - w0;
    }
    list_v[i] = v;
  }

  vint3d list_maxv(n + 1, vint2d(n + 1, vint(MAXDW + 1, -1)));

  int m = 0;

  for_range(k, n + 1) {
    for_range(dw, MAXDW + 1) {
      if (k * w0 + dw <= maxw) {
        m = max(m, maxv(n, k, dw, list_maxv, list_v, list_dw));
      }
    }
  }

  cout << m << endl;
}

