vector<pll> pref[4];

void solve() {
	for(int t = 0; t < 4; ++t) {
		pref[t].emplace_back(0, 0);
	}

	int n = fetch<int>();
	ll W = fetch<ll>();

	ll fst_w = NIL;

	for(int i = 0; i < n; ++i) {
		ll w = fetch<ll>();
		ll v = fetch<ll>();

		if(fst_w == NIL) {
			fst_w = w;
		}

		pref[w - fst_w].emplace_back(w, v);
	}

	for(int t = 0; t < 4; ++t) {
		sort(pref[t].begin(), pref[t].end());
		int sz = len(pref[t]);

		for(int i = 1; i < sz; ++i) {
			pref[t][i].first += pref[t][i - 1].first;
			pref[t][i].second += pref[t][i - 1].second;
		}
	}

	ll answ = 0;

	for(int i = 0; i < len(pref[0]); ++i) {
		for(int j = 0; j < len(pref[1]); ++j) {
			int l = len(pref[3]) - 1;
			for(int k = 0; k < len(pref[2]); ++k) {
				while(l >= 0 && pref[0][i].first + pref[1][j].first + pref[2][k].first + pref[3][l].first > W) {
					--l;
				}

				if(l >= 0) {
					answ = max(answ, pref[0][i].second + pref[1][j].second + pref[2][k].second + pref[3][l].second);
				}
			}
		}
	}

	cout << answ << '\n';
}

int main() {
	fast_io();
	solve();

	return 0;
}

