int dp[102][10000000];
int n, W;
int w[102];
int v[102];

void solve()
{
	for (int i = n - 1;i >= 0;i--) {
		for (int j = 0;j <= W;j++) {
			if (j < w[i]) {
				dp[i][j] = dp[i+1][j];
			}
			else {
				dp[i][j] = std::max(dp[i + 1][j], dp[i + 1][j - w[i]] + v[i]);
			}
		}
	}
	cout << dp[0][W] << endl;
}

