ll solve(int idx, int left, int wt)
{
    if(left == 0)
        return 0;
    if(idx > n)
    {
        if(left != 0)
            return INT_MIN;
        else
           return 0;
    }
    if(dp[idx][left][wt] != -1)
        return dp[idx][left][wt];
    if(w[idx] > wt)
        return dp[idx][left][wt] = solve(idx + 1, left, wt);
    else
        return dp[idx][left][wt] = max(v[idx] + solve(idx + 1, left - 1, wt - w[idx]), solve(idx + 1, left, wt));
}

int main()
{
    scanf("%d %d", &n, &W);
    for(int i = 1 ; i <= n ; i++)
