    {
        if((W - i*x) < 0 )
            continue;
        int wgt = min(3*i, W - i*x);
        memset(dp, -1, sizeof(dp));
        ans = max(ans, solve(1, i, wgt));
    }
    printf("%lld", ans);
    return 0;
}

