// i番目以降の品物から重さの輪がj以下になるように選んだ時の
// 取りうる価値の総和の最大値を返す関数
ll rec(ll i, ll j){
    ll res;
    if(i == N){
        // 品物がもう残っていないときは、価値の和の最大値は0で確定
        res = 0;
    }else if(j < w[i]){
        // 残りの容量が足りず品物iを入れられないので、入れないパターンだけ処理
        // i+1 以降の品物のみを使った時の最大値をそのままこの場合の最大値にする。
        res = rec(i+1,j);
    }else{
        // 品物iを入れるか入れないか選べるので、両方試して価値の和が大きいほうを選ぶ
        res=max(rec(i+1, j), rec(i+1, j-w[i])+v[i]);
    }
    return res;
}

