	Item(int w, int v) : weight(w), value(v) {}
};

const bool operator > (const Item a, const Item b) {
	return (a.value > b.value);
}

int main() {
	int n, w; scanf("%d %d", &n, &w);
	vector<Item> items(n, Item(0, 0));
	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &(items[i].weight), &(items[i].value));
	}

	long long rootW = items[0].weight;

	vector<vector<Item>> byweight(4, vector<Item>());

	for (int i = 0; i < n; ++i) {
		byweight[items[i].weight - rootW].push_back(items[i]);
	}

	for (int i = 0; i < 4; ++i) {
		sort(byweight[i].begin(), byweight[i].end(), greater<Item>());
	}


	vector<vector<ll>> prefixw(4, vector<ll>());
	for (int i = 0; i < 4; ++i) {
		prefixw[i] = vector<ll>(byweight[i].size() + 1, 0);
		for (int j = 1; j < prefixw[i].size(); ++j) {
			prefixw[i][j] = prefixw[i][j-1] + byweight[i][j-1].value;
			//printf("first %d items of weight %d have total value %d\n", j, rootW + i, prefixw[i][j]);
		}
	}

	ll maxval = 0;
	for (int rc = 0; rc <= byweight[0].size(); ++rc) {
		for (int rcp1 = 0; rcp1 <= byweight[1].size(); ++rcp1) {
			for (int rcp2 = 0; rcp2 <= byweight[2].size(); ++rcp2) {
				for (int rcp3 = 0; rcp3 <= byweight[3].size(); ++rcp3) {
					ll curw = (rootW * rc) + ((rootW + 1) * rcp1) + ((rootW + 2) * rcp2) + ((rootW + 3) * rcp3);
					//printf("selection of %d %d %d %d has total w %lld\n", rc, rcp1, rcp2, rcp3, curw);
					if (curw <= w) {
						maxval = max(maxval,
							prefixw[0][rc] + prefixw[1][rcp1] + prefixw[2][rcp2] + prefixw[3][rcp3]);
					}
				}
			}
		}
	}

	printf("%lld\n", maxval);
	return 0;
}

