long long dp[2][101][301] = {}; // turn, n put, rest
long long w[100] = {};
long long v[100] = {};

int main() {
  long long N, W, best = 0;
  scanf("%lld %lld", &N, &W);

  for (int i = 0; i < N; i++) {
    scanf("%lld %lld", w + i, v + i);
  }

  for (int i = 0; i < N; i++) {
    int cur = i % 2, prev = (i + 1) % 2;
    for (int j = 0; j < 101; j++) {
      for (int k = 0; k < 301; k++) {
	dp[cur][j][k] = 0;
      }
    }

    for (int j = 0; j <= i; j++) {
      for (int k = 0; k <= 300; k++) {
	int cost = w[0] * j + k;
	if (cost > W) continue;

	int prev_value = dp[prev][j][k];
	// do not use the i-th item
	if (dp[cur][j][k] < prev_value) {
	  dp[cur][j][k] = prev_value;
	}

	// use the i-th item
	cost += w[i];
	if (cost > W) continue;
	int next_value = prev_value + v[i];
	if (dp[cur][j + 1][k + w[i] - w[0]] < next_value) {
	  dp[cur][j + 1][k + w[i] - w[0]] = next_value;
	}
      }
    }

    if (i == N - 1) {
      for (int j = 0; j < 101; j++) {
	for (int k = 0; k < 301; k++) {
	  if (best < dp[cur][j][k]) {
	    best = dp[cur][j][k];
	  }
	}
      }
    }
  }

  printf("%lld\n", best);
  return 0;
}

