        return value;
    int ans = 0;
    rep(i, 0, cum_value[index].size())
    {
        ans = max(ans, dfs(index + 1, weight + weights[index] * i, value + cum_value[index][i]));
        // cout << cum_value[index][i]<<' '<<weight << endl;
    }
    return ans;
}

