int main(){
//	freopen("01.in", "r", stdin);
//	freopen("01.ans", "w", stdout);

	scanf("%d%d", &N, &W);

	LL m0 = 1e9;
	for(int i=1;i<=N;i++){
		scanf("%lld%lld", &w[i], &x[i]);
		m0 = min(m0, w[i]);
	}

	for(int i=1;i<=N;i++){
		if(w[i]==m0) v[0][++n0] = x[i];
		if(w[i]==m0+1) v[1][++n1] = x[i];
		if(w[i]==m0+2) v[2][++n2] = x[i];
		if(w[i]==m0+3) v[3][++n3] = x[i];
	}

	sort(v[0]+1, v[0]+1+n0, greater<int>());
	sort(v[1]+1, v[1]+1+n1, greater<int>());
	sort(v[2]+1, v[2]+1+n2, greater<int>());
	sort(v[3]+1, v[3]+1+n3, greater<int>());

	for(int i=1;i<=n3;i++){
		s[i] = s[i-1] + v[3][i];
	}

	LL ans = 0;
	for(int i=0;i<=n0;i++){
		for(int j=0;j<=n1;j++){
			for(int k=0;k<=n2;k++){
				if(i*m0 + j*(m0+1) + k*(m0+2) > W) continue;
				if(i) dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + v[0][i]);
				if(j) dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + v[1][j]);
				if(k) dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] + v[2][k]);

				ans = max(ans, dp[i][j][k] + s[(W - i*m0 - j*(m0+1) - k*(m0+2))/(m0+3)]);
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

