priority_queue<ll> que[4];
ll sum[4][101];
ll N, W, w0;
ll sz[4];

void solve() {
	cin >> N >> W;
	for (ll i = 0; i < N; i++) {
		ll w, v;
		cin >> w >> v;
		if (i == 0) w0 = w;
		que[w - w0].push(v);
	}

	for (ll i = 0; i < 4; i++) {
		sz[i] = que[i].size();
	}

	for (ll i = 1; i <= sz[0]; i++) {
		sum[0][i] += que[0].top() + sum[0][i-1];
		que[0].pop();
	}
	for (ll i = 1; i <= sz[1]; i++) {
		sum[1][i] += que[1].top() + sum[1][i - 1];
		que[1].pop();
	}
	for (ll i = 1; i <= sz[2]; i++) {
		sum[2][i] += que[2].top() + sum[2][i - 1];
		que[2].pop();
	}
	for (ll i = 1; i <= sz[3]; i++) {
		sum[3][i] += que[3].top() + sum[3][i - 1];
		que[3].pop();
	}

	ll ans = 0LL;

	for(ll i = 0; i <= sz[0]; i++)
		for (ll j = 0; j <= sz[1]; j++)
			for (ll k = 0; k <= sz[2]; k++)
				for (ll l = 0; l <= sz[3]; l++) 
					if (W >= i*w0 + j*(w0 + 1) + k*(w0 + 2) + l*(w0 + 3))
						ans = max(ans, (ll)sum[0][i] + sum[1][j] + sum[2][k] + sum[3][l]);

	cout << ans << endl;

}

int main() {
	solve();
	return 0;
}

