    vector<vector<int>> c(N+1, vector<int>(n));
    REP(i, N) dp[i][0] = 0;
    REP(i, N){
        REP(j, 905){
            if(dp[i+1][j] < dp[i][j]){
                chmax(dp[i+1][j], dp[i][j]);
                c[i+1][j] = c[i][j];
            }else if(dp[i+1][j] == dp[i][j]){
                chmin(c[i+1][j], c[i][j]);
            }

            if(dp[i][j]==-1) continue;

            if(dp[i+1][j+w[i]] < dp[i][j]+v[i]){
                chmax(dp[i+1][j+w[i]], dp[i][j]+v[i]);
                c[i+1][j+w[i]] = c[i][j] + 1;
            }else if(dp[i+1][j+w[i]] == dp[i][j]+v[i]){
                chmin(c[i+1][j+w[i]], c[i][j] + 1);
            }
        }
    }

    ll ans = 0;
    REP(i, N+1){
        REP(j, n){
            if(j<=(W-c[i][j]*w0)) chmax(ans, dp[i][j]);
        }
    }
