vector<int> get(int x, int y) {
	//cout << x << ' ' << y << endl;
	vector<int> res;
	for (int v : g[x]) {
		if (binary_search(all(g[y]), v)) {
			//cout << "FOUND " << v << endl;
			res.pb(v);
		}
	}

	return res;
}

vector<int> tryLR() {
	for (int r : g[0]) {
		vector<int> ans;

		int l = 0;
		ans.push_back(l);

		auto it = get(l, r);
		if (sz(it) != 1) {
			continue;
		}

		//cout << l << ' ' << r << ' ' << it << endl;
		int m = it[0];
		ans.push_back(m);
		ans.push_back(r);

		while (1) {
			auto it = get(m, r);

			if (sz(it) != 2) {
				return {};
			}

			int v = it[0];
			if (v == l) {
				v = it[1];
			}

			if (v == 0) {
				return ans;
			}

			ans.pb(v);

			l = m;
			m = r;
			r = v;
		}
	}
}

bool check(vector<int>& ans) {
	if (sz(ans) != n) {
		return false;
	}

	bool res = true;
	forn(i, n) {
		int x = ans[i];
		int y = ans[(i + 1) % n];
		if (x > y) {
			swap(x, y);
		}

		res &= bool(have.count({ x, y }));

		x = ans[i];
		y = ans[(i + 2) % n];
		if (x > y) {
			swap(x, y);
		}

		res &= bool(have.count({ x, y }));
	}

	return res;
}

