int dp[101][101][301];	//dp[i][j][k] = 商品i個見た. (今までにj個入れて)合計重さ = j * w[0] + kである. このときの, 価値max.

signed main() {
	int i, j, k;

	cin >> n >> W;
	for (i = 0; i < n; i++) cin >> w[i] >> v[i];

	for (i = 0; i <= n; i++) for (j = 0; j <= n; j++) for (k = 0; k <= 300; k++) dp[i][j][k] = -INF;
	dp[0][0][0] = 0;

	for (i = 0; i < n; i++) {
		for (j = 0; j <= i; j++) {
			for (k = 0; k <= 3 * i; k++) {
				dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k]);
				dp[i + 1][j + 1][k + w[i] - w[0]] = max(dp[i + 1][j + 1][k + w[i] - w[0]], dp[i][j][k] + v[i]);
			}
		}
	}

	int ans = 0;
	for (j = 0; j <= n; j++) {
		for (k = 0; k <= 300; k++) {
			if (j * w[0] + k <= W) {
				ans = max(ans, dp[n][j][k]);
			}
