		}
		return 1;
	}

	void init (const Input &input) {
		*this = input;
	}
};

struct Data: Input {
	int ans;

	void write () {
		cout << ans << endl;
	}
};


namespace Main {

	struct Solution: Data {
		int d[N + 1][N * K + 1];

		void solve () {
			memset(d, 0, sizeof d);
			forn (i, n) {
				ford (j, i + 1) {
					forn (k, i * K + 1) {
						umx(d[j + 1][k + w[i] - w[0]], d[j][k] + v[i]);
					}
				}
			}
			ans = 0;
			forn (i, m / w[0] + 1) {
				forn (j, min(n * K, m - i * w[0]) + 1) {
					umx(ans, d[i][j]);
				}
			}
		}

		void clear () {
			*this = Solution();
		}
	};
}


