	REP(i, N) {
		cin >> items[i].w >> items[i].v;
	}
	vector<vector<int>> eitems(min(4, N));
	REP(i, items.size()) {
		REP(j, eitems.size()) {
			if (items[0].w + j == items[i].w) {
				eitems[j].push_back(items[i].v);
			}
		}
	}
	REP(i, eitems.size()) {
		sort(eitems.begin(), eitems.end());
	}

	if (items[0].w > 3 * N) {
		int canTake = min(W / items[0].w, N);
		int take = 0;
		int remainW = W;
		LONG sum = 0;
		REP(i, N) {
			int idx = 0;
			int maxV = 0;
			REP(j, eitems.size()) {
				if (eitems[j].size() > 0 && remainW - (items[0].w + idx) >= 0 &&
					eitems[j][eitems[j].size() - 1] >= maxV) {
					idx = j;
					maxV = eitems[j][eitems[j].size() - 1] / (items[0].w + idx);
				}
			}
			sum += eitems[idx][eitems.size() - 1];
			remainW -= items[0].w + idx;
			eitems[idx].erase(eitems[idx].end() - 1);
		}
		cout << sum << endl;
	}
	else {
		if (W >= (items[0].w + 3) * N) {
			LONG sum = 0;
			REP(i, N) {
				sum += items[i].v;
			}
			cout << sum << endl;
		}
		else {
			vector<LONG> dp(W + 1);
			REP(i, W) {
				dp[i] = 0;
			}
			REP(j, N) {
				for (int i = W; i >= 0; i--) {
					if (i - items[j].w >= 0) {
						dp[i] = max(dp[i], dp[i - items[j].w] + items[j].v);
					}
				}
			}
			LONG ans = 0;
			REP(i, W + 1) {
				ans = max(dp[i], ans);
			}
			cout << ans << endl;
		}
	}
	return 0;
}

