const int maxn = 100 + 5;

long long n;
long long W;
long long w[maxn], ww[maxn], v[maxn];
long long f[maxn][3 * maxn];

long long check(long long K)
{
    memset(f, 0, sizeof f);
    long long rem = std::min(W - K * w[1], 3 * K);
    if (rem < 0) return 0;
    for (int i = 1; i <= n; ++ i)
        for (int j = i; j; -- j)
            for (int k = rem; k >= ww[i]; -- k)
                chkmax(f[j][k], f[j - 1][k - ww[i]] + v[i]);
    long long ret = 0;
    for (int j = 0; j <= rem; ++ j) chkmax(ret, f[K][j]); 
    return ret;
}

void exec()
{
    read(n), read(W);
    for (int i = 1; i <= n; ++ i) {
        read(w[i]);
        read(v[i]);
        ww[i] = w[i] - w[1];
    }
    int l = 1, r = n, mid1, mid2;
    while (l + 5 < r) {
        mid1 = (l + l + r) / 3;
        mid2 = (l + r + r) / 3;
        if (check(mid1) < check(mid2))
            l = mid1;
        else
            r = mid2;
    }
    long long ans = 0;
    for (int i = l; i <= r; ++ i) chkmax(ans, check(i));
    write(ans);
}

