void dfs(ll value,ll weight,int dep) {
	//cout<<value<<endl;
	ans = max(ans, value);

	if(dep>=cnt)return;

	for(int i=0;i<=q[dep].size();i++) {
		if(i*q[dep][0].w + weight>w)break;
		ll tmp = 0;
		for(int j=0;j<i;j++)tmp+=q[dep][j].val;
		dfs(value+tmp, weight+i*q[dep][0].w, dep+1);
	}

	return;
}

bool cmp(const node &v1, const node &v2) {
	return v1.val > v2.val;
}

