    if( scanf("%ld", &x) <= 0 ) exit(0);
    return *this;
  }
  S002& operator >= (double& x) {
    if( scanf("%lf", &x) <= 0 ) exit(0);
    return *this;
  }
  S002& operator >= (std::string& s) {
    if( not (std::cin >> s) ) exit(0);
    return *this;
  }
  template<typename a>
  S002& operator >= (std::vector<a>& v) {
    v.resize(n);
    for(long i = 0; i < n; ++i) {
      *this >= v[i];
    }
    return *this;
  }
  template<typename a, std::size_t s>
  S002& operator >= (std::array<a, s>& x) {
    for(long i = 0; i < (long)s; ++i) {
      *this >= x[i];
    }
    return *this;
  }
};


struct Solver {
  long n, w;
  std::vector<long> ws, vs;
  Solver() {
    S002 reader;
    std::vector<std::array<long, 2>> ys;
    reader >= n >= w >n>= ys;
    for(auto y : ys) {
      ws.push_back(y[0]);
      vs.push_back(y[1]);
    }
  }
  long dp[128][512];
  void solve() {
    for(long i = 0; i < 128; ++i) {
      for(long j = 0; j < 512; ++j) {
        dp[i][j] = 0;
      }
    }
    for(long k = 0; k < n; ++k) {
      for(long i = n; i >= 0; --i) {
        for(long j = 0; j < 512; ++j) {
          if( j-(ws[k]-ws[0]) < 0 ) continue;
          if( i - 1 < 0 ) continue;
          dp[i][j] = std::max(dp[i][j], dp[i-1][j-(ws[k]-ws[0])] + vs[k]);
        }
      }
    }
    long res = 0;
    for(long i = 0; i <= n; ++i) {
      for(long j = 0; j < 512; ++j) {
        if( i * ws[0] + j > w ) continue;
        res = std::max(res, dp[i][j]);
      }
    }
    printf("%ld\n", res);        
  }    
  ~Solver() { fprintf(stderr, "--end--\n"); }
};


int main() {
  loop std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

