template<typename T>
vector<vector<vector<T>>>
Make3DVector(int d1, int d2, int d3, T default_value) {
  return vector<vector<vector<T>>>(
      d1, vector<vector<T>>(d2, vector<T>(d3, default_value)));
}

template<class T> inline bool UpdateMin(T& a, T b) {
  if (a > b) { a = b; return 1; } return 0;
}

template<class T> inline bool UpdateMax(T& a, T b) {
  if (a < b) { a = b; return 1; } return 0;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  int64 cap;
  cin >> n >> cap;
  vector<int64> ws(n);
  vector<int64> vs(n);
  for (int i = 0; i < n; i++) {
    cin >> ws[i];
    cin >> vs[i];
  }

  int64 base = ws[0];
  for (int i = 0; i < n; i++) {
    ws[i] -= base;
  }

  auto solve_m = [&](int m) -> int64 {
    int64 m_cap = cap - base * m;
    if (m_cap <= 0) return 0;

    if (m_cap >= 3 * m) m_cap = 3 * m;
    auto dp = Make3DVector(n + 1, m + 1, m_cap + 1, 0LL);
    for (int i = 0; i < n; i++) {
      for (int k = 0; k <= m; k++) {
        for (int w = 0; w <= m_cap; w++) {
          int new_w = w + ws[i];
          if (k + 1 <= m && new_w <= m_cap) {
            UpdateMax(dp[i + 1][k + 1][new_w], dp[i][k][w] + vs[i]);
          }
          UpdateMax(dp[i + 1][k][w], dp[i][k][w]);
        }
      }
    }

    int64 max = 0;
    for (int k = 0; k <= m; k++) {
      for (int w = 0; w <= m_cap; w++) {
        UpdateMax(max, dp[n][k][w]);
      }
    }
    return max;
  };

  int64 ans = 0;
  for (int i = 1; i <= n; i++) {
    UpdateMax(ans, solve_m(i));
  }
  cout << ans << endl;
}

