    ll N, W;
    cin >> N >> W;

    vector<p> inputs(N);
    vector<ll> V[4];
    ll min_weight = INF;
    for (ll i = 0; i < N; i++) {
        ll w, v;
        cin >> w >> v;
        inputs[i] = p(w, v);
        min_weight = min(min_weight, w);
