int solve (int a, int b, int c, int d, int weight) {
    vector<int> results;
    results.reserve(4);
    //cout << a << " " << b << " " << c << " " << d << endl;
    bool f1 = (x[1][b] <= x[0][a]);
    bool f2 = (x[2][c] <= x[1][b]) || f1;
    bool f3 = (x[3][d] <= x[2][c]) || f1;

    if (a < x[0].size () - 1 && w0 + 0 <= weight) {
        results.push_back (x[0][a] + solve (a + 1, b, c, d, weight - (w0 + 0)));
    }
    if (b < x[1].size () - 1 && w0 + 1 <= weight && !f1) {
        results.push_back (x[1][b] + solve (a, b + 1, c, d, weight - (w0 + 1)));
    }
    if (c < x[2].size () - 1 && w0 + 2 <= weight && !f2) {
        results.push_back (x[2][c] + solve (a, b, c + 1, d, weight - (w0 + 2)));
    }
    if (d < x[3].size () - 1 && w0 + 3 <= weight && !f3) {
        results.push_back (x[3][d] + solve (a, b, c, d + 1, weight - (w0 + 3)));
    }

    int result = 0;
    for (auto e : results) {
        result = max (e, result);
    }
    return result;
}

