        sort(sv[k].begin(), sv[k].end(), greater<llong>());

        sv[k].push_back(0);
        for (int i = sv[k].size() - 1; i > 0; i--) {
            swap(sv[k][i], sv[k][i - 1]);
        }
    }
    for (int k = 0; k < 4; k++) {
        for (int i = 1; i < sv[k].size(); i++) {
            sv[k][i] += sv[k][i - 1];
        }
    }

