int n;
int W;
int w[120];
int v[120];
int dp[120][350];

int main() {
    cin >> n >> W;
    for (int i = 0; i < n; ++i)
        cin >> w[i] >> v[i];
    int ans = 0;
    int mx = 3 * n;
    for (int i = 0; i < n; ++i) {
        int c = w[i] - w[0];
        for (int j = i; j >= 0; --j) {
            for (int k = mx - c; k >= 0; --k)
                dp[j + 1][k + c] = max(dp[j + 1][k + c], dp[j][k] + v[i]);
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (w[0] * i > W)
            break;
        ans = max(ans, dp[i][min(mx, W - w[0] * i)]);
    }
    cout << ans << "\n";
    return 0;
}

