map<long long int, long long int>M[100][101];
long long int ans;

int main() {
	ios::sync_with_stdio(false);
	cin >> N >> W;
	for (int i = 0; i < N; i++)cin >> w[i] >> v[i];
	int box = w[0];
	for (int i = 0; i < N; i++)w[i] -= box;
	if(w[0]+box<=W)M[0][1][0] = v[0];
	for (int i = 0; i < N - 1; i++) {
		for (int j = 0; j < N; j++) {
			if (!j) {
				if (w[i+1]+box > W)continue;
				M[i + 1][j + 1][w[i]] = v[i];
				ans = max(M[i + 1][j + 1][w[i]], ans);
				continue;
			}
			for (int k = j*-3; k <= j * 3; k++) {
				if (k + w[i + 1] + box*(j + 1) > W)continue;
				if (M[i][j][k]) {
					M[i + 1][j + 1][k + w[i]] = max(M[i][j][k] + v[i + 1], M[i + 1][j + 1][k + w[i]]);
					ans = max(ans, M[i + 1][j + 1][k + w[i]]);
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

