Int w[N_MAX];
Int v[N_MAX];

void solve() {
    cin >> N >> W;
    REP(i, N){
        cin >> w[i + 1] >> v[i + 1];
    }
    REP(i, W + 1) {
        dp[0][i] = 0;
    }
    for(int i = 1; i <= N; i++) {
        for(int j = 0; j <= W; j++) {
            Int v0 = dp[i-1][j];
            Int v1 = (w[i] <= j) ? dp[i-1][j - w[i]] + v[i] : 0;
            dp[i][j] = max(v0, v1);
        }
    }

    cout << dp[N][W] << endl;
}

