Int maxv(Int i, Int k, Int dw, vint3d &list_maxv, vint &list_v, vint &list_dw) {
  Int INF = Int(pow(10, 9));

  if (i == 0) {
    if (k == 0 && dw == 0) return 0;
    else return -INF;
  } else if (k == 0) {
    if (dw == 0) return 0;
    else return -INF;
  } else if (dw < 0) {
    return -INF;
  } else if (list_maxv[i][k][dw] != -1) {
    return list_maxv[i][k][dw];
  } else {
    Int v0 = list_v[i - 1] + maxv(i - 1, k - 1, dw - list_dw[i - 1], list_maxv, list_v, list_dw);
    Int v1 = maxv(i - 1, k, dw, list_maxv, list_v, list_dw);

    Int result = max(v0, v1);
    list_maxv[i][k][dw] = result;
    return result;
  }
}

