            for (int k = 3 * N; k >= A[i].x; --k) {
                chkmax(dp[j][k], dp[j-1][k-A[i].x] + A[i].y);
            }
        }
    }

    int ans = 0;
    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j <= 3 * N && (LL)i * base + j <= W; ++j) {
            chkmax(ans, dp[i][j]);
        }
    }
    printf("%d\n", ans);
}

