{
    for(int i = 1; i <= N; ++i)
    {
        for(int j = 1; j <= C; ++j)
        {
            if (weight[i - 1] > j)
                selective[i][j] = selective[i - 1][j];
            else
                selective[i][j] = max(selective[i - 1][j], selective[i - 1][j - weight[i - 1]] + value[i - 1]);
        }
    }
    return selective[N][C];
}
