using namespace std;

long long knapsack(long long max_weight, vector<long long> weight, vector<long long> profit) {
    long long items_quantity = profit.size();
    long long knap[items_quantity+1][max_weight+1];

    for(long long i = 0; i <= items_quantity; i++) {
        for(long long w = 0; w <= max_weight; w++) {
            if (i == 0 || w == 0)
                knap[i][w] = 0;
            else if (weight[i-1] <= w)
                knap[i][w] = max(profit[i-1]+knap[i-1][w-weight[i-1]], knap[i-1][w]);
            else
                knap[i][w] = knap[i-1][w];
        }
    }

    return knap[items_quantity][max_weight];
}

int main() {
    long long N, W;
    cin >> N >> W;

    vector<long long> weight(N), profit(N);
    for(long long i = 0; i < N; i++)
        cin >> weight[i] >> profit[i];

    long long ans = knapsack(W, weight, profit);
    cout << ans << '\n';

    return 0;
}

