const int maxn = 110;

int w[maxn], v[maxn];
priority_queue<int> item[4];
int f[4][maxn];
int s[maxn];

int main()
{
	//freopen("D.in","r",stdin);
	int n,W;
	scanf("%d%d",&n,&W);
	for (int i=1;i<=n;i++)
	{
		scanf("%d%d",&w[i], &v[i]);
		if (i==1) 
		{
			item[0].push(v[1]);
			continue;
		}
		item[w[i] - w[1]].push(v[i]);
	}
	for (int i=0;i<=3;i++)
	{
		s[i] = item[i].size();
		f[i][0] = 0;
		int tmp = item[i].size();
		if (!item[i].empty()) f[i][1] = item[i].top(), item[i].pop();
		for (int j=2;j<=tmp;j++)
		{
			f[i][j] = f[i][j-1] + item[i].top();
			item[i].pop();
		}
	}

	int ans = 0;
	for (int i=0;i<=s[0];i++)
	{
		for (int j=0;j<=s[1];j++)
		{
			for (int k=0;k<=s[2];k++)
			{
				int left = W - (i * w[1] + j * (w[1]+1) + k * (w[1]+2));
				//cout<<left<<endl;
				if (left < 0) continue;
				int l = left / (w[1]+3);
				l = min(l,s[3]);
				ans = max(ans, f[0][i] + f[1][j] + f[2][k] + f[3][l]);
			}
		}
	}
	printf("%d\n",ans);
	return 0;
}

