const int MAX_N = 105;

struct Node
{
  int v, w;

  Node () {}

  Node (int v_, int w_) : v(v_), w(w_) {}

  bool operator < (const Node &b) const
  {
    return v > b.v;
  }
};

int N, W;
int w1;
vector<Node> v[4];
int s[4][MAX_N];

int Bs(int l, int r, int tmp_w)
{
  while (r - l > 1) {
    int mid = (l + r) / 2;
    if (tmp_w + s[3][mid] <= W) l = mid;
    else r = mid;
  }
  return l;
}

int main()
{
  #ifdef OJ
    freopen("/home/linjian/Documents/cpp_programs/in.txt", "r", stdin);
  #endif
  cin >> N >> W;
  int v1; scanf("%d%d", &w1, &v1);
  v[0].push_back(Node(v1, w1));
  for (int i = 1; i < N; ++i) {
    int tmp_w, tmp_v; scanf("%d%d", &tmp_w, &tmp_v);
    v[tmp_w - w1].push_back(Node(tmp_v, tmp_w));
  }
  for (int i = 0; i < 4; ++i) {
    sort(v[i].begin(), v[i].end());
    s[i][0] = 0;
    for (int j = 0; j < (int)v[i].size(); ++j) {
      s[i][j + 1] = s[i][j] + v[i][j].v;
    }
  }
  int max_v = 0;
  for (int i = 0; i <= (int)v[0].size(); ++i) {
    int tmp_w = i ? v[0][i - 1].w : 0;
    int tmp_v = i ? v[0][i - 1].v : 0;
    for (int j = 0; j <= (int)v[1].size(); ++j) {
      tmp_w += j ? v[1][j - 1].w : 0;
      tmp_v += j ? v[1][j - 1].v : 0;
      for (int k = 0; k <= (int)v[2].size(); ++k) {
        tmp_w += k ? v[2][k - 1].w : 0;
        tmp_v += k ? v[2][k - 1].v : 0;
        // if (i == 1 && k == 1) printf("tmp_w=%d\ttmp_v=%d\n", tmp_w, tmp_v);
        if (tmp_w > W) continue;
        int l = Bs(0, (int)v[3].size() + 1, tmp_w);
        tmp_v += l ? v[3][l - 1].v : 0;
        max_v = max(max_v, tmp_v);
        // if (max_v < tmp_v) {
          // max_v = tmp_v;
          // printf("w:%d\tw+1:%d\tw+2:%d\tw+3:%d\n", i, j, k, l);
        // }
      }
    }
  }
  printf("%d\n", max_v);
  return 0;
}

