int zeroOnePack(int N, int C, vector<int>& weight, vector<int>& value)
{
    vector<unordered_map<int, int>> select(N+1, unordered_map<int, int>());
    for(int i = 1; i <= N; ++i)
    {
        for(int j = 1; j <= C; ++j)
        {
            if (weight[i - 1] > j)
                select[i][j] = select[i - 1][j];
            else
                select[i][j] = max(select[i - 1][j], select[i - 1][j - weight[i - 1]] + value[i - 1]);
        }
    }
    return select[N][C];
}
