int N;
ll W;
ll w[110], v[110];
vector<ll> key;
vector<ll> val[4];
int sz;

map<ll, ll> memo;

ll calc(int k, ll rem) {
    if (k == sz) return 0;
    ll idx = rem * 10 + k;
    if (memo.count(idx) == 0) {
        ll res = calc(k+1, rem), sum = 0;
        for (int i = 0; i < val[k].size() && key[k]*(i+1) <= rem; i++) {
            sum += val[k][i];
            res = max(res, sum + calc(k+1, rem - key[k]*(i+1)));
        }
        memo[idx] = res;
    }
    return memo[idx];
}

ll solve() {
    for (int i = 0; i < N; i++) key.push_back(w[i]);
    sort(ALL(key));
    UNIQ(key);
    sz = key.size();
    map<ll, int> m;
    for (int i = 0; i < sz; i++) m[key[i]] = i;
    for (int i = 0; i < N; i++) val[m[w[i]]].push_back(v[i]);
    for (int i = 0; i < sz; i++) sort(RALL(val[i]));

    return calc(0, W);
}

void input() {
    cin >> N >> W;
    for (int i = 0; i < N; i++) cin >> w[i] >> v[i];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(15);

    input();
    cout << solve() << endl;
}

