                if (b > 0 && sw <= W)
                {
                    dp[i + 1][a][b][c][d] = MAX(dp[i][a][b][c][d], dp[i][a][b - 1][c][d] + v[i]);
                }
                else
                {
                    dp[i + 1][a][b][c][d] = dp[i][a][b][c][d];
                }
