                }
                else
                {
                    dp[i + 1][a][b][c][d] = dp[i][a][b][c][d];
                }
                break;
            case 3:
                if (d > 0 && sw <= W)
                {
                    dp[i + 1][a][b][c][d] = MAX(dp[i][a][b][c][d], dp[i][a][b][c][d - 1] + v[i]);
                }
                else
                {
                    dp[i + 1][a][b][c][d] = dp[i][a][b][c][d];
                }
                break;
            default:
                return 0;
                break;
            }
        }
    }

    s64 ans = 0;
    rep (a, A + 1) rep (b, B + 1) rep (c, C + 1) rep (d, D + 1)
    {
