using namespace std;

int N,W;
int Wbase;
int itemV[101];
int itemW[101];
int dpV[101][301][303];

int calc(int depth,int space, int cap) {
	int& V = dpV[depth][space][cap];
	int result = 0;
	if (V != -1)return V;
	else if (depth == N - 1) {
		if (space) {
			if (cap >= itemW[depth]) {
				return V = itemV[depth];
			}
			else if (space >= 2) {
				return V = calc(depth, space - 1, min(cap + Wbase, 300));
			}
		}
		else {
			return (V=0);
		}
	}
	else {
		if (space) {
			if (cap >= itemW[depth]) {
				result = itemV[depth] + calc(depth + 1, space - 1, cap - itemW[depth]);
			}
			else  if (space >= 2) {
				result = calc(depth, space - 1, min(cap + Wbase, 300));
			}
		}
		else result = 0;
		return V = max(calc(depth + 1, space, cap), result);
	}
}
int main() {

	cin >> N >> W;
	cin >> itemW[0] >> itemV[0];
	Wbase = itemW[0];
	for (int i = 1; i < N; i++)
	{
		cin >> itemW[i] >> itemV[i];
		itemW[i] -= Wbase;
	}
	for (int i = 0; i < 100; i++)
	{
		for (int j = 0; j < 300; j++)
		{
			for (int k = 0; k < 300; k++)
			{
				dpV[i][j][k] = -1;
			}
		}
	}

	cout << calc(0, min(W / Wbase, 300), min(W % Wbase, 300));
	return 0;
}

