int main() {
    int N, W; cin >> N >> W;
    vector<int> w(N), v(N);
    vector<int> w1, w2, w3, w4;
    rep(i, N){
        cin >> w[i] >> v[i];
    }
    ll w0 = w[0];
    rep(i, N){
        if(w[i] == w0){
            w1.push_back(v[i]);
        } else if(w[i] == w0 + 1){
            w2.push_back(v[i]);
        } else if(w[i] == w0 + 2){
            w3.push_back(v[i]);
        } else {
            w4.push_back(v[i]);
        }
    }
    sort(w1.begin(), w1.end());
    sort(w2.begin(), w2.end());
    sort(w3.begin(), w3.end());
    sort(w4.begin(), w4.end());

    int w1s = w1.size();
    int w2s = w2.size();
    int w3s = w3.size();
    int w4s = w4.size();

    ll ans = 0;

    for (int i = 0; i <= w1s; i++){
        for (int j = 0; j <= w2s; j++){
            for (int k = 0; k <= w3s; k++){
                for (int l = 0; l <= w4s; l++){
                    ll total = w0 * (i+j+k+l) + j + k*2 + l*2;
                    if(total > W)break;
                    ll kouho = 0;
                    for (int m = w1s-1; m >= w1s-1-i+1; m--){
                        kouho += w1[m];
                    }
                    for (int m = w2s-1; m >= w2s-1-j+1; m--){
                        kouho += w2[m];
                    }
                    for (int m = w3s-1; m >= w3s-1-k+1; m--){
                        kouho += w3[m];
                    }
                    for (int m = w4s-1; m >= w4s-1-l+1; m--){
                        kouho += w4[m];
                    }
                    ans = max(ans, kouho);
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

