typedef struct {
  int key1;
  int key2;
}table;

int comp(const void *a,const void *b){
  table *p1 = (table*)a;
  table *p2 = (table*)b;

  if(p1->key1 != p2->key1)
    return p1->key1 - p2->key1;
  else
    return p1->key2 - p2->key2;
}


int ans[100001][100001];

int greedy_knapsack(table *item,int n,int w){
  int i,j;

  for(i=0;i<=w;i++){
    for(j=0;j<=n;j++){
      if(i == 0 || j == 0)
        ans[i][j] = 0;
      else if(item[j-1].key1 <= i)
        ans[i][j] = max( item[j-1].key2 + ans[i - item[j-1].key1][j-1] , ans[i][j-1]);
      else
        ans[i][j] = ans[i][j-1];

      cout << ans[i][j] << endl;
    }
  }
  return ans[w][n];
}


int main()
{
  int i,j,n,w;
  cin >> n >> w;
  table item[100001] = {};
  for(i=0;i<n;i++){
    cin >> item[i].key1 >> item[i].key2;  //key1 = weight, key2 = value
  }

  qsort(item,n,sizeof(table),comp);

  cout << greedy_knapsack(item,n,w) << endl;

  return 0;
}

