typedef long long int LL;

LL N, W, v[112], w[112];
std::pair<LL, LL> ps[1 << 20];

int main()
{
	in >> N >> W;
	rep(i, N) { in >> w[i] >> v[i]; }
	LL N2 = N / 2;
	rep(i, 1 << N2)
	{
		LL sw = 0, sv = 0;
		for (int j = 0; j < N2; ++j)
		{
			if (i >> j & 1)
			{
				sw += w[j];
				sv += v[j];
			}
		}
		ps[i] = std::make_pair(sw, sv);
	}
	std::sort(ps, ps + (1 << N2));
	LL m = 1;
	for (int i = 1; i < 1 << N2; ++i)
	{
		if (ps[m - 1].second < ps[i].second)
		{
			ps[m++] = ps[i];
		}
	}

	LL ans = 0;
	for (int i = 0; i < 1 << (N - N2); i++)
	{
		LL sw = 0, sv = 0;
		rep(j, N - N2)
		{
			if (i >> j & 1)
			{
				sw += w[N2 + j];
				sv += v[N2 + j];
			}
		}
		if (sw <= W)
		{
			LL tv = (std::lower_bound(ps, ps + m, std::make_pair(W - sw, INF)) - 1)->second;
			ans = std::max(ans, sv + tv);
		}
	}
	out << ans << std::endl;
	return 0;
}

