int sDP[101][301][101];

int saved;

int dp(short index, int weight, int cnt) {
	int &ret = sDP[index][weight][cnt];
	if (ret != -1) return ret;

	if (weight + cnt*saved > w) return -1000000000;

	if (index == n-1) {
		weight += weights[index];
		cnt++;
		if (weight + cnt*saved > w) {
			return ret = 0;
		} else {
			return ret = values[index];
		}
	}

	ret = max(dp(index+1, weight, cnt), dp(index+1, weight + weights[index], cnt+1) + values[index]);

	return ret;
}

