    take( ll w[], ll nowv ) {
      t[ 0 ] = w[ 0 ];
      t[ 1 ] = w[ 1 ];
      t[ 2 ] = w[ 2 ];
      t[ 3 ] = w[ 3 ];
      sm = 0;
      for ( int i = 0 ; i < 4 ; ++i )
