	for(int i=1;i<=n;++i){
		cin>>a>>b;
		if(i==1)mm=a; a-=mm;
		V[a].push_back(b);
	}

	for(int i=0;i<4;++i){
		V[i].push_back((ll)1e18);
		sort(V[i].begin(),V[i].end(),cmp);
		V[i][0]=0;
		for(int j=1;j<V[i].size();++j)
			V[i][j]+=V[i][j-1];
	}

	ll ans=0;

	for(ll i=0;i<V[0].size();++i){
		if(i*mm>m)break;
		for(ll j=0;j<V[1].size();++j){
