vvi cache;
vi VS;
vi WS;

ll knapsack(int n, int maxw) {
  if (n == -1) {
    return 0;
  }
  int v = VS[n];
  int w = WS[n];
  if (cache[n][maxw] != -1) {
    return cache[n][maxw];
  } else {
    ll ans = 0;
    if (maxw < w) {
      ans = knapsack(n-1, maxw);
    } else {
      ans = max(knapsack(n-1, maxw-w) + v, knapsack(n-1, maxw));
    }
    cache[n][maxw] = ans;
    return ans;
  }
}

int main() {
  int n, maxw;
  scanf("%d%d", &n, &maxw);
  VS = vi(n, 0);
  WS = vi(n, 0);
