  for (size_t i = 0; i < n; i++) {
    int w, v;
    scanf("%d%d", &w, &v);
    WS[i] = w;
    VS[i] = v;
  }
  ll ans = knapsack(n-1, maxw);
  cout << ans << endl;
  return 0;
}

