int main() {
	int N, W, w, wf, v;
	cin >> N >> W;
	for (int i = 0;i < N;i++) {
		cin >> w >> v;
		if (i == 0) wf = w;
		V[w - wf].push_back(v);
	}
	int vs[4];
	for (int i = 0;i < 4;i++) {
		sort(all(V[i]));
		reverse(all(V[i]));
		vs[i] = V[i].size();
		for (int j = 1;j < vs[i];j++)
			V[i][j] += V[i][j - 1];
	}
	int tw, alv, ans = 0;
	for (int i = 0;i <= vs[0];i++) {
		tw = W - i * wf;
		if (tw < 0) break;

		for (int j = 0;j <= vs[1];j++) {
			tw = W - i * wf - j * (wf + 1);
			if (tw < 0) break;

			for (int k = 0;k <= vs[2];k++) {
				tw = W - i * wf - j * (wf + 1) - k * (wf + 2);
				if (tw < 0) break;

				for (int l = 0;l <= vs[3];l++) {
					tw = W - i * wf - j * (wf + 1) - k * (wf + 2) - l * (wf + 3);
					if (tw < 0) break;

					alv = 0;
					if (i) alv += V[0][i - 1];
					if (j) alv += V[1][j - 1];
					if (k) alv += V[2][k - 1];
					if (l) alv += V[3][l - 1];
					//cout << alv << endl;
					ans = max(ans, alv);
				}
			}
