void init() { 
  base = w[0];
  rep(i,N) w[i] -= base;
}

void compute() {
  init();
  ll ans = 0;
  REP(use,1,N+1) {
    ll new_W = W - use * base;
    if( new_W < 0LL ) break;
    ll size = min(new_W+1LL,3LL*use+10LL);
    memset(dp,-1,sizeof dp);
    dp[0][0] = 0;
    rep(i,N) {
      for(int j=use-1;j>=0;--j) {
	rep(k,size+1) {
	  if( dp[j][k] == -1 ) continue;
	  if( k+w[i] <= size ) {
	    dp[j+1][k+w[i]] = max(dp[j+1][k+w[i]],
				  dp[j][k]+v[i]);
	  }
	}
      }
    }
    ll maxi = -1;
    rep(i,size) maxi = max(maxi,dp[use][i]);
    if( maxi != -1 ) ans = max(ans,maxi);
  }
  cout << ans << endl;
}

