#include <bits/stdc++.h>

using namespace std;


int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n, W;
  cin >> n >> W;
  map<int, vector<int>> mp;
  for (int i = 0; i < n; i++) {
    int w, v;
    cin >> w >> v;
    mp[w].push_back(v);
  }
  vector<long long> ws;
  for (auto& it : mp) {
    ws.push_back(it.first);
    sort(it.second.rbegin(), it.second.rend());
    for (int j = 1; j < (int) it.second.size(); j++) {
      it.second[j] += it.second[j - 1];
    }
  }
  int ans = 0;
  if (ws.size() == 1) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      if (i * ws[0] > W) {
        break;
      }
      ans = max(ans, i == 0 ? 0 : mp[ws[0]][i - 1]);
    }
  } else if (ws.size() == 2) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      for (int j = 0; j <= mp[ws[1]].size(); j++) {
        if (i * ws[0] + j * ws[1] > W) {
          break;
        }
        ans = max(ans,
          (i == 0 ? 0 : mp[ws[0]][i - 1])
          + (j == 0 ? 0 : mp[ws[1]][j - 1])
        );
      }
    }
  } else if (ws.size() == 3) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      for (int j = 0; j <= mp[ws[1]].size(); j++) {
        for (int k = 0; k <= mp[ws[2]].size(); k++) {
          if (i * ws[0] + j * ws[1] + k * ws[2] > W) {
            break;
          }
          ans = max(ans,
            (i == 0 ? 0 : mp[ws[0]][i - 1])
            + (j == 0 ? 0 : mp[ws[1]][j - 1])
            + (k == 0 ? 0 : mp[ws[2]][k - 1])
          );
        }
      }
    }
  } else if (ws.size() == 4) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      for (int j = 0; j <= mp[ws[1]].size(); j++) {
        for (int k = 0; k <= mp[ws[2]].size(); k++) {
          long long cur_w = i * ws[0] + j * ws[1] + k * ws[2];
          long long rem_w = W - cur_w;
          if (rem_w < 0) {
            continue;
          }
          int l = min(n - i - j - k, (int) (rem_w / ws[3]));
          if (l < 0 || l > (int) mp[ws[3]].size()) {
            continue;
          }
          if (i * ws[0] + j * ws[1] + k * ws[2] + l * ws[3] > W) {
            continue;
          }
          ans = max(ans, 
            (i == 0 ? 0 : mp[ws[0]][i - 1]) 
            + (j == 0 ? 0 : mp[ws[1]][j - 1]) 
            + (k == 0 ? 0 : mp[ws[2]][k - 1]) 
            + (l == 0 ? 0 : mp[ws[3]][l - 1])
          );
        }
      }
    }
  } else {
    assert(false);
  }
  cout << ans << '\n';
  return 0;
}

