int n,W,v[101],w[101],dp[101][400];

int solve(int i,int sum){
    if(sum<0)return 0;
    if(i==n)return 0;
    if(dp[i][W-sum]!=0)return dp[i][W-sum];
    else{
        dp[i][W-sum]=solve(i+1,sum);
        if(sum-w[i]>=0){
            dp[i][W-sum]=max(solve(i+1,sum),solve(i+1,sum-w[i])+v[i]);
        }
        return dp[i][W-sum];
    }
}

