  const long w0 = ws[0];
  vector<vector<long>> vss(4, vector<long>());
  for (int i = 0; i < N; i++) {
    vss[ws[i] - w0].push_back(vs[i]);
  }
  for (int k = 0; k < 4; k++) {
    sort(vss[k].begin(), vss[k].end(), greater<long>());
  }

  // search all
  long ans = 0;
  long total_v0 = 0, total_w0 = 0;
  for (int i0 = 0; i0 <= vss[0].size(); i0++) {
    total_v0 += i0 > 0 ? vss[0][i0 - 1] : 0;
    total_w0 += i0 > 0 ? w0 : 0;
    long total_v1 = 0, total_w1 = 0;
    for (int i1 = 0; i1 <= vss[1].size(); i1++) {
      total_v1 += i1 > 0 ? vss[1][i1 - 1] : 0;
      total_w1 += i1 > 0 ? w0 + 1 : 0;
      long total_v2 = 0, total_w2 = 0;
      for (int i2 = 0; i2 <= vss[2].size(); i2++) {
        total_v2 += i2 > 0 ? vss[2][i2 - 1] : 0;
        total_w2 += i2 > 0 ? w0 + 2 : 0;
        long total_v3 = 0, total_w3 = 0;
        for (int i3 = 0; i3 <= vss[3].size(); i3++) {
          total_v3 += i3 > 0 ? vss[3][i3 - 1] : 0;
          total_w3 += i3 > 0 ? w0 + 3 : 0;
          if (total_w0 + total_w1 + total_w2 + total_w3 <= W) {
            ans = max(ans, total_v0 + total_v1 + total_v2 + total_v3);
          }
        }
      }
    }
  }
  printf("%ld\n", ans);
}

