    vector<int> num_w(4);
    for(int i = 0; i < N; ++i) ++num_w[w[i]-w[0]];

    dp[1][0][0][0] = v[0];
    for(int n = 1; n < N; ++n){
        for(int i = num_w[0]; i >= 0; --i){
            for(int j = num_w[1]; j >= 0; --j){
                for(int k = num_w[2]; k >= 0; --k){
                    for(int l = num_w[3]; l >= 0; --l){
                        if(w[n]-w[0] == 0){
                            dp[i+1][j][k][l] = max(dp[i][j][k][l]+v[n], dp[i+1][j][k][l]);
                        }
                        if(w[n]-w[0] == 1){
                            dp[i][j+1][k][l] = max(dp[i][j][k][l]+v[n], dp[i][j+1][k][l]);
                        }
                        if(w[n]-w[0] == 2){
                            dp[i][j][k+1][l] = max(dp[i][j][k][l]+v[n], dp[i][j][k+1][l]);
                        }
                        if(w[n]-w[0] == 3){
                            dp[i][j][k][l+1] = max(dp[i][j][k][l]+v[n], dp[i][j][k][l+1]);
