                for(int l = 0; l <= num_w[3]; ++l){
                    if(i+j+k+l <= N and w[0]*(i+j+k+l)+j+2*k+3*l <= W){
                        ans = max(ans, dp[i][j][k][l]);
                    }
                }
            }
        }
    }
