using namespace std;

int const kNumClasses = 4;

vector<uint64_t> g_classes[kNumClasses];
vector<uint64_t> g_prefixSums[kNumClasses];

int main() {
  int n;
  uint64_t capacity;

  uint64_t pivot = 0;
  cin >> n >> capacity;
  for (int i = 0; i < n; ++i) {
    uint64_t weight, value;
    cin >> weight >> value;
    if (i == 0)
      pivot = weight;

    assert(weight >= pivot);
    assert(weight < pivot + kNumClasses);
    g_classes[weight - pivot].push_back(value);
  }

  for (int i = 0; i < kNumClasses; ++i) {
    auto &klass = g_classes[i];
    sort(klass.rbegin(), klass.rend());

    auto &sums = g_prefixSums[i];
    sums.push_back(0);
    for (auto const &value : klass) {
      auto const sum = sums.back() + value;
      sums.push_back(sum);
    }
  }

  uint64_t best = 0;
  for (int a = 0; a <= g_classes[0].size(); ++a) {
    uint64_t const w1 = pivot * a;
    if (w1 > capacity)
      break;

    for (int b = 0; b <= g_classes[1].size(); ++b) {
      uint64_t const w2 = w1 + (pivot + 1) * b;
      if (w2 > capacity)
        break;

      for (int c = 0; c <= g_classes[2].size(); ++c) {
        uint64_t const w3 = w2 + (pivot + 2) * c;
        if (w3 > capacity)
          break;

        uint64_t d = (capacity - w3) / (pivot + 3);
        if (d > g_classes[3].size())
          d = g_classes[3].size();

        uint64_t const curr = g_prefixSums[0][a] + g_prefixSums[1][b] +
                              g_prefixSums[2][c] + g_prefixSums[3][d];
        if (curr > best)
          best = curr;
      }
    }
  }

  cout << best << endl;

  return 0;
}

