long long prefix[4][101];
void pre(){
	for(int val=0; val<4; val++)
		for(int i=1; i<=cnt[val]; i++)
			prefix[val][i]=prefix[val][i-1]+t[val][i];
}

long long get(int val, int k){
    return prefix[val][k];
}

int main(){
	scanf("%d %d", &n, &W);
	for(int i=1; i<=n; i++){
		scanf("%d %d", &w[i], &v[i]);
		int val=w[i]-w[1];
		t[val][++cnt[val]]=v[i];
	}
	for(int val=0; val<4; val++){
		sort(t[val]+1, t[val]+1+cnt[val]);
		reverse(t[val]+1, t[val]+1+cnt[val]);
	}
	pre();
	long long valmax=0;
	for(int i=0; i<=cnt[0]; i++){
		for(int j=0; j<=cnt[1]; j++){
			for(int k=0; k<=cnt[2]; k++){
				long long nowsum=0;
				nowsum += w[1]*1ll*i;
				nowsum += (w[1]+1)*1ll*j;
				nowsum += (w[1]+2)*1ll*k;
				if(nowsum > W) break;

				int s=1, e=cnt[3], ans=0;
				while(s<=e){
					int mid=(s+e)/2;
					if(nowsum + (w[1]+3)*1ll*mid <= W)
						ans=mid, s=mid+1;
					else e=mid-1;
				}

                long long valsum=0;
                valsum += get(0, i);
                valsum += get(1, j);
                valsum += get(2, k);
                valsum += get(3, ans);
                valmax = max(valmax, valsum);
			}
		}
	}
	printf("%lld", valmax);
	return 0;
}

