priority_queue<int> PQ[4];

long long val(int a,int b,int c,int d){
  int sum=0;
  for(int i=1;i<=a;i++){
    int tmp=PQ[0].top(); PQ[0].pop();
    sum=sum+tmp;
  }
  for(int i=1;i<=b;i++){
    int tmp=PQ[1].top(); PQ[1].pop();
    sum=sum+tmp;
  }
  for(int i=1;i<=c;i++){
    int tmp=PQ[2].top(); PQ[2].pop();
    sum=sum+tmp;
  }
  for(int i=1;i<=d;i++){
    int tmp=PQ[3].top(); PQ[3].pop();
    sum=sum+tmp;
  }
  return sum;
}

