  cnt[0]++;
  PQ[0].push(v_1);
  for(int i=2;i<=N;i++){
    int w,v; cin >> w >> v;
    PQ[w-w_1].push(v);
    cnt[w-w_1]++;
  }
  long long ans=0;
  for(int a=0;a<=cnt[0];a++){
    for(int b=0;b<=cnt[1];b++){
      for(int c=0;c<=cnt[2];c++){
        for(int d=0;d<=cnt[3];d++){
          if(a*w_1+b*(w_1+1)+c*(w_1+2)+d*(w_1+3)>W) continue;
          ans=max(ans,val(a,b,c,d));
        }
      }
    }
  }
  cout << ans << endl;
}

