        cin >> items[i].w >> items[i].v;
    }
    ll w_base = items[0].w;
    auto dp = make_vec_nd(numeric_limits<ll>::min(), 2, N+1, 3*N+1);
    dp[0][0][0] = 0;
    rep(n,1,N+1) {
        rep(m,0,n+1) {
            rep(w,0,300*N+1) {
                if (!(m * w_base + w <= W)) {
                    continue;
                }
                dp[n%2][m][w] = dp[(n-1)%2][m][w];
                ll w_off = items[n-1].w - items[0].w;
                if (m >= 1 && w >= w_off) {
                    dp[n%2][m][w] = max(dp[n%2][m][w], dp[(n-1)%2][m-1][w-w_off] + items[n-1].v);
                }
            }
        }
    }
    ll ans = numeric_limits<ll>::min();
    rep(m,0,N+1) {
        rep(w,0,3*N+1) {
            ans = max(ans, dp[N%2][m][w]);
        }
    }
    cout << ans << endl;
}

#include <iostream>
