struct wv {
    std::uint64_t w;
    std::uint64_t v;
};

inline bool operator<(wv const& lhs, wv const& rhs) {
    if (lhs.w < rhs.w) return true;
    if (rhs.w < lhs.w) return false;
    if (lhs.v < rhs.v) return true;
    return false;
}

auto memo = std::map<std::multiset<wv>, wv>();

std::uint64_t solve(std::multiset<wv> s, std::multiset<wv>& choose, std::uint64_t wmax) {
    std::uint64_t biggest = 0;
    std::vector<wv> vec;
    vec.reserve(s.size());
    std::copy(s.begin(), s.end(), std::back_inserter(vec));
    do {
        std::uint64_t wsum = 0;
        std::uint64_t vsum = 0;
        auto tmpvec = vec;
        while (!tmpvec.empty()) {
            tmpvec.pop_back();
            std::multiset<wv> tmpms;
            for (auto const& e : tmpvec) tmpms.insert(e);
            auto it = memo.find(tmpms);
            if (it == memo.end()) continue;
            wsum = it->second.w;
            vsum = it->second.v;
            break;
        }
        auto it = vec.begin();
        it += tmpvec.size();
        for (; it != vec.end(); ++it) {
            auto const& e = *it;
            wsum += e.w;
            if (wsum > wmax) break;
            vsum += e.v;
            choose.insert(e);
            memo.emplace(choose, wv{wsum, vsum});
        }
        biggest = std::max(vsum, biggest);
    } while (std::next_permutation(vec.begin(), vec.end()));
    return biggest;
}

int main() {
    std::uint64_t n, w;
    std::cin >> n >> w;
    std::multiset<wv> s, choose;
    for (std::uint64_t i = 0; i != n; ++i) {
        std::uint64_t w, v;
        std::cin >> w >> v;
        s.emplace(wv{w, v});
    }
    std::uint64_t result = solve(s, choose, w);
    std::cout << result << std::endl;
}

