ll calc(int d, ll wsofar, ll vsofar) {
	if (d == 4) {
		return wsofar <= W ? vsofar : 0;
	}
	ll ret = calc(d + 1, wsofar, vsofar);
	for (ll v : val[d]) {
		wsofar += w0 + d;
		vsofar += v;
		if (wsofar > W) break;
		ret = max(ret, calc(d + 1, wsofar, vsofar));
	}
	return ret;
}

