{
    ll val = W-(ll)n*w0;
    if(val < 0){
        return -1;
    }
    else if (val == 0){
        return 0;
    }
    ll maxi = 0;

    for(int i = 0; i < min(n+1, (int)w[0].size()+1); i++){
        const ll v1 = w_sum[0][i];
        for(int j = 0; j < min(n+1-i, (int)w[1].size()+1); j++){
            if(j > val){
                break;
            }
            const ll v2 = w_sum[1][j];
            for(int k = 0; k < min(n+1-i-j, (int)w[2].size()+1); k++){
                const int l = n - i - j - k;
                if(l <= (int)w[3].size()){
                    if(j + 2*k+3*l > val){
                        break;
                    }
                    const ll v3 = w_sum[2][k];
                    const ll v4 = w_sum[3][l];
                    chmax(maxi, v1+v2+v3+v4);               
                }
            }
        }
    }
    return maxi;
}

signed main()
{
    cin >> N >> W;
    rep(i, N){
        ll w_;
        cin >> w_ >> v[i];
        if(i == 0){
            w0 = w_;
            w[0].pb(v[i]);
        } else {
            w[w_-w0].pb(v[i]);
        }
    }
    rep(i, 4){
        if(not w[i].empty()){
            sort(w[i].begin(), w[i].end(), greater<ll>());            
        }
    }
    for(int i = 0 ; i < 4; i++){
        w_sum[i].resize(w[i].size()+1);
    }
    rep(i, 4){
        w_sum[i][0] = 0;
    }
    rep(i, 4){
        rep1(j, static_cast<int>(w[i].size())){
            w_sum[i][j] = w_sum[i][j-1]+w[i][j-1];
        }
    }
    int inf = 0;
    int sup = N;
    while(inf < sup){
        const int mid = (inf+sup)/2;
        ll val = ans(mid);
        if(val == -1){
            sup = mid;
        } else {
            if(mid+1 == sup){
                if(ans(sup) != -1){
                    inf = sup;
                }
                break;
            }
            inf = mid;
        }
    }
    cout << ans(inf) << endl;
    return 0;
}

