void depth_first(int n, int b[4]) {
	if (n == 4) {
		ll value_total = 0, weight_total = 0;
		for (int i = 0; i < 4; i++) {
			value_total += (sum_value[i][b[i]] - sum_value[i][0]);
			weight_total += (sum_weight[i][b[i]] - sum_weight[i][0]);
		}
		if (weight_total <= W)ans = max(ans, value_total);
		return;
	}
	int next_b[4];
	next_b[0] = b[0], next_b[1] = b[1], next_b[2] = b[2], next_b[3] = b[3];
	for (int i = 0; i <= value[n].size(); i++) {
		next_b[n] = i;
		depth_first(n + 1 ,next_b);
	}
}

