        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= 300; j++) {
                dp[k][i][j] = max(dp[k - 1][i - 1][j], dp[k][i - 1][j]);
                dp[k][i][j] = max(dp[k][i][j], dp[k - 1][i][j]);
                if (j - w[i - 1] >= 0) {
                    if (dp[k][i][j] < dp[k - 1][i - 1][j - w[i - 1]] + v[i - 1]) dp[k][i][j] = dp[k - 1][i - 1][j - w[i - 1]] + v[i - 1];
                }
            }
        }
    }
    int r = 0;
    for (int k = 1; k <= n; k++) {
        int64_t j = W - (int64_t)w0 * k;
        if (0 <= j && j <= 300) {
