typedef struct {
  int key1;
  int key2;
}table;

int comp(const void *a,const void *b){
  table *p1 = (table*)a;
  table *p2 = (table*)b;

  if(p1->key1 != p2->key1)
    return p1->key1 - p2->key1;
  else
    return p1->key2 - p2->key2;
}


int ans[401][101];
int kazu[401][101];

int greedy_knapsack(table *item,int n,int w ,int x){
  int i,j;

  for(i=0;i<=w;i++){
    for(j=0;j<=n;j++){
      if(i == 0 || j == 0){
        ans[i][j] = 0;
        kazu[i][j] = 0;
      }
      else if(item[j-1].key1 <= i){
        if(item[j-1].key2 + ans[i - item[j-1].key1][j-1]  >  ans[i][j-1] && kazu[i - item[j-1].key1][j-1] < x){
          ans[i][j] = item[j-1].key2 + ans[i - item[j-1].key1][j-1];
          kazu[i][j] = 1 + kazu[i - item[j-1].key1][j-1];
        }
        else if(item[j-1].key2 + ans[i - item[j-1].key1][j-1]  <  ans[i][j-1]){
          ans[i][j] = ans[i][j-1];
          kazu[i][j] = kazu[i][j-1];
        }
        else{
          ans[i][j] = ans[i][j-1];
          if( 1 + kazu[i - item[j-1].key1][j-1]  <  kazu[i][j-1])
            kazu[i][j] = 1 + kazu[i - item[j-1].key1][j-1];
          else
            kazu[i][j] = kazu[i][j-1];
        }
      }
      else{
        ans[i][j] = ans[i][j-1];
        kazu[i][j] = kazu[i][j-1];
      }
    }
  }
  return ans[w][n];
}


int main()
{
  int i,j,n,w;
  cin >> n >> w;
  table item[101] = {};

  int tmp1,tmp2;
  cin >> tmp1 >> tmp2;
  item[0].key1 = 1;
  item[0].key2 = tmp2;
  for(i=1;i<n;i++){
    int x;  cin >> x; x -= tmp1 - 1;  item[i].key1 = x;
    cin  >> item[i].key2;
  }

  qsort(item,n,sizeof(table),comp);

  int ans = 0;
  for(int i=0;i<=n;i++)
    ans = max(ans , greedy_knapsack(item,n,max(0,w-(tmp1 - 1)*i),i) );

  cout << ans << endl;

  return 0;
}

