LL judge;

int dfs(int now, LL rest, LL value)
{
    if(value >= judge) return 1;
    if(now > n) return 0;
    int flag1 = 0, flag2 = 0;
    flag1 = dfs(now + 1, rest, value);
    if(rest - w[now] >= 0) flag2 = dfs(now + 1, rest - w[now], value + v[now]);
    if(flag1 + flag2 > 0) return 1;
    return 0;
}

int C(LL x)
{
    judge = x;
    if(dfs(1, W, 0)) return 1;
    else return 0;
}

