            sum += v[i];
        }
        LL l = 0, r = sum, mid;
        while(l < r)
        {
            mid = (l + r) / 2;
            if(C(mid)) l = mid + 1;
            else r = mid;
        }
        mid = (l + r) / 2;
        if(!C(mid)) l--;
        printf("%lld\n", l);
    }
}

