LL dfs(vector<LL> &w, vector<vector<LL>> &vs, int iter, 
       LL W, PII cur) {
  if(iter==w.size()) {
    if(cur.first <= W) return cur.second;
    return 0;
  }
  LL ans = dfs(w, vs, iter+1, W, cur);
  LL sum = 0;
  for(int i=0; i<vs[iter].size(); i++) {
    PII next = cur;
    sum += vs[iter][i];
    next.first = cur.first + (i+1) * w[iter];
    next.second = cur.second + sum;
    chmax(ans, dfs(w, vs, iter+1, W, next));

  }
  return ans;


}


