long long n, w, refW, refV;

long long nr[4];
long long values[4][101];

int main() {
  cin >> n >> w;

  cin >> refW >> refV;

  values[0][1] = refV;
  nr[0]++;


  for (int obj = 2; obj <= n; ++obj) {
    long long weight, value;
    cin >> weight >> value;
    int poz = weight - refW;
    ++nr[poz];
    values[poz][nr[poz]] = value;
  }

  long long sumVal0, sumVal1, sumVal2, sumVal3;
  long long bestVal = 0;

  for (int type = 0; type <= 3; ++type) {
    sort(values[type] + 1, values[type] + nr[type] + 1, greater<long long>());
  }

  sumVal0 = sumVal1 = sumVal2 = sumVal3 = 0;

  for (int nr0 = 0; nr0 <= nr[0]; ++nr0) {
    sumVal0 += values[0][nr0];
    sumVal1 = sumVal2 = sumVal3 = 0;
    for (int nr1 = 0; nr1 <= nr[1]; ++nr1) {
      sumVal1 += values[1][nr1];
      sumVal2 = sumVal3 = 0;
      for (int nr2 = 0; nr2 <= nr[2]; ++nr2) {
        sumVal2 += values[2][nr2];
        sumVal3 = 0;
        for (int nr3 = 0; nr3 <= nr[3]; ++ nr3) {
          sumVal3 += values[3][nr3];
          long long sumW = 0;
          sumW = (nr0 + nr1 + nr2 + nr3) * refW + nr1 + nr2 * 2 + nr3 * 3;

          if (sumW > w) continue;

          if (sumVal0 + sumVal1 + sumVal2 + sumVal3 > bestVal)
            bestVal = sumVal0 + sumVal1 + sumVal2 + sumVal3;
        }
      }
    }
  }

  cout << bestVal;

}

