const int SIZE = 1 << 17;

char buffer[SIZE];
int pointer = SIZE;

char Advance() {
    if (pointer == SIZE) {
        fread(buffer, 1, SIZE, stdin);
        pointer = 0;
    }
    return buffer[pointer++];
}

int Read() {
    int answer = 0;
    char ch = Advance();
    while (!isdigit(ch))
        ch = Advance();
    while (isdigit(ch)) {
        answer = answer * 10 + ch - '0';
        ch = Advance();
    }
    return answer;
}

const int MAXN = 100;

int weight[1 + MAXN], value[1 + MAXN], delta[1 + MAXN];
int dp[1 + MAXN][1 + MAXN][1 + 3 * MAXN];

int main() {
    //freopen("tema.in", "r", stdin);
    //freopen("tema.out", "w", stdout);
    int n, limit, answer = 0;
    scanf("%d%d", &n, &limit);
    for (int i = 1; i <= n; i++) {
        scanf("%d%d", &weight[i], &value[i]);
        delta[i] = weight[i] - weight[1];
    }
    memset(dp, -1, sizeof(dp));
    for (int i = 0; i <= n; i++)
        dp[i][0][0] = 0;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            for (int k = 3 * n; k >= 0; k--) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (k >= delta[i] && dp[i - 1][j - 1][k - delta[i]] != -1)
                    dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j - 1][k - delta[i]] + value[i]);
            }
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            for (int k = 0; k <= 3 * n; k++)
                if (1LL * j * weight[1] + k <= limit)
                    answer = max(answer, dp[i][j][k]);
    printf("%d\n", answer);
    return 0;
}

