#define MAIN 110
using namespace std;
const long long INF=0x3fffffff;
int n;
LL c,w[MAIN],v[MAIN];
pair <LL,LL> pi[1<<(MAIN/2)];
int main()
{
    while(~scanf("%d%lld",&n,&c))
    {
        for(int i = 0; i < n; i++)
            scanf("%lld%lld",&w[i],&v[i]);
        int n2=n/2;
        FC(i,0,1<<n2)
        {
            int sw=0,sv=0;
            FC(j,0,n2)
            {
                if((i>>j)&1)
                {
                    sw+=w[j];
                    sv+=v[j];
                }
            }
            pi[i]=MK(sw,sv);
        }
        sort(pi,pi+(1<<n2));
        int m=1;
        FC(i,1,1<<n2)
        {
            if(pi[m-1].second<pi[i].second)
                pi[m++]=pi[i];
        }
        LL ans=0;
        FC(i,0,1<<(n-n2))
        {
            LL sw=0,sv=0;
            FC(j,0,n-n2)
            {
                if((i>>j)&1)
                {
                    sw+=w[n2+j];
                    sv+=v[n2+j];
                }
            }
            if(sw<=c)
            {
                LL tv=(lower_bound(pi,pi+m,MK(c-sw,INF))-1)->second;
                ans=max(ans,sv+tv);
            }
        }
        printf("%lld\n",ans);
    }
    return 0;
}

