// i 個目の品物を見ているときに基準からの重さの差が j で入れたものの数が k だった場合
// 価値を返す
ll search(ll i, ll j, ll k) {
    printf("i %lld j %lld k %lld\n", i, j, k);
    if(i >= N) { printf("return\n"); return 0; }
    ll ret = 0;
    if((j + obj[i].first) + (w1 * (k+1)) <= W) {
        printf("in k=%lld\n", k);
        ret = max(ret, search(i+1, j + obj[i].first, k+1) + obj[i].second);
