int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, W;
    cin >> N >> W;
    vector< multiset<int, greater<int> > > m(4);
    int w1;
    REP(i, N){
        int w, v;
        cin >> w >> v;
        if(i == 0) w1 = w;
        w -= w1;
        m[w].insert(v);
    }
    llint ans = -1;
    REP(i, N+1)REP(j, N+1-i)REP(k, N+1-i-j)REP(l, N+1-i-j-k){
        if(i*w1 + j*(w1+1) + k*(w1+2) + l*(w1+3) > W) continue;
