int N, W, w_1, v, w_i;

int findAns(int weight, long long int totWeight, int totVal){
	if(weight==4)
		return totVal;
	int ret = findAns(weight+1, totWeight, totVal);
	int i=0;
	while(i < val[weight].size() && totWeight + w_1 + weight <= W){
		totWeight += w_1 + weight;
		totVal += val[weight][i];
		ret = max(ret, findAns(weight+1, totWeight, totVal));
		++i;
	}
	return ret;
}

