using ll = long long;

const int MAXN = 105;
int N;
ll Wmax;
ll W[MAXN];
int V[MAXN];

int dp[MAXN][MAXN][3 * MAXN];

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	cin >> N >> Wmax;
	for (int i = 0; i < N; i++) {
		cin >> W[i] >> V[i];
	}

	dp[0][0][0] = 0;
	for (int i = 0; i < N; i++) {
		for (int n = 0; n <= i; n++) {
			for (int a = 0; a <= 3 * n; a++) {
				ll curW = n * W[0] + a;
				if (curW > Wmax) continue;
				setmax(dp[i+1][n][a], dp[i][n][a]);
				ll nxtW = (n+1) * W[0] + a + (W[i] - W[0]);
				if (nxtW <= Wmax) {
					setmax(dp[i+1][n+1][a + (W[i] - W[0])], dp[i][n][a] + V[i]);
				}
			}
		}
	}

	int ans = 0;
	for (int n = 0; n <= N; n++) {
		for (int a = 0; a <= 3 * n; a++) {
			setmax(ans, dp[N][n][a]);
		}
	}

	cout << ans << '\n';

	return 0;
}

