#define ll long long

void f(vector<ll> &v) {
  vector<ll> n;
  n.push_back(0);
  for(ll i = 0; i < v.size(); i++) {
    n.push_back(n.back() + v[v.size() - 1 - i]);
  }
  v.clear();
  for(ll i = 0; i < n.size(); i++) {
    v.push_back(n[i]);
  }

  return;
}

int main() {
  ll N, W;
  cin >> N >> W;
  vector<ll> w(N), v(N);
  for(ll i = 0; i < N; i++) {
    cin >> w[i] >> v[i];
  }

  ll ans = 0;

  vector<ll> v0, v1, v2, v3;
  for(ll i = 0; i < N; i++) {
    ll tmp = w[i] - w[0];
    if(tmp == 0) {
      v0.push_back(v[i]);
    }else if(tmp == 1) {
      v1.push_back(v[i]);
    }else if(tmp == 2) {
      v2.push_back(v[i]);
    }else {
      v3.push_back(v[i]);
    }
  }

  sort(v0.begin(), v0.end());
  sort(v1.begin(), v1.end());
  sort(v2.begin(), v2.end());
  sort(v3.begin(), v3.end());

  f(v0);
  f(v1);
  f(v2);
  f(v3);

  for(ll i0 = 0; i0 < v0.size(); i0++) {
    for(ll i1 = 0; i1 < v1.size(); i1++) {
      for(ll i2 = 0; i2 < v2.size(); i2++) {
        for(ll i3 = 0; i3 < v3.size(); i3++) {
          if(w[0] * i0 + (w[0] + 1) * i1 + (w[0] + 2) * i2 + (w[0] + 3) * i3 <= W) {
            ans = max(ans, v0[i0] + v1[i1] + v2[i2] + v3[i3]);
          }
        }
      }
    }
  }

  cout << ans << endl;



}

