ll knapsack(vpl &v, ll w){
	memset( dp,0,sizeof ( dp));
	dp[0][0]=1;
	dp[0][1]=0;

	for ( ll i=0;i<v.sz();i++){
		memset( dpi,0,sizeof ( dpi));
		for ( ll j=0;j<30000;j++)
		if ( dp[j][0]==1){
			dpi[j+v[i].fi][0]=1;
			dpi[j+v[i].fi][1]=max( dpi[j+v[i].fi][1],dp[j][1]+v[i].se);
			dpi[j][0]=1;
			dpi[j][1]=max( dpi[j][1],dp[j][1]);
		}
		swap( dp,dpi);
	}
	ll ma=0;
	for ( ll i=0;i<=w;i++)
		ma=max( dp[i][1],ma);
	return ma;
}
