ll memo[101][401][101];
ll solve(int i,int sum,int k)
{
    if(i == n)
        return 0;
    ll &ret = memo[i][sum][k];
    if(ret != -1)
        return ret;
    ll x1 = 0 , x2 = 0;
    x1 = solve(i+1,sum,k);
    if(k > 0 && a[i].fr <= sum)
    {
        x2 = a[i].sc + solve(i+1,sum-a[i].fr,k-1);
    }
    return ret = max(x1,x2);
}
