using namespace std;

typedef long long ll;

int main(){
    ll N, W;
    cin >> N >> W;
    ll W0;

    vector<ll> v(N);
    vector<ll> w(N);

    for(int i = 0; i < N; i++){
        cin >> w[i] >> v[i];
        if(i == 0){
            W0 = w[0];
            w[0] = 0;
        } else { 
            w[i] -= W0;
        }
    }

    ll dp[N][3*N+1][N+1];
    for(ll i = 0; i < N; i++){
        for(ll j = 0; j <= 3*N; j++){
            for(ll k = 0; k <= N; k++){
                dp[i][j][k] = 0;
            }
        }
    }
    //dp[i][j][k] : iまで、補正済み重さj、個数kで最大価値

    // v0を使う場合
    dp[0][0][1] = (W0 <= W ? v[0] : 0 ) ;

    for(ll i = 0; i < N; i++){
        for(ll j = 0; j <= 3*N; j++){
            for(ll k = 0; k <= N; k++){
                // i+1を使う
                if(i+1 < N && j + w[i+1] + W0 * (k+1) <= W && k+1 <= N) {
                    dp[i+1][j + w[i+1]][k+1] = max(dp[i+1][j + w[i+1]][k+1], dp[i][j][k] + v[i+1]);
                }
                // i+1を使わない 
                if(i+1 < N){
                    dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
                }
            }
        }
    }


    ll ans = 0;
    for(int j=0; j<=3*N; j++){
        for(int k=0; k<=N; k++){
            ans = max(ans, dp[N-1][j][k]);
        }
    }
    cout << ans << endl;

}

