ll calc(int cnt1, int cnt2, int cnt3, int cnt4){
    ll sum = 0;
    for (int i = w1.size()-1; i>=w1.size()-cnt1;i--){
        sum+=w1[i];
    }
    for (int i = w2.size()-1; i>=w2.size()-cnt2;i--){
        sum+=w2[i];
    }for (int i = w3.size()-1; i>=w3.size()-cnt3;i--){
        sum+=w3[i];
    }for (int i = w4.size()-1; i>=w4.size()-cnt4;i--){
        sum+=w4[i];
    }
    return sum;
}
