int Solve(const int idx, const int n, const int tw, const int w, const vector<P>& wv) {
  if (idx >= n) {
    return 0;
  }
  if (memo[idx][tw] != 0) {
    return 0;
  }
  int ret1 = 0, ret2 = 0;
  if (tw + wv[idx].first <= w) {
    ret1 = wv[idx].second + Solve(idx + 1, n, tw + wv[idx].first, w, wv);
  }
  ret2 = Solve(idx + 1, n, tw, w, wv);

  return memo[idx][tw] = max(ret1, ret2);
}

