int knapsack (int W, int *w, int *v, int N) {
    int K[N+1][W+1];

    for (int i = 0; i <= N; i++)
    for (int j = 0; j <= W; j++){
        if      (i == 0 || j == 0) K[i][j] = 0;
        else if (w[i-1] <= j)      K[i][j] = max(v[i-1] + K[i-1][j-w[i-1]], K[i-1][j]);
        else                       K[i][j] = K[i-1][j];
    }

    return K[N][W];
}

