    if(WV[3].size() != 0)d = rand() % (WV[3].size() + 1);
    if(A * a + b * (max(a - 1,0LL)) + c * (max(a - 2,0LL)) + d * (max(a - 3,0LL)) <= w){
      vector<priority_queue<ll>>WWV;
      WWV = WV;
