void solve(){
    // mainalgorithm
    dp[1][1][0] = V[0];
    dp[1][0][0] = 0;
    for (int i = 1; i < N; ++i)
    {
        for (int j = 0; j <= N; ++j)
        {
            for (int k = 0; k < N * 3; ++k)
            {
                if(dp[i][j][k] == -1LL) continue;
                if(W_0 * (j+1) + (k + W[i]) <= M)
                    dp[i+1][j+1][k+W[i]] = max(dp[i+1][j+1][k+W[i]],
                                               dp[i][j][k] + V[i]);
                dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
            }
        }
    }
}
