int solve(int groupNum, int weight, int curWeight, int curVal, int a)
{
    if (groupNum == 3)
    {
        for (int i = 0; i < min((int) groups[groupNum].size(), (weight - curWeight) / (a + 3)); i++)
        {
            curVal += groups[groupNum][i];
        }
        return curVal;
    }
    else
    {
        int ans = solve(groupNum + 1, weight, curWeight, curVal, a);
        for (int i = 0; i < (int) groups[groupNum].size(); i++)
        {
            curWeight += a + groupNum;
            curVal += groups[groupNum][i];
            if (curWeight > weight)
                break;
            ans = max(ans, solve(groupNum + 1, weight, curWeight, curVal, a));
        }
        return ans;
    }
}

