					dp[i][j] = dp[i - 1][j];
					dp_n[i][j] = dp_n[i - 1][j];
				}
			}
		}
		for (i = 1; i < N + 1; i++){
			for (j = 1; j < mW + 1; j++){
				if (dp_n[i][j] <= num){
					cand = max(cand, dp[i][j]);
				}
			}
		}
		cout << cand << endl;
		return 0;
	}
}

