class UnionFind {
    public:
    //各頂点の親の番号を格納する。その頂点自身が親だった場合は-(その集合のサイズ)を入れる。
    vector<int> Parent;

    //クラスを作るときは、Parentの値を全て-1にする。
    //以下のようにすると全てバラバラの頂点として解釈できる。
    UnionFind(int N) {
        Parent = vector<int>(N, -1);
    }

    //Aがどのグループに属しているか調べる
    int root(int A) {
        if (Parent[A] < 0) return A;
        return Parent[A] = root(Parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    int size(int A) {
        return -Parent[root(A)];//先祖をrootで取っておきたい。
    }

    //AとBをくっ付ける
    bool connect(int A, int B) {
        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        if (A == B) {
            //すでにくっついてるからくっ付けない
            return false;
        }

        //大きい方(A)に小さいほう(B)をくっ付けたい
        //大小が逆だったらAとBをひっくり返す。
        if (size(A) < size(B)) swap(A, B);

        //Aのサイズを更新する
        Parent[A] += Parent[B];
        //Bの親をAに変更する
        Parent[B] = A;

        return true;
    }
};

int main(){
  int n;
  long long W;
  cin>>n>>W;
  vector<vector<long long>> values(4);
  long long w,v;
  long long w1;
  REP(i,n){
    cin>>w>>v;
    if(i==0){
      w1 = w;
      values[0].push_back(v);
    }else{
      values[w-w1].push_back(v);
    }
  }
  REP(i,4){
    sort(values[i].begin(),values[i].end(),greater<long long>());
    REP(j,n){
      if(j==0){
        continue;
      }else{
        values[i][j]=values[i][j]+values[i][j-1];
      }
    }
  }
  long long ans=0;
  long long temp=0;
  int l;
  REP(i,n+1){
    REP(j,n+1){
      REP(k,n+1){
        if(i+j+k>n){
          continue;
        }
        l = n-(i+j+k);
        if(w1*i + (w1+1)*j + (w1+2)*k + (w1+3)*l > W){
          continue;
        }
        if(i!=0){
          temp += values[0][i-1];
        }
        if(j!=0){
          temp += values[1][j-1];
        }
        if(k!=0){
          temp += values[2][k-1];
        }
        if(l!=0){
          temp += values[3][l-1];
        }
        ans = max(ans,temp);
        temp = 0;
      }
    }
  }
  cout<<ans<<endl;
  return 0;
}

