LL N2, ans;

int main()
{
	in >> N >> W;
	rep(i, N) { in >> w[i] >> v[i]; }

	N2 = N / 2;
	rep(i, (1 << N2))
	{
		LL sum_w = 0, sum_v = 0;
		rep(j, N2)
		{
			if (i >> j & 1) { sum_w += w[j], sum_v += v[j]; }
		}
		res[i] = std::make_pair(sum_w, sum_v);
	}
	std::sort(res, res + (1 << N2));
	LL seek = 1;
	for (LL i = 1; i < (1 << N2); ++i)
	{
		if (res[seek - 1].second < res[i].second) { res[seek++] = res[i]; }
	}
	rep(i, (1 << (N - N2)))
	{
