void solve() {
	int N, W; cin >> N >> W;
	unordered_map<int, vector<int>> wv;
	REP(i, N) {
		int w, v; cin >> w >> v;
		wv[w].push_back(v);
	}

	unordered_map<int, int> wCnt;
	for (auto &a : wv) {
		sort(ALL(a.second));
		wCnt[a.first] = a.second.size();
	}

	vector<int> v;
	v.reserve(N);
	for (auto &a : wCnt) {
		REP(i, a.second) {
			v.push_back(a.first);
		}
	}

	int res = 0;
	do {
		unordered_map<int, vector<int>::iterator> its;
		for (auto &a : wCnt) {
			its[a.first] = wv[a.first].begin();
		}
		int val = 0;
		int w = 0;
		for (auto &a : v) {
			w += a;
			if (w > W) {
				break;
			}
			val += *its[a];
			its[a]++;
		}
		res = max(res, val);
	} while (next_permutation(ALL(v)));
	cout << res << endl;
}

