int SimpleKnapSack(long long w[], int val[], int W, int n)
{
    if (!W || !n)
        return 0;

    if (w[n - 1] > W)
        return SimpleKnapSack(w, val, W, n - 1);

    else
        return (max(val[n - 1] + SimpleKnapSack(w, val, W - w[n - 1], n - 1), SimpleKnapSack(w, val, W, n - 1)));
}

int KnapSackDP(long long w[], int val[], int W, int n)
{
    int K[n + 1][W + 1];

    K[0][0] = 0;
    for (int i = 1; i <= n; i++)
    {
        for (int j = 1; j <= W; j++)
        {
            if (w[i] <= W)
                K[i][j] = max(val[n - 1] + KnapSackDP(w, val, W - w[n - 1], n - 1), KnapSackDP(w, val, W, n - 1));
            else
                 K[i][j] = K[i - 1][j];
        }
    }
}

