using namespace std;
typedef long long LL;
LL wt[101],val[101],W;
int n;
LL knapSack()
{
    LL i, w;
    LL K[n + 1][W + 1];

    for (i = 0; i <= n; i++)
    {
        for (w = 0; w <= W; w++)
        {
            if (i == 0 || w == 0)
                K[i][w] = 0;
            else if (wt[i - 1] <= w)
                K[i][w]= max(val[i - 1] + K[i - 1][w - wt[i - 1]], K[i - 1][w]);
            else
                K[i][w] = K[i - 1][w];
        }
    }

    return K[n][W];
}

int main()
{
    scanf("%d %I64d",&n,&W);
    for(int i=0;i<n;i++){
        scanf("%I64d %I64d",&wt[i],&val[i]);
    }
    printf("%I64d",knapSack());
    return 0;
}

