      ll w = (i + j + k + l) * base_w + j + 2 * k + 3 * l;
      unless(w <= W) continue;

      ll v = 0;

      rep(m, i) v += values[0][m];
      rep(m, j) v += values[1][m];
      rep(m, k) v += values[2][m];
      rep(m, l) v += values[3][m];

      chmax(res, v);
    }
  }

  cout << res << endl;
}

