int rec(int i, int j, int k) {
    if (dp[i][j][k] >= 0) return dp[i][j][k];
    int res;
    if (i == N) {
        res = 0;
    } else if (j < w[i] - w[0]) {
        res = rec(i + 1, j, k);
    } else {
        res = max(rec(i + 1, j, k), rec(i + 1, j - w[i] + w[0], k - 1) + v[i]);
    }
    return res;
}

