#define	MOD 1000000007

struct	ITEM {
	long	wei;
	long	val;
};

long	knap(vector<ITEM> &p, long ix, long K, vector<vector<long>> &V) {
	if (V.at(K).at(ix) >= 0) return V.at(K).at(ix); // Check memo if done for this
	//cout << K << ":" << ix << endl;
	long R=0;
	if (ix == p.size()) R=0;	// No more item to add
	else if (K == 0) R=0;		// No more spaece in knapsack
		// If space avalable, try both and pick up better one
	else if (K >= p.at(ix).wei) R=max(p.at(ix).val + knap(p, ix+1, K-p.at(ix).wei, V), knap(p, ix+1, K, V) );
		// No space to put this, but may be more
	else R=knap(p, ix+1, K, V);
	V.at(K).at(ix)=R;	// Let's take note for this
	return R;
};

