LL N, W;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N >> W;
	VL w(N), v(N);

	VVL s(4);
	LL baseW;
	FOR(i, 0, N) {
		cin >> w[i] >> v[i];
		if (i == 0)baseW = w[i];
		int id = w[i] - baseW;
		s[id].push_back(v[i]);
	}
	FOR(i, 0, 4)SORT(s[i]);


	FOR(i, 0, SZ(s[0])+1) {
		FOR(j, 0, SZ(s[1])+1) {
			FOR(k, 0, SZ(s[2])+1) {
				FOR(l, 0, SZ(s[3])+1) {

					LL Vs = 0;
					LL Ws = 0;
					FOR(a, 0, i) {
						Ws += baseW;
						Vs += s[0][a];
					}FOR(a, 0, j) {
						Ws += baseW+1;
						Vs += s[1][a];
					}FOR(a, 0, k) {
						Ws += baseW+2;
						Vs += s[2][a];
					}FOR(a, 0, l) {
						Ws += baseW+3;
						Vs += s[3][a];
					}
					if (W >= Ws) {
						ans = max(ans, Vs);
					}

				}
			}
		}
	}
	cout << ans << "\n";

	return 0;
}

