    ll i,j;
    ll k[n+1][W+1];
    for(ll i=0;i<=n;i++)
    {
        for(ll w=0;w<=W;w++)
        {
            if(i==0 ||w==0)
               k[i][w]=0;
            else if(wt[i-1]<=w)
               k[i][w]=max(val[i-1]+k[i-1][w-wt[i-1]],k[i-1][w]);
            else k[i][w]=k[i-1][w];
        }

    }
