long long int din(int a, int weight, int surplus) {
	if (mem[a][weight][surplus] != 0) return mem[a][weight][surplus];
	if (surplus > w0) {
		weight+=floor(surplus/w0);
		surplus = surplus%w0;
	}
	if (weight >= maxw) {
		if (surplus > maxsur) {
			return -9999;
		}
	}
	if (a >= n) return 0;
	int res;
	res = max(din(a+1,weight,surplus),v[a]+din(a+1,weight+1,surplus+w[a]));
	mem[a][weight][surplus] = res;
	return res;
}
