ll memo(int pos, int cnt, int remain){
  if (base_weight *(ll)cnt + remain > W){
    return -INF;
  }
  if (pos >= N){
    return 0;
  }
  ll &res = dp[pos][cnt][remain];
  if (res >= 0){
