  res = -INF;
  ll point = items[pos].first - base_weight;
  ll value = items[pos].second;
  res = max(res, memo(pos + 1, cnt, remain));
  res = max(res, memo(pos + 1, cnt + 1, remain + point) + value);
  return res;
}

