// dp[i+1][k][w]
// i番目までみたとき、k個入れて、重さの和がwのときの、価値の最大値
// dp[N]に最終結果がある
int dp[N_MAX+1][N_MAX+1][3*N_MAX+1] = {{{0}}};


int main(int argc, char** argv) {
  int N;
  ll W;
  cin >> N >> W;

  vll ws(N);
  vi vs(N);

  REP(i, N) {
    cin >> ws[i] >> vs[i];
  }

  ll w0 = ws[0];
  REP(i, N) {
    ws[i] -= w0;
  }

  REP(i, N) {
    REP(k, i+1) {
      REP(j, 3*k+1) {
        // 入れない場合
        chmax(dp[i+1][k][j], dp[i][k][j]);
        // 入れる場合
	if ((w0*(k+1)+j+ws[i])<=W) {
          chmax(dp[i+1][k+1][j+ws[i]], dp[i][k][j]+vs[i]);
	}
      }
    }
  }

  int ret = 0;
  REP(k, N+1) {
    REP(j, 3*k+1) {
      chmax(ret, dp[N][k][j]);
    }
  }

  cout << ret << endl;

  return 0;
}

