	{
		s[i] = item[i].size();
		f[i][0] = 0;
		int tmp = item[i].size();
		if (!item[i].empty()) f[i][1] = item[i].top(), item[i].pop();
		for (int j=2;j<=tmp;j++)
		{
			f[i][j] = f[i][j-1] + item[i].top();
			item[i].pop();
		}
	}

	int ans = 0;
	for (int i=0;i<=s[0];i++)
	{
		for (int j=0;j<=s[1];j++)
		{
			for (int k=0;k<=s[2];k++)
