int N,W;
int Wbase;
int itemV[101];
int itemW[101];
int dpV[101][121][303];

int calc(int depth,int space, int cap) {
	int& V = dpV[depth][space][cap];
	int result = 0;
	if (V != -1)return V;
	else if (depth == N - 1) {
		if (space) {
			if (cap >= itemW[depth]) {
				return V = itemV[depth];
			}
			else if (space >= 2) {
				return V = calc(depth, space - 1, min(cap + Wbase, 300));
			}
		}
		else {
			return (V=0);
		}
	}
	else {
		if (space) {
			if (cap >= itemW[depth]) {
				result = itemV[depth] + calc(depth + 1, space - 1, cap - itemW[depth]);
			}
			else  if (space >= 2) {
				result = calc(depth, space - 1, min(cap + Wbase, 300));
			}
		}
		else result = 0;
		return V = max(calc(depth + 1, space, cap), result);
	}
}
