    dp[0][1][0] = v[0];
    for(int i = 1; i < N; i++){
        for(int j = 0; j <= N; j++){
            for(int k = 0; k <= 3 * N; k++){
                dp[i][j][k] = dp[i - 1][j][k];
                if(j > 0 && k - adjusted_w[i] >= 0 && dp[i - 1][j - 1][k - adjusted_w[i]] >= 0){
                    dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j - 1][k - adjusted_w[i]] + v[i]);
                }
            }
        }
    }
    /*
    for(int i = 0; i < N; i++){
        for(int j = 0; j <= N; j++){
            cout << j << ": ";
            for(int k = 0; k <= 3 * N; k++){
                cout << dp[i][j][k] << " ";
            }
        }
        cout << endl;
    }
    */
    long long ans = 0;
    for(int i = 1; i <= N; i++){
        for(int j = 0; j <= W - (w[0] * i); j++){
            if(j  <= 3 * N){
                ans = max(ans, dp[N - 1][i][j]);
                //cout << i << ", " << j << ": " << dp[N - 1][i][j] << endl;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

