        break;
      }
      ans = max(ans, i == 0 ? 0 : mp[ws[0]][i - 1]);
    }
  } else if (ws.size() == 2) {
    for (int i = 0; i <= mp[ws[0]].size(); i++) {
      for (int j = 0; j <= mp[ws[1]].size(); j++) {
        if (i * ws[0] + j * ws[1] > W) {
          break;
        }
        ans = max(ans,
          (i == 0 ? 0 : mp[ws[0]][i - 1])
          + (j == 0 ? 0 : mp[ws[1]][j - 1])
        );
      }
    }
