          ans = max(ans,
            (i == 0 ? 0 : mp[ws[0]][i - 1])
            + (j == 0 ? 0 : mp[ws[1]][j - 1])
            + (k == 0 ? 0 : mp[ws[2]][k - 1])
          );
        }
      }
