const int MAX_N = 100;

int main()
{
    int N, W;
    static int w[MAX_N], v[MAX_N];
    vector<int> a, b, c, d;

    cin >> N >> W;
    rep(i, N) {
        cin >> w[i] >> v[i];
    }


    rep(i, N) {
        if (w[i] == w[0]) a.push_back(v[i]);
        else if (w[i] == w[0] + 1) b.push_back(v[i]);
        else if (w[i] == w[0] + 2) c.push_back(v[i]);
        else d.push_back(v[i]);
    }

    int asize = (int)a.size(), bsize = (int)b.size(), csize = (int)c.size(), dsize = (int)d.size();
    sort(all(a)); sort(all(b)); sort(all(c)); sort(all(d));
    int sumw = 0, sumv = 0, ans = 0;


    rep(i, asize+1) {
        if (i) {
            sumw += w[0];
            sumv += a[asize-i];
        }
        rep(j, bsize+1) {
            if (j) {
                sumw += w[0]+1;
                sumv += b[bsize-j];
            }
            rep(k, csize+1) {
                if (k) {
                    sumw += w[0]+2;
                    sumv += c[csize-k];
                }
                rep(l, dsize+1) {
                    if (l) {
                        sumw += w[0]+3;
                        sumv += d[dsize-l];
                    }
                    if (sumw <= W) {
                        ans = max(ans, sumv);
                        cout << ans << endl;
                    }
                    if (l == dsize) {
                        sumw -= l*(w[0]+3);
                        rep(l2, dsize) {
                            sumv -= d[l2];
                        }
                    }
                }
                if (k == csize) {
                    sumw -= k*(w[0]+2);
                    rep(k2, csize) {
                        sumv -= c[k2];
                    }
                }
            }
            if (j == bsize) {
                sumw -= j*(w[0]+1);
                rep(j2, bsize) {
                    sumv -= b[j2];
                }
            }
        }
    }

    cout << ans << endl;
    return 0;
}

