typedef long long ll;
map <pair<ll, ll>, ll> dp;


ll solve(ll n, ll w, vector<ll> &wei, vector<ll> &val)
{
    if(w < 0)
        return (-1e10);
    if(n < 0)
        return 0;    

    if(dp.find({n, w}) != dp.end())
        return dp[{n, w}];    

    if(n)
        dp[{n, w}] = solve(n - 1, w, wei, val);    
    else
        dp[{n, w}] = 0;   

    if(w >= wei[n])
        dp[{n, w}] = max(dp[{n, w}], val[n] + solve(n - 1, w - wei[n], wei, val));

    return  dp[{n, w}];   
}

