		rem=min(rem,(ll)SZ(a[3]));
		ll cur=pre[0][i]+pre[1][j]+pre[2][k]+pre[3][rem];
		ans=max(ans,cur);
	}
	cout<<ans<<'\n';
	return 0;
}

