                        remax (dp[i+1][j + 1][extra + w[i+1] - w[1]], dp[i][j][extra] + v[i + 1]);
                        remax (sol, dp[i+1][j + 1][extra + w[i+1] - w[1]]);
                    } 
                }
                remax (dp[i+1][j][extra], dp[i][j][extra]);
            }
        }
    }

    cout << sol << "\n";

    return 0;
}

