int main(){
	scanf("%d%d", &n, &w);

	int x,y;
	scanf("%d%d", &x, &y);

	w0 = x;

	v[0].push_back(y);

	for(i = 0; i < n - 1; i++){
		scanf("%d%d", &x, &y);
		v[x - w0].push_back(y);
	}

	for(i = 0; i < 4; i++){
		sort(v[i].begin(), v[i].end());
		reverse(v[i].begin(), v[i].end());
	}

	long long res = 0;

	long long sum0 = 0;

	for(i = 0; i <= v[0].size(); i++){
		long long sum1 = 0;
		for(j = 0; j <= v[1].size(); j++){
			long long sum2 = 0;
			int p = v[3].size() - 1;
			long long sum3 = 0;

			for(k = 0; k < v[3].size(); k++)
			sum3 += v[3][k];

			for(k = 0; k <= v[2].size(); k++){
				long long tot = (long long)i * w0 + (long long)j * (w0 + 1) + (long long)k * (w0 + 2);

				if(tot > w) break;

				long long remain = (w - tot) / (w0 + 3);

				while(p + 1 > remain){
					sum3 -= v[3][p];
					p--; 
				}

				res = max(res, sum0 + sum1 + sum2 + sum3);

				if(k != v[2].size())
				sum2 += v[2][k];
			}
			if(j != v[1].size())
			sum1 += v[1][j];
		}
		if(i != v[0].size())
		sum0 += v[0][i];
	}

	printf("%lld\n", res);
}

