#include <bits/stdc++.h>
using namespace std;

long long n, w;

int values[110], weights[110];

int sDP[101][301][101];

int saved;

int dp(short index, int weight, int cnt) {
	int &ret = sDP[index][weight][cnt];
	if (ret != -1) return ret;

	if (index == n-1) {
		weight += weights[index];
		cnt++;
		if (weight + cnt*saved > w) {
			return ret = 0;
		} else {
			return ret = values[index];
		}
	}

	ret = dp(index+1, weight, cnt);
	if (weight + weights[index] + (cnt+1)*saved <= w) {
		ret = max(ret, dp(index+1, weight + weights[index], cnt+1) + values[index]);
	}

	return ret;
}

int main() {
	memset(sDP, -1, sizeof(sDP));

	cin >> n >> w;
	cin >> weights[0] >> values[0];
	saved = weights[0];
	weights[0] = 0;
	for (int i = 1; i < n; i++) {
		cin >> weights[i] >> values[i];
		weights[i] -= saved;
	}
	cout << dp(0, 0, 0);
}

