using namespace std;
typedef long long ll;
template <typename T>
using V = vector<T>;
using VL = V<ll>;
using VVL = V<VL>;
template <typename T, typename U>
using P = pair<T, U>;
using PL = P<ll, ll>;
using VPL = V<PL>;
template <typename T>
inline bool chmax(T& a, T b);
template <typename T>
inline bool chmin(T& a, T b);
void print_ints(vector<ll> v);
template <typename T>
void drop(T a);

const ll INF = 1e18;

void solve() {
  ll N, W;
  cin >> N >> W;

  struct Item {
    ll w;
    ll v;
  };

  V<Item> is(N);

  rep(i, N) {
    ll w, v;
    cin >> w >> v;
    is[i] = {w, v};
  }

  ll w_diff = 3;
  ll max_w = w_diff * (N - 1);

  // dp[i][w][ct]: i >= 1 番目のアイテムまでで重さ w
  // 以下での価値の最大値. ct 個選んだ場合。 w は先頭の要素の重さとの差
  V<VVL> dp(N + 1, VVL(max_w + 1, VL(N + 1)));

  ll w_base = is[0].w;

  rep(i, N) rep(w, max_w + 1) rep(ct, N) {
    auto item = is[i];

    chmax(dp[i + 1][w][ct], dp[i][w][ct]);

    if (w + item.w - w_base <= max_w) {
      chmax(dp[i + 1][w + item.w - w_base][ct + 1], dp[i][w][ct] + item.v);
    }
  }

  ll res = 0;

  rep(ct, N + 1) {
    ll w = w_base * ct;
    if (w > W) continue;
    ll rest_w = W - w;

    chmax(res, dp[N][min(rest_w, max_w)][ct]);
  }

  cout << res << endl;
}

