void solve() {
    i64 N; RD(N);
    i64 WMAX; RD(WMAX);

    vector<vector<i64>> vs(4);
    i64 w_base; RD(w_base);
    {
        i64 v; RD(v);
        vs[0].emplace_back(v);
    }
    FOR(_, 1, N) {
        i64 w,v; RD(w); RD(v);
        vs[w-w_base].emplace_back(v);
    }
    for(auto& e : vs) {
        ALL(sort, e, greater<>());
    }

    vector<vector<i64>> ss(4);
    REP(i, 4) {
        ss[i] = vector<i64>(SIZE(vs[i])+1, 0);
        ALL(partial_sum, vs[i], begin(ss[i])+1);
    }

    i64 ans = 0;
    auto rec = FIX([WMAX,w_base,&ss,&ans](auto self, i64 i, i64 w, i64 v) -> void {
        if(i == 4) {
            chmax(ans, v);
            return;
        }

        REP(k, SIZE(ss[i])) {
            i64 w_cur = (w_base+i) * k;
            if(w+w_cur > WMAX) continue;
            i64 v_cur = ss[i][k];
            self(i+1, w+w_cur, v+v_cur);
        }
    });
    rec(0, 0, 0);

    // * 小さいケースで試した?
    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

signed main() {


    solve();

    EXIT();
}

