      for (int c=0; c<=A[2].size(); c++) {
        for (int d=0; d<=A[3].size(); d++) {
          int w = base*a + (base+1)*b + (base+2)*c + (base+3)*d;
          if (w > W) continue;
          int v = 0;
          if (a > 0) v += A[0][a-1];
          if (b > 0) v += A[1][b-1];
          if (c > 0) v += A[2][c-1];
          if (d > 0) v += A[3][d-1];
          s = max(s, v);
        }
      }
    }
  }
  cout << s << "\n";
  return 0;
}

