LL rec(int i, int j, int k) //i番目の品物以降で重さj以下かつ個数k以下となるよう選んだときの最適解
{
    dump(i)
    dump(j)
    dump(k)
    LL res;
    if(dp[i][j][k] != -1) return dp[i][j][k];
    if(k == 0) return dp[i][j][k] = 0;

    if(i == N){
        return dp[i][j][k] = 0;
    }
    else if(j < w[i]){
        res = rec(i+1,j,k);
        return dp[i][j][k] = res;
    }
    else{
        //LL tmpa = rec(i+1,j,k);
        //LL tmpb = rec(i+1,j-w[i],k-1)+v[i];
        //if(tmpa > tmpb)
        //{
        //    return dp[i][j][k] = tmpa;
        //}
        //else
        //{
        //    return dp[i][j][k] = tmpb;
        //}
        res = max(rec(i+1,j,k), rec(i+1,j-w[i],k-1)+v[i]);
        return dp[i][j][k] = res;
    }
}

