int val[10];
vector<int> v[10];

main()
{
    int n,w;
    scanf("%d %d",&n,&w);
    for(int i=0;i<n;i++)
    {
        int a,b;
        scanf("%d %d",&a,&b);
        for(int j=0;j<10;j++)
        {
            if(a==val[j])
            {
                v[j].PB(b);
                break;
            }
            else if(val[j]==0)
            {
                val[j]=a;
                v[j].PB(b);
                break;
            }
        }
    }
    for(int i=0;i<10;i++)
    {
        if(val[i]!=0)
        {
            sort(v[i].begin(),v[i].end());
            v[i].PB(0);
        }
    }
    int ans=0;
    int cal1=0,cal2=0,cal3=0,cal4=0;
    for(int i=v[0].size()-1;i>=0;i--)
    {
        long long use1=v[0].size()-i-1;
        long long limit1=w-use1*val[0];
        if(limit1<0)
            break;
            //printf("1:%d limit=%d\n",v[0][i],limit1);
        cal1+=v[0][i];
        ans=max(ans,cal1);
        if(limit1==0)
            break;

        for(int j=v[1].size()-1;j>=0;j--)
        {
            long long use2=v[1].size()-j-1;
            long long limit2=limit1-use2*val[1];
            if(limit2<0)
                break;
            //printf("    2:%d limit=%d\n",v[1][j],limit2);
            cal2+=v[1][j];
            ans=max(ans,cal1+cal2);
            if(limit2==0)
                break;

            for(int k=v[2].size()-1;k>=0;k--)
            {
                long long use3=v[2].size()-k-1;
                long long limit3=limit2-use3*val[2];
                if(limit3<0)
                    break;
                //printf("        3:%d limit=%d\n",v[2][k],limit3);
                cal3+=v[2][k];
                ans=max(ans,cal1+cal2+cal3);
                if(limit3==0)
                    break;

                for(int l=v[3].size()-1;l>=0;l--)
                {
                    long long use4=v[3].size()-l-1;
                    long long limit4=limit3-use4*val[3];
                    if(limit4<0)
                        break;
                    //printf("            4:%d limit=%d\n",v[3][l],limit4);
                    cal4+=v[3][l];
                    ans=max(ans,cal1+cal2+cal3+cal4);
                }
                cal4=0;
            }
            cal3=0;
        }
        cal2=0;
    }
    printf("%d\n",ans);
}

