using namespace std; 
typedef long long ll;

int n;
ll W, w[110], v[110];
vector<ll> V[4];

int main(void) {
  cin >> n >> W;
  for (int i = 0; i < n; i++) {
    cin >> w[i] >> v[i];
    V[w[i] - w[0]].push_back(v[i]);
  }

  for (int i = 0; i < 4; i++) {
    sort(V[i].begin(), V[i].end(), greater<ll>());
    for (int j = 1; j < V[i].size(); j++) {
      V[i][j] += V[i][j - 1];
    }
  }

  ll ans = 0;
  for (int i = 0; i <= V[0].size(); i++) {
    for (int j = 0; j <= V[1].size(); j++) {
      for (int k = 0; k <= V[2].size(); k++) {
        ll rem = W - w[0] * i - (w[0] + 1) * j - (w[0] + 2) * k;
        if (rem < 0) continue;
        ll l = rem / (w[0] + 3);
        ll sum = 0;
        if (i) sum += V[0][i - 1];
        if (j) sum += V[1][j - 1];
        if (k) sum += V[2][k - 1];
        if (l && l < V[3].size()) sum += V[3][l - 1];
        ans = max(ans, sum);
      }
    }
  }
  cout << ans << endl;

  return 0;
}

