    int pivot = w[0];
    for(int i = 0; i < n; i++) w[i] -= pivot;

    ll dp[n+1][n+1][1005];
    memset(dp, -1, sizeof dp);

    dp[0][0][0] = 0;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            for(int k = 0; k < 1e3; k++) {
                if(dp[i][j][k] == -1) continue;

                dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
                dp[i+1][j+1][k+w[i]] = max(dp[i+1][j+1][k+w[i]], dp[i][j][k] + v[i]); 
            }
        }
    }

    ll ans = 0;
    for(int i = 0; i <= n; i++) {
        for(int j = 0; j <= n; j++) {
            for(int k = 0; k < 1e3; k++) {
                ll lim = W - 1LL*j*pivot;

                if(k <= lim) ans = max(ans, dp[i][j][k]);
            }
        }
    }

    cout << ans << endl;

    return 0;
}

