						if (w + ws[0] <= maxW) {
							dp[i0 + 1][i1][i2][i3] = max(dp[i0 + 1][i1][i2][i3], dp[i0][i1][i2][i3] + vss[0][i0]);
						}

						if (w + ws[0] + 1 <= maxW) {
							dp[i0][i1 + 1][i2][i3] = max(dp[i0][i1 + 1][i2][i3], dp[i0][i1][i2][i3] + vss[1][i1]);
