int main () {
	ll a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q;
	scanf("%lld %lld", &a, &b);
	for (i = 1; i <= a; i++) {
		scanf("%lld %lld", &c, &d);
		item[i] = {c, -d};
	}
	sort(item + 1, item + a + 1);
	e = item[1].fi;
	for (i = 0; i <= 3; i++) clas[i].pb(0);
	for (i = 1; i <= a; i++) clas[item[i].fi - e].pb(-item[i].se);
	SET(dp, 0); n = 0;
	f = 0;
	for (i = 0; i < clas[0].size(); i++) {
		if (f > b) break;
		g = 0;
		for (j = 0; j < clas[1].size(); j++) {
			if (f + g > b) break;
			h = 0;
			for (k = 0; k < clas[2].size(); k++) {
				if (f + g + h > b) break;
				m = 0;
				for (l = 0; l < clas[3].size(); l++) {
					if (f + g + h + m > b) break;
					if (i > 0) {
						dp[i & 1][j][k][l] = max(dp[i & 1][j][k][l], dp[!(i & 1)][j][k][l] + clas[0][i]);
					}
					if (j > 0) {
						dp[i & 1][j][k][l] = max(dp[i & 1][j][k][l], dp[i & 1][j - 1][k][l] + clas[1][j]);
					}
					if (k > 0) {
						dp[i & 1][j][k][l] = max(dp[i & 1][j][k][l], dp[i & 1][j][k - 1][l] + clas[2][k]);
					}
					if (l > 0) {
						dp[i & 1][j][k][l] = max(dp[i & 1][j][k][l], dp[i & 1][j][k][l - 1] + clas[3][l]);
					}
					n = max(n, dp[i & 1][j][k][l]);
					m += e + 3;
				}
				h += e + 2;
			}
			g += e + 1;
		}
		f += e;
	}
	printf("%lld\n", n);
	return 0;
}

