ll solve(int a, int b, int c, int d){
    //printf("%d %d %d %d\n", a, b, c, d);
    int sum = a*vec[0][0].fi+b*(vec[0][0].fi+1)+c*(vec[0][0].fi+2)+d*(vec[0][0].fi+3);
    int ha = ((100*d+c)*100+b)*100+a;
    if (sum > tot) return -inf;
    if (m.count(ha))
        return m[ha];


    //printf("bef ans\n");
    ll ans = 0;
    if (a != vec[0].size())
        ans = max(ans, solve(a+1, b, c, d)+vec[0][a].se);
    if (b != vec[1].size())
        ans = max(ans, solve(a, b+1, c, d)+vec[1][b].se);
    if (c != vec[2].size())
        ans = max(ans, solve(a, b, c+1, d)+vec[2][c].se);
    if (d != vec[3].size())
        ans = max(ans, solve(a, b, c, d+1)+vec[3][d].se);

    return m[ha] = ans;
}

