    int LA = wt[0].size(), LB = wt[1].size(), LC = wt[2].size(), LD = wt[3].size();

    long long best = 0, A = 0, B = 0, C = 0, D = 0, wa = 0, wb = 0, wc = 0, wd = 0;

    for(int a = LA; a >= 0; --a){
