                }
                D = wd = 0;
                for(int d = LD; d >= 0; --d){
                    if(d < LD){
                        D += wt[3][d];
                        wd += weight[0] + 3;
                    }
                    if(wa + wb + wc + wd > w)
                        continue;
                    best = max(best, A + B + C + D);
                }
            }
        }
    }

    cout << best << "\n";

    return 0;

}

