using namespace std;

typedef long long int lli;

#define N_MAX 100
#define W_MAX 3
#define MOD 1000000007

pair<int, int> table[N_MAX];
int memo[N_MAX][N_MAX + 1][N_MAX*W_MAX+1];

int func(int index, int cnt, int sum)
{
	if (sum < 0){
		return -1;
	}
	if (cnt < 0){
		return -1;
	}
	if (-2 != memo[index][cnt][sum]){
		return memo[index][cnt][sum];
	}
	if (0 == index){
		if (cnt > 1){
			return -1;
		}
		else if (1 == cnt){
			if (table[index].first <= sum){
				return table[index].second;
			}
			else{
				return -1;
			}
		}
		else{
			return 0;
		}
	}

	int val1 = func(index - 1, cnt - 1, sum - table[index].first);
	if (-1 != val1){
		val1 += table[index].second;
	}
	int val2 = func(index - 1, cnt, sum);

	return memo[index][cnt][sum] = (val1 > val2 ? val1 : val2);
}

void solv()
{
	int N, W; scanf("%d%d", &N, &W);
	for (int i = 0; i < N; i++){
		int w, v; scanf("%d%d", &w, &v);
		table[i] = make_pair(w, v);
	}

	int w0 = table[0].first;
	for (int i = 0; i < N; i++){
		table[i].first -= w0;
	}

	for (int i = 0; i < N; i++){
		for (int j = 0; j <= N; j++){
			fill(memo[i][j], memo[i][j] + N_MAX*W_MAX + 1, -2);
		}
	}

	int ret = 0;
	for (int cnt = 1; cnt <= N; cnt++){
		if (w0*cnt > W){
			break;
		}
		ret = max(ret, func(N - 1, cnt, min(W - w0*cnt, W_MAX*N)));
	}

	printf("%d\n", ret);

	return;
}

