				if (w[i+1]+box > W)continue;
				M[i + 1][j + 1][w[i]] = v[i];
				ans = max(M[i + 1][j + 1][w[i]], ans);
				continue;
			}
			for (int k = j*-3; k <= j * 3; k++) {
				if (k + w[i + 1] + box*(j + 1) > W)continue;
				if (M[i][j][k]) {
					M[i + 1][j + 1][k + w[i]] = max(M[i][j][k] + v[i + 1], M[i + 1][j + 1][k + w[i]]);
					ans = max(ans, M[i + 1][j + 1][k + w[i]]);
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

