int w[100],v[100];
int n,W;
int dp[100][100000];
int knapsack(){
	memset(dp,0,sizeof(dp));
	dp[0][w[0]] = v[0];
	for(int i = 1;i < n;i++){
		int j;
		for(j = 0;j < w[i] && j <= W;j++){
			dp[i][j] = dp[i-1][j];
		}
		for(j = w[i];j <= W;j++){
			dp[i][j] = max(dp[i-1][j],dp[i-1][j-w[i]]+v[i]);
		}
	}
	int ans = 0;
	for(int i = W;i >= 0;i--){
		if(dp[n-1][i] > ans) ans = dp[n-1][i];
	}
	return ans;
}

int solve(){
	int W2 = W%w[0];
	int dp2[100][101][300];
	memset(dp2,0,sizeof(dp2));
	int w2[100];
	for(int i = 0;i < n;i++){
		w2[i] = w[i]-w[0];
	}
	dp2[0][1][w2[0]] = v[0];
	for(int i = 1;i < n;i++){
		for(int j = 1;j <= n;j++){
			int k;
			for(k = 0;k < w2[i];k++){
				dp2[i][j][k] = dp2[i-1][j][k];
			}
			for(k = w2[i];k < 300;k++){
				dp2[i][j][k] = max(dp2[i-1][j][k],dp2[i-1][j-1][k-w2[i]]+v[i]);
			}
		}
	}
	int ans = 0;
	for(int i = 0;i < W/w[0];i++){
		for(int j = 0;j < 300;j++){
			if(i*w[0]+j > W) break;
			if(dp2[n-1][i][j] > ans) ans = dp2[n-1][i][j];
		}
	}
	return ans;
}

int main() {
	cin >> n >> W;
	for(int i = 0;i < n;i++){
		cin >> w[i] >> v[i];
	}
	if(w[0] > 300){
		cout << solve() << endl;
	}
	else{
		cout << knapsack() << endl;
	}
}

