int N,W;

int solve(int i, int w_max)
{
    if (i == N)
        return 0;
    if (mem[i].find(w_max) != mem[i].end()) {
        return mem[i][w_max];
    }

    int v1=0,v2=0;
    if (w_max >= weights[i]) {
        v1 = solve(i+1, w_max-weights[i]) + values[i];
    }
    v2 = solve(i+1, w_max);
    int ans = max(v1,v2);
    //pr(i) pr(w_max) pr(ans) nl
    mem[i][w_max] = ans;
    return ans;
}

