const LL INF = -12345678901234567;
LL dp(int i, int j, int d)
{
	if (j < 0 || d < 0)return INF;
	if (i == 0)
	{
		if (j != 0 || d != 0)return INF;
		return 0;
	}
	if (~memo[i][j][d])return memo[i][j][d];
	LL ans = dp(i - 1, j - 1, d - w[i - 1]) + v[i - 1];
	ans = max(ans, dp(i - 1, j, d));
	return memo[i][j][d] = ans;
}

