bool judge(int n, int sum, int para) {
  int s = 0;
  int lb = lower_bound(all(weight_list), weight[0] + para) - begin(weight_list);
  if (lb < n) {
    rep (i, n) {
      if (i == lb) { continue; }
      s += weight_list[i];
    }
  } else {
    s += weight_list[lb];
    rep (i, n-1) {
      if (i == lb) { continue; }
      s += weight_list[i];
    }
  }
  return s <= sum;
}

