ll rec( int i, ll j )
{
  if( i == 0 || j <= 0 )
    return 0;

  if( dp.count( P(i,j) ) )
    return dp[P(i,j)];

  if( j-w[i-1] >= 0 )
    return dp[P(i,j)] = std::max( rec( i-1, j ), rec( i-1, j-w[i-1] )+v[i-1] );
  else
    return dp[P(i,j)] = rec( i-1, j );
}

