    take( ll w[], ll nowv ) {
      t[ 0 ] = w[ 0 ];
      t[ 1 ] = w[ 1 ];
      t[ 2 ] = w[ 2 ];
      t[ 3 ] = w[ 3 ];
      sm = 0;
      for ( int i = 0 ; i < 4 ; ++i )
        sm += t[ i ];
      value = nowv;
    }
    ll t[ 4 ], sm, value;
};
int main() {
  cin >> n >> w;
  for ( int i = 0 ; i < n ; ++i )
    cin >> a[ i ] >> b[ i ];

  for ( int i = 0 ; i < n ; ++i ) {
    ll idx = a[ i ] - a[ 0 ];
    v[ idx ].push_back( make_pair( b[ i ], i ) );
  }
  for ( int i = 0 ; i < 4 ; ++i ) {
    sort( v[ i ].begin(), v[ i ].end() );
    reverse( v[ i ].begin(), v[ i ].end() );
  }

  if ( w <= 1e5 ) {
    ll tmp[ 4 ] = { 0, 0, 0, 0 };
    queue< pair< ll, take > > q;
    q.push( make_pair( 0, take( tmp, 0 ) ) );
    while ( !q.empty() ) {
      ll weight = q.front().first;
      take now = q.front().second;
      q.pop();
      if ( now.value > ans )
        ans = now.value;
      if ( now.sm == n ) continue;
      /*
      cout << "now: " << weight << endl;
      for ( int i = 0 ; i < 4 ; ++i )
        cout << now.t[ i ] << ' ';
      cout << now.sm << ' ' << now.value << endl;
      */
      for ( int i = 0 ; i < 4 ; ++i ) {
        if ( now.t[ i ] == v[ i ].size() ) continue;
        if ( weight + a[ 0 ] + i > w ) continue;
        ll now_num[ 4 ];
        for ( int j = 0 ; j < 4 ; ++j )
          now_num[ j ] = now.t[ j ];
        now_num[ i ] += 1;
        /*
        cout << "now_num ";
        for ( int j = 0 ; j < 4 ; ++j )
          cout << now_num[ j ] << ' ';
        cout << endl;
        cout << v[ i ][ now_num[ i ] - 1 ].first << endl;
        */
        q.push( make_pair( weight + a[ 0 ] + i, take( now_num, now.value + v[ i ][ now_num[ i ] - 1 ].first ) ) );
      }
    }
  }
  else {
    ll total = 0;
    for ( int i = 0 ; i < 4 ; ++i )
      total += v[ i ].size() * ( a[ 0 ] + i );
    if ( total <= w ) {
      cout << accumulate( b, b + n, 0 ) << endl;
      return 0;
    }
    total = 0;
    ll r = 0, l = 0;
    for ( int i = 0 ; i < 4 ; ++i )
      for ( int j = 0 ; j < v[ i ].size() ; ++j ) {
        total += a[ 0 ] + i;
        if ( total > w )
          break;
        ++r;
      }
    for ( int i = 3 ; i >= 0 ; --i )
      for ( int j = 0 ; j < v[ i ].size() ; ++j ) {
        total += a[ 0 ] + i;
        if ( total > w )
          break;
        ++l;
      }
    vector< pair< ll, ll > > final;
    for ( int i = 0 ; i < n ; ++i )
      final.push_back( make_pair( b[ i ], a[ i ] ) );
    sort( final.begin(), final.end() ); reverse( final.begin(), final.end() );
    ll now_sum = 0;
    for ( int i = 0 ; i < l ; ++i )
      now_sum += final[ i ].first;
    if ( l == r ) {
      cout << now_sum << endl;
      return 0;
    }
    else {
      ll now_weight = 0;
      for ( int i = 0 ; i < l ; ++i )
        now_weight += final[ i ].second;
      if ( now_weight + final[ l ].second <= w )
        cout << now_sum + final[ l ].first << endl;
      else
        cout << now_sum << endl;
    }
  }

  cout << ans << endl;
}

