using namespace std;

int main()
{
    int64_t N, W;
    std::cin >> N >> W;

    struct Bag {
        int64_t weight;
        int64_t value;
    };

    std::vector<Bag> B;
    int64_t W0;
    for (decltype(N) i = 0; i < N; ++i) {
        Bag t;
        std::cin >> t.weight >> t.value;
        if (i == 0) {
            W0 = t.weight -1;
        }
        B.push_back(t);
        B.back().weight -= W0;
    }

    #include <boost/multi_array.hpp>

    boost::multi_array<int64_t, 3> memo(boost::extents[101][101][5*100]);
// const auto Y = memo.shape()[0];
// const auto X = memo.shape()[1];

    std::fill(memo.data(), memo.data() + memo.num_elements(), -1);

    for (auto p = memo.data(); p < (memo.origin() + memo.num_elements()); ++p) {
        std::cin >> *p;
    }


    auto f = [&memo,W0, N, W, &B](auto F, int64_t i, int64_t s, int64_t w) -> int64_t {

        if (memo[i][s][w] != -1) {
            return memo[i][s][w];
        }
        if (i == N) {
            return 0;
        }

        if (w + B[i].weight <= W - (s+1)*W0) {
            memo[i][s][w] = std::max(F(F, i+1, s+1, w+B[i].weight) + B[i].value, F(F, i+1, s, w));
        }
        else {
            memo[i][s][w] = F(F, i+1, s, w);
        }
        return memo[i][s][w];
    };

    auto val = f(f, 0, 0, 0);

    std::cout << val << std::endl;

    return 0;
}

