void solve() {
    int n;
    ll w;
    cin >> n >> w;
    vector<vector<ll>> vals(4, {0});
    ll w1 = 0;
    for (int i=0; i<n; ++i) {
        int x, y;
        cin >> x >> y;
        if (i == 0) {
            w1 = x;
        }
        vals.at(x-w1).push_back(y);
    }
    for (int i=0; i<4; ++i) sort(vals.at(i).begin(), vals.at(i).end());
    for (int i=0; i<4; ++i) reverse(vals.at(i).begin()+1, vals.at(i).end());
    int l0 = (int)vals.at(0).size();
    int l1 = (int)vals.at(1).size();
    int l2 = (int)vals.at(2).size();
    int l3 = (int)vals.at(3).size();
    for (int i=1; i<l0; ++i) vals.at(0).at(i) += vals.at(0).at(i-1);
    for (int i=1; i<l1; ++i) vals.at(1).at(i) += vals.at(1).at(i-1);
    for (int i=1; i<l2; ++i) vals.at(2).at(i) += vals.at(2).at(i-1);
    for (int i=1; i<l3; ++i) vals.at(3).at(i) += vals.at(3).at(i-1);
