				k = min((int)pref[3].size() - 1, k);

				int tren = pref[0][i] + pref[1][j] + pref[2][l] + pref[3][k];
				sol = max(sol, tren);
			} 
		}
	}
	printf("%d", sol);
	return 0;
}

