long long dp(int x, int take, int sum) {
    long long weight = 1LL * take * init + sum;
    if(weight > W) return -inf;
    if(x == N+1) {
        return 0;
    }
    if(mem[x][take][sum] != -1) return mem[x][take][sum];

    long long ans = -inf;
    ans = max(ans, dp(x + 1, take, sum));
    ans = max(ans, v[x] + dp(x + 1, take + 1, sum + w[x]));
    return mem[x][take][sum] = ans;
}

