		}

		cout << list[n - 1] << flush;
	}

	//VLLの配列をソートする
	static void Sort_VLL(VVLL & x, LL n) {
		auto function = [&](VLL a, VLL b) {
			return a[n] < b[n];
		};

		sort(x.begin(), x.end(), function);
	}

	//デバッグ用出力
