    rep(i, dp1.size())dp1[i] = i == 0 ? w1[i] : dp1[i - 1] + w1[i];
    rep(i, dp2.size())dp2[i] = i == 0 ? w2[i] : dp2[i - 1] + w2[i];
    rep(i, dp3.size())dp3[i] = i == 0 ? w3[i] : dp3[i - 1] + w3[i];
