void solve(long long N, long long W, std::vector<long long> w, std::vector<long long> v)
{

    vector<ll> dp[4];
    ll first = w[0];
    for (int i = 0; i < N; i++)
    {
        dp[w[i] - first].push_back(v[i]);
    }

    for (int i = 0; i < 4; i++)
    {
        RSORT(dp[i]);

        for (int j = 1; j < dp[i].size(); j++)
        {
            dp[i][j] += dp[i][j - 1];
        }
    }

    ll ans = 0;
    for (int a = 0; a <= dp[0].size(); a++)
    {
        for (int b = 0; b <= dp[1].size(); b++)
        {
            for (int c = 0; c <= dp[2].size(); c++)
            {
                for (int d = 0; d <= dp[3].size(); d++)
                {
                    if (N < a + b + c + d)
                    {
                        continue;
                    }
                    if (a * first + b * (first + 1) + c * (first + 2) + d * (first + 3) > W)
                    {
                        continue;
                    }
                    ll value = 0;

                    if (a != 0)
                    {
                        value += dp[0][a - 1];
                    }
                    if (b != 0)
                    {
                        value += dp[1][b - 1];
                    }
                    if (c != 0)
                    {
                        value += dp[2][c - 1];
                    }
                    if (d != 0)
                    {
                        value += dp[3][d - 1];
                    }
                    ans = max(ans, value);
                }
            }
        }
    }
    cout << ans << endl;
}

int main()
{
    long long N;
    scanf("%lld", &N);
    long long W;
    scanf("%lld", &W);
    std::vector<long long> w(N);
    std::vector<long long> v(N);
    for (int i = 0; i < N; i++)
    {
        scanf("%lld", &w[i]);
        scanf("%lld", &v[i]);
    }
    solve(N, W, std::move(w), std::move(v));
    return 0;
}

