					dp[k][j] = max(dp[k][j], dp[k - 1][j - idx] + items[i].v);
				}
			}
		}
	}
	LONG ans = 0;
	REP(j, 301) REP(k, 101) {
		int cost = k * items[0].w + j;
		if (cost > W) continue;
		ans = max(dp[k][j], ans);
	}
	cout << ans << endl;
	return 0;
}

