pair<LL, LL> CalSum(vector<pair<LL, LL>> const& ls, LL count) {
	LL w, v;
	w = v = 0;

	LL i, j, k;
	for (i = 0; i < count; i++) {
		w += ls[i].first;
		v += ls[i].second;
	}

	return make_pair(w, v);
}

pair<LL, LL> CalSum(vector<vector<pair<LL, LL>>> const& ls, VLL count) {
	LL i, j, k, n, m, v, w;
	v = w = 0;
	for (i = 0; i < 4; i++) {
		auto temp = CalSum(ls[i], count[i]);
		w += temp.first;
		v += temp.second;
	}

	return make_pair(w, v);
}

