int dfs(vector<vector<int>> &vw, int lv, int vt, int w, int wb, int wlim){
  if(lv == 4){
    if(w > wlim) return 0;
    else return vt;
  }
  int ret = dfs(vw, lv+1, vt, w, wb, wlim);
  int sum = 0;
  rep(i, vw.at(lv).size()){
    sum += vw.at(lv).at(i);
    if(w + (i+1)*(lv+wb) > wlim) break;
    int r = dfs(vw, lv+1, vt+sum, w + (i+1)*(lv+wb), wb, wlim);
    // cerr << r << endl;
    if(r > ret) ret = r;
  }
  return ret;
}

