void solve(void)
{
  int N,xW;
  cin>>N>>xW;
  vector<int> W (N,0);
  vector<int> V (N,0);

  for (int i = 0; i < N; i++)
  {
    cin>>W[i]>>V[i];
  }
  // DEBUG(W);
  // DEBUG(V);
  vector<vector<int> > DP (N+1,vector<int>(xW+1,0));
  for (int i = 0; i < N; i++)
  {
    for (int w = 0; w <= xW; w++)
    {
      if(W[i] > w)
      {
        DP[i+1][w] = DP[i][w];
      }
      else
      DP[i+1][w] = max(max(DP[i][w],DP[i][w - W[i]]+V[i]),DP[i+1][w]);
    }
  }
  // DEBUG(DP);
  cout<<DP[N][xW]<<endl;





  return;
}


