	for (auto i = 0; i < N; ++i)
	{
		cin >> w[i] >> v[i];
	}

	set<ll> s;
	for (auto i = 1; i <= N; ++i)
	{
		for (auto j = 0; j <= i * 3; ++j)
		{
			auto temp = w[0] * i + j;
			if (temp <= W)
			{
				s.insert(temp);
			}
		}
	}
	s.insert(W);

	vector<ll> x;
	x.push_back(0);
	for (auto v : s)
	{
		x.push_back(v);
	}

	vector<vector<ll>> dp(N + 1, vector<ll>((int)x.size(), -1));
	dp[0][0] = 0;
	for (auto i = 0; i < N; ++i)
	{
		for (auto j = 0; j < (int)x.size(); ++j)
		{
			dp[i + 1][j] = dp[i][j];
			if (j <= 0)
			{
				continue;
			}

			auto weight = x[j];
			if (weight < w[i])
			{
				continue;
			}
			auto it = lower_bound(x.begin(), x.end(), weight - w[i]);
			if (it == x.end() || *it != weight - w[i])
			{
				continue;
			}
			auto k = it - x.begin();
			if (dp[i][k] < 0)
			{
				continue;
			}
			dp[i + 1][j] = max(dp[i + 1][j], dp[i][k] + v[i]);
		}
	}

	auto ans = 0ll;
	for (auto i = 0; i < (int)x.size(); ++i)
	{
		ans = max(ans, dp[N][i]);
	}
	cout << ans << endl;

	return 0;
}

