                if (k >= w[i] && dp[i - 1][j - 1][k - w[i]] + v[i] > dp[i-1][j][k]) {
                    dp[i][j][k] = dp[i-1][j-1][k-w[i]] + v[i];
                } else {
                    dp[i][j][k] = dp[i-1][j][k];
                }
            }
        }
    }
    unsigned long long max = 0;
    for (unsigned i = 1; i <= N; ++i) {
        if (i * C <= W) {
            max = std::max(max, dp[N][i][std::min(3 * N, W - i * C)]);
        }
    }
    std::cout << max << std::endl;
    return 0;
