using LL = long long;
LL N,w;
LL W, V;
LL size[4],ww[4];
LL ans;
std::vector<LL> dp[4];
void value(LL x, LL y, LL z, LL q) {
	LL sum = 0;
	for (LL aa = 0; aa < x; aa++) {
		sum += dp[0][aa];
	}
	for (LL aa = 0; aa < y; aa++) {
		sum += dp[1][aa];
	}
	for (LL aa = 0; aa < z; aa++) {
		sum += dp[2][aa];
	}
	for (LL aa = 0; aa < q; aa++) {
		sum += dp[3][aa];
	}
	ans = std::max(ans, sum);
	sum = 0;
}
void solve() {
	for (LL i = 0; i <= size[0]; i++) {
		for (LL j = 0; j <= size[1]; j++) {
			for (LL k = 0; k <= size[2]; k++) {
				for (LL l = 0; l <= size[3]; l++) {
					ww[0] = i*w;
					ww[1] = j*(w + 1);
					ww[2] = k*(w + 2);
					ww[3] = l*(w + 3);
					if ((ww[0] + ww[1] + ww[2] + ww[3]) > W) {
						break;
					}
						value( i, j, k, l);
				}
			}
		}
	}
}
