		dp[tmp-w].push_back(Q);
	}
	for (LL i = 0;  i < 4; i++) {
		std::sort(dp[i].begin(), dp[i].end());
		size[i] = dp[i].size();
	}
	solve();
	std::cout << ans << std::endl;
	return 0;
}

