    rep (i, n) wv[i].first -= w_std;
    rep (i, n) {
        rep (j, i + 1) {
            reprev (k, min(MAX_LEN - 3, w + 1)) {
                chmax(dp[i + 1][j + 1][k + wv[i].first], dp[i][j][k] + wv[i].second);
