using namespace std;

int N, W;
vector<int> weight;
vector<int> value;

int dp[100][100][300];

int pack(int now, int packed, int weight_now){
    if(now == N){
        return 0;
    }else if(dp[now][packed][weight_now - packed * weight[0]] != -1){
        return dp[now][packed][weight_now - packed * weight[0]];
    }else if(weight_now + weight[now] > W){
        return dp[now][packed][weight_now - packed * weight[0]] = pack(now + 1, packed, weight_now);
    }else{
        return dp[now][packed][weight_now - packed * weight[0]] = max(pack(now + 1, packed, weight_now), value[now] + pack(now + 1, packed + 1, weight_now + weight[now]));
    }
}

int main(){
    cin >> N >> W;
    weight.resize(N);
    value.resize(N);
    for(int i = 0; i < N; i++){
        cin >> weight[i] >> value[i];
    }
    for(int i = 0; i < 100; i++){
        for(int j = 0; j < 100; j++){
            for(int k = 0; k < 300; k++){
                dp[i][j][k] = -1;
            }
        }
    }
    cout << pack(0, 0, 0) << endl;
}

