int main()
{
	int N, W;
	cin >> N >> W;
	for (int i = 0; i < N; i++) cin >> w[i] >> v[i];
	int base = w[0];
	for (int i = 0; i < N; i++) {
		V[w[i] - base].push_back(v[i]);
	}
	for (int i = 0; i < 4; i++) {
		sort(V[i].rbegin(), V[i].rend());
	}
	ll ans = 0;
	for (int i = 0; i < 25; i++) {
		for (int j = 0; j < 25; j++) {
			for (int k = 0; k < 25; k++) {
				for (int l = 0; l < 25; l++) {
					if (i > V[0].size()) continue;
					if (j > V[1].size()) continue;
					if (k > V[2].size()) continue;
					if (l > V[3].size()) continue;
					ll value = 0;
					ll weight = 0;
					weight += i * base;
					weight += j * (base + 1);
					weight += k * (base + 2);
					weight += l * (base + 3);
					if (weight > W) continue;
					//cout << i << " " << j << " " << k << " " << l << endl;
					for (int q = 0; q < i; q++) value += V[0][q];
					for (int q = 0; q < j; q++) value += V[1][q];
					for (int q = 0; q < k; q++) value += V[2][q];
					for (int q = 0; q < l; q++) value += V[3][q];
					ans = max(ans, value);
				}
			}
		}
	}
	cout << ans << endl;
}

