using namespace std;

using ll = long long;
using p = pair<ll, ll>;

constexpr ll INF = 1LL << 62;
constexpr ll MOD = 1e9 + 7;
constexpr ll MAX_N = 100;
ll dp[MAX_N + 1][MAX_N + 1][MAX_N + 1][MAX_N + 1];

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, W;
    cin >> N >> W;

    vector<p> inputs(N);
    vector<ll> V[4];
    ll min_weight = INF;
    for (ll i = 0; i < N; i++) {
        ll w, v;
        cin >> w >> v;
        inputs[i] = p(w, v);
        min_weight = min(min_weight, w);
    }

    for (auto in : inputs) {
        V[in.first - min_weight].push_back(in.second);
    }

    for (ll i = 0; i < 4; i++) {
        sort(V[i].begin(), V[i].end());
    }

    for (ll a = 0; a <= V[0].size(); a++) {
        for (ll b = 0; b <= V[1].size(); b++) {
            for (ll c = 0; c <= V[2].size(); c++) {
                for (ll d = 0; d <= V[3].size(); d++) {
                    ll weight = a * min_weight + b * (min_weight + 1) + c * (min_weight + 2) + d * (min_weight + 3);
                    if (weight > W) {
                        dp[a][b][c][d] = -INF;
                    } else {
                        ll ans = dp[a][b][c][d];
                        if (a > 0) {
                            ans = max(ans, dp[a - 1][b][c][d] + V[0][a - 1]);
                        }
                        if (b > 0) {
                            ans = max(ans, dp[a][b - 1][c][d] + V[1][b - 1]);
                        }
                        if (c > 0) {
                            ans = max(ans, dp[a][b][c - 1][d] + V[2][c - 1]);
                        }
                        if (d > 0) {
                            ans = max(ans, dp[a][b][c][d - 1] + V[3][d - 1]);
                        }

                        dp[a][b][c][d] = ans;
                    }
                }
            }
        }
    }

    ll ans = 0;
    for (ll a = 0; a <= V[0].size(); a++) {
        for (ll b = 0; b <= V[1].size(); b++) {
            for (ll c = 0; c <= V[2].size(); c++) {
                for (ll d = 0; d <= V[3].size(); d++) {
                    ans = max(ans, dp[a][b][c][d]);
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

