const int N = 110;
const long long inf = 1e18;

int n, W;
int w[N], v[N], base;
long long dp[N][N][3 * N];
long long ans;

void mxm(long long &a, long long b) {
	if (a < b) a = b;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n >> W;
	for (int i = 1; i <= n; ++i) cin >> w[i] >> v[i];

	base = w[1];
	for (int i = 1; i <= n; ++i) w[i] -= base;

	for (int i = 0; i < N; ++i) {
		for (int choose = 0; choose < N; ++choose) {
			for (int add = 0; add <= choose * 3; ++add) {
				dp[i][choose][add] = -inf;
			}
		}
	}

	dp[0][0][0] = 0;
	for (int i = 1; i <= n; ++i) {
		for (int choose = 0; choose < i; ++choose) {
			for (int add = 0; add <= 3 * choose; ++add) {
				if (dp[i-1][choose][add] == -inf) continue;
				// don't choose a[i]
				mxm(dp[i][choose][add], dp[i-1][choose][add]);
				// choose a[i]
				long long real_sum = 1LL * (choose + 1) * base + add + w[i];
				if (real_sum <= W) {
					mxm(dp[i][choose + 1][add + w[i]], dp[i-1][choose][add] + v[i]);
				}
			}
		}
	}

	for (int choose = 0; choose <= n; ++choose) {
		for (int add = 0; add <= 3 * choose; ++add) {
			ans = max(ans, dp[n][choose][add]);
		}
	}

	cout << ans << endl;
}

