// w0, W
int DFS(const vector<vector<int>> &ws, vector<int>& v, const int w, const int w0, const int W, const int value) {
	int res = 0;
	for (int i = 0; i < 4; ++i) {
		v[i]--;
		if ((w + w0 + i) <= W && v[i] >= 0) {
			res = max(res, DFS(ws, v, w+w0+i, w0, W, value + ws[i][ws[i].size() - v[i] - 1]));
		}
		v[i]++;
	}
	if (res == 0) {
		return value;
	}
	return res;
}

