LL ans;
LL W, w1;
vl v[4], c[4];

void TZL()
{
	int n; scf(n);
	scf(W);
	scf(w1);
	LL x; scf(x);
	v[0].pb(x);
	forn(i, 1, n - 1)
	{
		LL ww, vv; scf(ww, vv);
		v[ww - w1].pb(vv);
	}
	rep(i, 4) sort(ALL(v[i])), reverse(ALL(v[i]));
	rep(i, 4) if(SZ(v[i]))
	{
		c[i].resize(SZ(v[i]));
		c[i][0] = v[i][0];
		forn(j, 1, SZ(v[i]) - 1) c[i][j] = c[i][j - 1] + v[i][j];
	}
	return;
}

void RANK1()
{
	forn(i0, 0, SZ(v[0])) forn(i1, 0, SZ(v[1])) forn(i2, 0, SZ(v[2]))
	{
		LL lft = W - (LL)i0 * w1 - (LL)i1 * (w1 + 1ll) - (LL)i2 * (w1 + 2ll);
		if(lft < 0) continue;
		LL cur = 0;
		if(i0) cur += c[0][i0 - 1];
		if(i1) cur += c[1][i1 - 1];
		if(i2) cur += c[2][i2 - 1];
		LL can_chs = lft / (w1 + 3ll);
		if(can_chs > SZ(c[3])) can_chs = SZ(c[3]);
		if(can_chs) cur += c[3][can_chs - 1];
		chkmax(ans, cur);
	}
	printf("%lld\n", ans);
	return;
}

