map<tuple<int, int>, int> cache;
vi VS;
vi WS;

ll knapsack(int n, int maxw) {
  if (n == -1) {
    return 0;
  }
  int v = VS[n];
  int w = WS[n];
  tuple<int, int> keys = mkt(n, maxw);
  if (cache.find(keys) != cache.end()) {
    return cache[keys];
  } else {
    ll ans = 0;
    if (maxw < w) {
      ans = knapsack(n-1, maxw);
    } else {
      ans = max(knapsack(n-1, maxw-w) + v, knapsack(n-1, maxw));
    }
    cache[keys] = ans;
    return ans;
  }
}

