  // dp[i][j][k] : i番目より手前の品物中から
  //               j個の品物を選び、余りの重さの総和が
  //               kとなるときのvの最大値

int main() {
  cin >> N >> W;

  for (int i = 0; i < N; i++) {
    cin >> w[i];
    cin >> v[i];
  }
  w0 = w[0];
  for (int i = 0; i < N; i++) {
    w[i] -= w0;
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      fill(dp[i][j], dp[i][j] + N * 4, -INF);
    }
  }
  for (int i = 0; i < N; i++) {
    dp[i][0][0] = 0;
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j <= i; j++) {
      for (int k = 0; k < N * 4; k++) {
        dp[i+1][j  ][k       ] = max(dp[i+1][j  ][k       ], dp[i][j][k]       );
        dp[i+1][j+1][k + w[i]] = max(dp[i+1][j+1][k + w[i]] ,dp[i][j][k] + v[i]);
      }
    }
  }

  int ans = 0;
  for (int i = 0; i <= N; i++) {
    for (int j = 0; j <= i; j++) {
      for (int k = 0; k < N * 4; k++) {
        if (j * w0 + k <= W) {
          ans = max(ans, dp[i][j][k]);
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

