int solve(int ind, int tezina,int br)
{	

	if(long(tezina)+long(br)*long(off) > lim) return -1e9;
	if(ind == n) return 0;

	if(memo[ind][tezina][br] != 0)
		return memo[ind][tezina][br];

	int w = items[ind].first;
	int v = items[ind].second;
	int ret =  max(solve(ind+1,tezina, br), solve(ind+1, tezina+w, br+1) + v);
	memo[ind][tezina][br] = ret;
	return ret;
}


