	vector<ITEM> p(N);
	for (long i=0; i<N; i++)
		cin >>p.at(i).wei >>p.at(i).val;
	long w1=p.at(0).wei;
	vector<vector<long>> WW(4);
	for (long i=0; i<N; i++)
		WW.at(p.at(i).wei-w1).push_back(p.at(i).val);
