		sort(WW.at(i).begin(), WW.at(i).end());
		reverse(WW.at(i).begin(), WW.at(i).end());
	}
	long S=0;
	for (int i0=0; i0<=WW.at(0).size(); i0++) {
		long WWW0=i0*w1;
		if (WWW0>W)
			break;
		for (int i1=0; i1<=WW.at(1).size(); i1++) {
			long WWW1=WWW0+i1*(w1+1);
