				for (int j=0; j<i1; j++)
					SS +=WW.at(1).at(j);
				for (int j=0; j<i2; j++)
					SS +=WW.at(2).at(j);
				for (int j=0; j<i3; j++)
					SS +=WW.at(3).at(j);
				S=max(S, SS);
			}
		}
	}
	cout <<S <<endl;
	return 0;
}

