ll n;

ll knapsack(ll index, ll rem){
	if(rem==0) return 0;
	if(index>n) return 0;
	if(used[pii(index,rem)]) return dp[pii(index,rem)];
	ll ret=0;
	if(weight[index]>rem) ret=knapsack(index+1,rem);
	else ret = max(knapsack(index+1,rem),value[index]+knapsack(index+1,rem-weight[index]));
	used[pii(index,rem)]=true;
	return dp[pii(index,rem)]=ret;
}

