std::uint64_t run(std::array<std::vector<std::uint64_t>, 4>const& data, int index, std::uint64_t rest, std::uint64_t first)
{
	if (index == 4)
	{
		return 0;
	}
	std::uint64_t max{};
	for (int i{}; i < data[index].size() && (first + index)*i <= rest; ++i)
	{
		max = std::max(max, run(data, index + 1, rest - (first + index)*i, first) + data[index][i]);
	}
	return max;
}

