int values[110], weights[110];

int sDP[101][100][101];

int saved;

int dp(short index, int weight, int cnt) {
	int &ret = sDP[index][weight][cnt];
	if (ret != -1) return ret;

	if (index == n-1) {
		weight += weights[index];
		cnt++;
		if (weight + cnt*saved > w) {
			return ret = 0;
		} else {
			return ret = values[index];
		}
	}

	ret = dp(index+1, weight, cnt);
	if (weight + weights[index] + (cnt+1)*saved <= w) {
		ret = max(ret, dp(index+1, weight + weights[index], cnt+1) + values[index]);
	}

	return ret;
}

