        vvc<ll> dp(K + 1, vl(Wd + 1)); //k個選び、重さWkであるときの最大価値
        rep(i,N){
            ll w,v;
            tie(w, v) = J[i];

            repr(k, K){
                rep(j,Wd+1){
                    if(j>=w)
                        dp[k + 1][j] = max(dp[k + 1][j], dp[k][j - w] + v);
                }
            }
        }
        // cout << "K= " << K << endl;
        // rep(i,K+1){
        //     rep(j, Wd + 1) cout << dp[i][j] << " ";
        //     cout << endl;
        // }
        // cout << endl;
        chmax(ans, dp[K][Wd]);
    }

    cout << ans << endl;

}

