//	f_t(){f[0]=f[1]=f[2]=f[3]=0;}
	bool operator < (const f_t& rhs) const {
		return memcmp(f, rhs.f, 16)<0;
	}
};


int N, W;
vector<x_t> x;
map<f_t,x_t> m;


int max(int a, int b)
{
	if(a>b) return a;
	return b;
}


int max_u(int &m, int v)
{
	if(m<v) m=v;
	return m;
}


x_t solve(int n, f_t f, int w, int v)
{
	x_t a, b;

	if(w>W) return (x_t){w, 0};
	if(n<0) return (x_t){w, v};
	if(m.find(f)!=m.end()) return m[f];

	a=solve(n-1, f, w, v);
	m[f]=a;

	f.f[n/32]|=(1<<(n%32));
	b=solve(n-1, f, w+x[n].w, v+x[n].v);
	m[f]=b;

	if(a.v>b.v) return a;
	return b;
}


