int _main()
{
    ll n, w;
    llin(n); llin(w);

    V<t2> wvlist;
    llinl2(wvlist, n);

    ll wbase = get<0>(wvlist[0]);
    V<ll> vallist[4];  // wsub --> value

    for (auto wv : wvlist) {
        ll w = get<0>(wv);
        ll v = get<1>(wv);
        ll wsub = w - wbase;

        assert(0LL <= wsub && wsub <= 3);

        vallist[wsub].pb(v);
    }
    sort_reverse(vallist[0]);
    sort_reverse(vallist[1]);
    sort_reverse(vallist[2]);
    sort_reverse(vallist[3]);

    assert(vallist[0].size() + vallist[1].size() +
           vallist[2].size() + vallist[3].size() == n);

    V<ll> valsum[4];
    rep (wsub, 4) {
        valsum[wsub].pb(0LL);
        rep (i, vallist[wsub].size()) {
            valsum[wsub].pb(valsum[wsub][i] + vallist[wsub][i]);
        }
    }

    ll w0c = valsum[0].size();
    ll w1c = valsum[1].size();
    ll w2c = valsum[2].size();
    ll w3c = valsum[3].size();
    assert(w0c + w1c + w2c + w3c == n + 4LL);

    ll ans = 0LL;

    rep (w0, w0c) rep (w1, w1c) rep (w2, w2c) rep (w3, w3c) {
        ll count = w0 + w1 + w2 + w3;
        ll wsum = w1 + w2 * 2LL + w3 * 3LL + count * wbase;
        if (wsum > w) continue;
        ans = max(ans,
                  valsum[0][w0] + valsum[1][w1] + valsum[2][w2] + valsum[3][w3]);
    }

    cout << ans;
    return 0;
}

