ll solve(int N,int W,vi& w,vi& v){
    int w0 = w[0];
    vi dw(N); rep(i,N) dw[i] = w[i] - w0;

    vvi dp(101, vi(301, -1));
    // dp[個数][Σdw] = Σv
    dp[0][0] = 0;
    rep(i, N) {
        // vvi dp2(101, vi(300, 0));
        int dw_i = dw[i];
        int v_i = v[i];
        for (int k=i; k>=0; --k) {
            for (int j=0; j<=300; ++j) {
                if (dp[k][j] == -1) continue;
                if (j+dw_i <= 300) {
                    dp[k+1][j+dw_i] = max(dp[k+1][j+dw_i], dp[k][j] + v_i);
                }
            }
        }
    }

    int ans = 0;
    for (int k=0; k<=100; ++k) {
        ll base = (ll)w0 * k;
        ll room = W - base;
        if (room < 0) break;
        int rmax = min(300, (int)room);
        // dp[k][0] .. dp[k][room]
        int best = 0;
        for (int j=0; j<=rmax; ++j) {
            if (dp[k][j] == -1) continue;
            best = max(best, dp[k][j]);
        }
        // fprintf(stderr, "k=%d, best=%d\n", k,best);
        ans = max(ans, best);
    }
    return ans;
}

