int main()
{
	ll N, W;
	ll w[101];
	ll v[101];
	cin >> N >> W;
	for(int i = 1; i <= N; i++){
		cin >> w[i] >> v[i];
	}
	w[0] = 0;
	v[0] = 0;

	static ll DP[101][101][3*100+1];
	for(int i = 0; i < 101; i++){
		for(int j = 0; j < 101; j++){
			for(int k = 0; k < 301; k++){
				DP[i][j][k] = 0;
			}
		}
	}

	for(int n = 1; n <= N; n++){
		for(int m = 0; m <= n; m++){
			ll w_ = w[n] - w[1];
			for(int g = 0; g <= 3*100; g++){
				DP[n][m][g] = DP[n-1][m][g];
				if(m > 0 && g >= w_ && m*w[1] + g <= W){
					DP[n][m][g] = max(DP[n][m][g], DP[n-1][m-1][g-w_] + v[n]);
				}
			}
		}
	}

	ll ans = 0;
	for(int m = 0; m <= N; m++){
		for(int g = 0; g <= 3*100; g++){
			if(w[1] * m + g <= W){
				//cout << m << " , " << g << " : " << DP[N][m][g] << endl;
				ans = max(ans, DP[N][m][g]);
			}
		}
	}

	cout << ans << endl;

	return 0;
}

