{
	scanf("%d %lld",&n,&max_w);
	scanf("%lld %lld",&w[0],&v[0]);
	table[0].pb(v[0]);
	for(int i=1;i<n;i++) {
		scanf("%lld %lld",&w[i],&v[i]);
		if(w[i]==w[0]) table[0].pb(v[i]);
		if(w[i]==w[0]+1) table[1].pb(v[i]);
		if(w[i]==w[0]+2) table[2].pb(v[i]);
		if(w[i]==w[0]+3) table[3].pb(v[i]);
	}
	//urut dari besar ke kecil
	for(int i=0;i<4;i++) {
		sz[i] = table[i].size();
		sort(table[i].begin(),table[i].end());
		table[i].pb(0);
		reverse(table[i].begin(),table[i].end());
		for(int j=1;j<=sz[i];j++) table[i][j]+=table[i][j-1];
	}
	//find max value
	ll ans = 0;
	for(int i=0;i<=sz[0];i++) {
		for(int j=0;j<=sz[1];j++) {
			for(int k=0;k<=sz[2];k++) {
