        if (a * w1 + b * (w1 + 1) + c * (w1 + 2) > W) break;
        long long d = (W - a * w1 + b * (w1 + 1) + c * (w1 + 2)) / (w1 + 3);
        ans = std::max(ans, v[0][a] + v[1][b] + v[2][c] + v[3][d]);
      }
    }
  }
  printf("%lld\n", ans);
  return 0;
}

