    std::uint64_t v;
};

inline bool operator<(wv const& lhs, wv const& rhs) {
    if (lhs.w < rhs.w) return true;
    if (rhs.w < lhs.w) return false;
    if (lhs.v < rhs.v) return true;
    return false;
}

auto memo = std::map<std::multiset<wv>, std::uint64_t>();

std::uint64_t solve(std::vector<wv> vec, std::multiset<wv>& choose, std::uint64_t wmax) {
    std::uint64_t biggest = 0;
    do {
        std::uint64_t wsum = 0;
        std::uint64_t vsum = 0;
        for (wv const& e : vec) {
            wsum += e.w;
            if (wsum > wmax) break;
            vsum += e.v;
            // choose.insert(e);
            // memo.emplace(choose, vsum);
        }
        biggest = std::max(vsum, biggest);
    } while (std::next_permutation(vec.begin(), vec.end()));
    return biggest;
}

