long long rec(int i, int j){
  if(dp[i][j] >= 0){
    return dp[i][j];
  }
  int res;
  if(i == n){//品物が残っていない
    res = 0;
  }else if(j < w[i]){//この品物は入らない
    res = rec(i+1,j);
  }else{//入れない場合と入れる場合を両方試す
    res = max(rec(i+1,j), rec(i+1, j-w[i]) + v[i]);
  }
  return dp[i][j] = res;
}

long long rec2(int i, int j){
  if(dp[i][j] >= 0){
    return dp[i][j];
  }
  int res;
  if(i == n){//品物が残っていない
