int64_t fast(int64_t N, int64_t W, V<int> weights, V<int> values) {
	int64_t w0 = weights[0];

	V<V<int64_t>> items(4);

	REP(i, N) {
		items[weights[i]-w0].push_back(values[i]);
	}

	REP(i, 4) {
		sort(items[i].begin(), items[i].end());
		reverse(items[i].begin(), items[i].end());
	}

	// V<int64_t> csum3(items[3].size());
	// if (items[3].size())
	// 	csum3[0] = items[3][0];
	// for (int i = 1; i < items[3].size(); ++i) {
	// 	csum3[i] += csum3[i-1]+items[3][i];
	// }


	int64_t ans = 0, v0 = 0, v1 = 0, v2 = 0, v3 = 0;

	for (int64_t cnt0 = 0; cnt0 <= items[0].size(); ++cnt0) {
		v1 = 0;
		for (int64_t cnt1 = 0; cnt1 <= items[1].size(); ++cnt1) {
			v2 = 0;
			for (int64_t cnt2 = 0; cnt2 <= items[2].size(); ++cnt2) {
				v3 = 0;
				for (int64_t cnt3 = 0; cnt3 <= items[3].size(); ++cnt3) {
					if (cnt0*w0+cnt1*(w0+1)+cnt2*(w0+2)+cnt3*(w0+3) <= W)
						ans = max(ans, v0+v1+v2+v3);
					if (items[3].size())
						v3 += items[3][cnt3];
				}
				// int64_t cnt3 = N-(cnt0+cnt1+cnt2);
				// cnt3 = min(cnt3, (int64_t)items[3].size());
				// v3 = 0;
				// if (cnt3)
				// 	v3 = csum3[cnt3-1];
				// cout << cnt0 << " " << cnt1 << " " << cnt2 << " " << cnt3 << endl;
				// cout << cnt0 << " " << v1 << " " << v2 << " " << v3 << endl;
				// cout << endl;
				// if (cnt0*v0+cnt1*(w0+1)+cnt2*(w0+2)+cnt3*(w0+3) <= W)
				// 	ans = max(ans, v0+v1+v2+v3);
				if (items[2].size())
					v2 += items[2][cnt2];
			}
			if (items[1].size())
				v1 += items[1][cnt1];
		}
		if (items[0].size())
			v0 += items[0][cnt0];
	}
	return ans;
}

int64_t brute(int64_t N, int64_t W, V<int> weights, V<int> values) {
	int64_t ans = 0;
	for (int bs = 0; bs < (1<<N); ++bs) {
		int64_t v = 0, w = 0;
		REP(i, N) if (bs&(1<<i)) {
			v += values[i];
			w += weights[i];
		}
		if (w > W)
			continue;
		ans = max(ans, v);
	}
	return ans;
}

