int main(){
    int n; long long m;
    scanf("%d%lld",&n,&m);
    for(int i = 1; i <= n; i++){
        scanf("%lld%lld",&w[i],&v[i]);
    }
    int size[4] = {0,0,0,0};
    long long fst = w[1];
    for(int i = 1; i <= n; i++){
        long long p = w[i]-fst;
        a[p][++size[p]] = v[i];
    }
    for(int i = 0; i < 4; i++){ 
        std::sort(a[i]+1,a[i]+1+size[i],[&](long long u,long long v){
            return u>v;
        });
        sum[i][0] = 0;
        for(int j = 1; j <= size[i]; j++) sum[i][j] = sum[i][j-1]+a[i][j];
    }
    long long ans = 0;
    for(int i = 0; i <= size[0]; i++){
        for(int j = 0; j <= size[1]; j++){
            for(int k = 0; k <= size[2]; k++){
                for(int l = 0; l <= size[3]; l++){
                    long long offer = sum[0][i]+sum[1][j]+sum[2][k]+sum[3][l];
                    long long weight = i*1ll*fst+j*1ll*(fst+1ll)+k*1ll*(fst+2ll)+l*1ll*(fst+3ll);
                    if(weight<=m && ans<offer) ans = offer;
                }
            }
        }
    }
    printf("%lld\n",ans);
    return 0;
