using namespace std;

const int MAX_N = 110;
const int MAX_EXTRA_W = 3 * MAX_N;

int64_t dp[2][MAX_N][MAX_EXTRA_W];

int main() {
  int N;
  int64_t W;
  cin >> N >> W;
  memset(dp, -1LL, sizeof(dp));

  int64_t w0, v0;
  cin >> w0 >> v0;
  int prev = 0;
  int next = 1;
  dp[1][0][0] = 0;
  dp[1][1][0] = v0;

  for (int i = 1; i < N; i++) {
    swap(prev, next);
    memcpy(dp[next], dp[prev], sizeof(dp[next]));

    int64_t w, v;
    cin >> w >> v;
    int extraW = w - w0;

    for (int totalN = 1; totalN <= i + 1; totalN++) {
      for (int prevExtraW = 0; prevExtraW + extraW <= 3 * totalN;
           prevExtraW++) {
        if (dp[prev][totalN - 1][prevExtraW] == -1) continue;
        if (dp[next][totalN][prevExtraW + extraW] >
            dp[prev][totalN - 1][prevExtraW] + v) {
          continue;
        }

        dp[next][totalN][prevExtraW + extraW] =
            dp[prev][totalN - 1][prevExtraW] + v;
      }
    }
  }

  int64_t maxValue = 0LL;
  for (int n = 1; n <= N; n++) {
    for (int64_t extraW = 0; extraW < MAX_EXTRA_W; extraW++) {
      int64_t totalW = w0 * n + extraW;
      if (totalW <= W) {
        maxValue = max(maxValue, dp[n & 1][n][extraW]);
      }
    }
  }
  printf("%ld\n", maxValue);

  return 0;
}

