int s[4][MAX_N];

int Bs(int l, int r, int tmp_w)
{
  while (r - l > 1) {
    int mid = (l + r) / 2;
    if (tmp_w + (w1 + 3) * l <= W) l = mid;
    else r = mid;
  }
  return l;
}

