ll N, W, ans;
ll w[110], v[110];
ll dp[110][110][330];

ll solv(ll i, ll j, ll k) {
	if (i == N) return 0;
	if (dp[i][j][k] > 0) return dp[i][j][k];
	ll next_k = w[i] - w[0], cur_sum_w = w[0] * j + k;
	dp[i + 1][j][k] = solv(i + 1, j, k);
	if (cur_sum_w + w[i] <= W) {
		dp[i + 1][j + 1][k + next_k] = solv(i + 1, j + 1, k + next_k) + v[i];
		return max(dp[i + 1][j][k], dp[i + 1][j + 1][k + next_k]);
	}
	else {
		return dp[i + 1][j][k] = solv(i + 1, j, k);
	}

}

