    cin >> N >> W;
    vector<pair<int, int> > vw(N);//vw[0][i]は重さ、vw[1][i]は価値
    vector<int> w_nums(4);
    fill(w_nums.begin(), w_nums.end(), 0);

    for(int i=0; i<N; i++){
        int tmp1, tmp2;
        cin >> tmp1 >> tmp2;
        vw[i] = make_pair(tmp1, tmp2);
        w_nums[vw[i].first-vw[0].first]++;
    }
    sort(vw.begin(), vw.end());
    vector<int> value[4];
    /*for(int i=0; i<N; i++){
        cout << vw[i].first << ',' << vw[i].second << endl;
    }*/

    int tmp=0;
    for(int i=0; i<4; i++){
        value[i].push_back(0);
        for(int j=0; j<w_nums[i]; j++){//重さが重いものから埋めていく
            value[i].push_back(value[i][j]+vw[w_nums[i]+tmp-j-1].second);
        }
        tmp+=w_nums[i];
    }

    int ans=0;
    for(int a=0; a<min(w_nums[0], N)+1; a++){
        int wa=a*vw[0].first;
        if(wa>W) continue;
        for(int b=0; b<min(w_nums[1], N-a)+1; b++){
            int wb=wa+b*(vw[0].first+1);
            if(wb>W) continue;
            for(int c=0; c<min(w_nums[2], N-a-b)+1; c++){
                int wc=wb+c*(vw[0].first+2);
                if(wc>W) continue;
                for(int d=0; d<min(w_nums[3], N-a-b-c)+1; d++){
                    int wd=wc+d*(vw[0].first+3);
                    if(wd>W) continue;
                    ans=max(ans, value[0][a]+value[1][b]+value[2][c]+value[3][d]);
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

