#include <vector>
#include <map>
#include <iostream>
#include <algorithm>

using namespace std;
typedef long long ll;


ll sol(ll n, ll w, vector<ll> wis, vector<ll> vis) {
    ll ret = 0, wi, vi, last, cw, cv, nw, nv, bw;
    map<ll, vector<ll>* > best;
    vector<ll> *tmp, flast, fwis, fvis;
    for (ll i = 0; i < n; i++) {
        wi = wis[i];
        vi = vis[i];
        if(wi <= w) {
            if(best.find(wi) == best.end()) {
                tmp = new vector<ll>(n, 0);
                best.insert(pair<ll, vector<ll>* >(wi, tmp));
            }
            best[wi]->at(i) = vi;
            flast.push_back(i);
            fwis.push_back(wi);
            fvis.push_back(vi);
        }
    }

    while(!flast.empty()) {
        last = flast.back(); flast.pop_back();
        cw = fwis.back(); fwis.pop_back();
        cv = fvis.back(); fvis.pop_back();
        for (ll i = last + 1; i < n; i++) {
            nw = cw + wis[i];
            nv = cv + vis[i];
            if(nw <= w) {
                if(best.find(nw) == best.end()) {
                    tmp = new vector<ll>(n, 0);
                    best.insert(pair<ll, vector<ll>* >(nw, tmp));
                }
                if(best[nw]->at(i) < nv) {
                    best[nw]->at(i) = nv;
                    flast.push_back(i);
                    fwis.push_back(nw);
                    fvis.push_back(nv);
                    ret = max(ret, nv);
                }
            }
        }

    }

    return ret;
}


