    vector<ll> wis, vis;
    for (ll i = 0; i < n; i++) {
        cin >> tmp;
        wis.push_back(tmp);
        cin >> tmp;
        vis.push_back(tmp);
    }
    cout << sol(n, w, wis, vis) << endl;
    return 0;
}

