                    dp[i + 1][j + 1][ww] = max(dp[i + 1][j + 1][ww], dp[i][j][ww - w[i]] + v[i]);
            }
        }
    }
    int ans = 0;
    rep(j, N) {
        rep(ww, MAX_W) {
            if((j + 1) * (tmp - 1) + ww == W)
                ans = max(ans, dp[N][j + 1][ww]);
        }
    }
    cout << ans << endl;
}

