			for(int j=W-ws[i];j>=0;j--) if(dpA[j]>=0) if(dpA[j+ws[i]]<dpA[j]+vs[i]) dpA[j+ws[i]]=dpA[j]+vs[i];
		}
		for(int j=0;j<=W;j++) if(dpA[j]>sol) sol=dpA[j];
	} else {
		int allowed=W/ws[0];
		if(allowed>N) {
			allowed=N;
		}
		int rem=W-allowed*ws[0];
		if(rem>607) rem=607;
		for(int loop=0;loop<2;loop++) {
			if(allowed<=0) break;
			for(int i=0;i<108;i++) {
				for(int j=0;j<608;j++) dpB[j][i]=-INF;
