int n, W, w[mxn], v[mxn], w1, memo[mxn][mxn][mxw];
bitset<mxw> vstd[mxn][mxn];
int dp(int at, int cntTaken, int weightTaken) {
    int actualWeightTaken = cntTaken*w1+weightTaken;
    if (actualWeightTaken>W) return -inf;
    if (at==n+1) return 0;
    auto &ret = memo[at][cntTaken][weightTaken];
    if (vstd[at][cntTaken][weightTaken]) return ret;
    vstd[at][cntTaken][weightTaken] = 1;
    ret = max(v[at]+dp(at+1, cntTaken+1, weightTaken+w[at]), dp(at+1, cntTaken, weightTaken));
    return ret;
}

