long dfs(long ww, long vv) {
  long ret = vv;

  int d = 0, e = 0;
  REP(i, 0, 4) if(idx[i] < p[i].size()) d += b + i, e += p[i][idx[i]];

  if(ww + d <= W) {
    int f[4] = { 0, 0, 0, 0 };
    REP(i, 0, 4) if(idx[i] < p[i].size()) idx[i]++, f[i] = 1;
    ret = max(ret, dfs(ww + d, vv + e));
    REP(i, 0, 4) if(f[i] == 1) idx[i]--;
  } else {
    REP(i, 0, 4) {
      if(idx[i] < p[i].size() && ww + b + i <= W) {
        ret = max(ret, dfs(ww + b + i, vv + p[i][idx[i]++]));
        idx[i]--;
      }
    }
  }

  return ret;
}

