    rep(j, W+1) {
        if (j < w[0]) dp[0][j] = 0;
        else dp[0][j] = v[0];
    }

    for (int j = 1; j <= W; ++j) {
        for (int i = 1; i < N; ++i) {
            if (j >= w[i]) dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]] + v[i]);
            else dp[i][j] = dp[i-1][j];
        }
    }

    cout << dp[N-1][W] << endl;
    return 0;
}

