long long int W,N,res=0;
long long int dp[105][105][305]={},w[234],v[234];

int main()
{

  cin>>N>>W;
  //一番最初の品の重さをメモする変数
	long long int W1=0;
	for(long long int i = 1; i <= N; i++){
		cin>>w[i]>>v[i];
	}
  //w[1]をメモ
	W1=w[1];
  //w[i]からW1を引くことでw[i]を0~3の範囲に抑え込める。N=100のときでも和は300を超えない。
	for(long long int i = 1; i <= N; i++){
		w[i]-=W1;
	}
  //dpの遷移。iはどの品を今見ているかを表す
	for(long long int i = 1; i <= N; i++){
    //jは今までに何品選んだかどうかを表す。i番目より前をみた時最大でもi-1品しか選んでいないのでj<iの範囲でループ。
		for(long long int j = 0; j < i; j++){
      //kは今までに選んだ品のw[i]の和を表す。j品選んだ時最大でも重さは3*jなのでk<=3*jの範囲でループ。
			for(long long int k = 0; k <= 3*j; k++){
        //i番目の品を選んだ時
				dp[i][j+1][k+w[i]] = max(dp[i][j+1][k+w[i]],dp[i-1][j][k]+v[i]);
        //i番目の品を選ばなかった時
				dp[i][j][k]=max(dp[i][j][k],dp[i-1][j][k]);
			}
		}
	}
  //条件を満たす中で最も価値の大きいものを見つける。
	for(long long int j = 0; j <= N; j++){
		for(long long int k = 0; k <= 3*j; k++){
      //dp[N][j][k]について、ナップサック内の重さの和はj*W1+kでこれがW以下でないといけない。
			if((j*W1)+k<=W){res = max(res,dp[N][j][k]);}
		}
	}
	cout<<res<<endl;


}

