        items[vec[i].first - mini].push_back(vec[i].second);
    }
    for(int i=0;i<4;++i)sort(items[i].rbegin(), items[i].rend());
    i64 ans = 0;
    for(i64 i=0;i<=items[0].size();++i){
        for(i64 j=0;j<=items[1].size();++j){
            for(i64 k=0;k<=items[2].size();++k){
                i64 wl = W - (i*mini + j*(mini+1) + k*(mini+2));
