        DP[i+1][w] = max(DP[i][w], DP[i+1][w]);
      }
      else
      {
      DP[i+1][w] = max(DP[i][w],DP[i][max(0,w - W[i])]+V[i]);
      }
    }
  }
  // DEBUG(DP);
  cout<<DP[N][xW]<<endl;





  return;
}


