            w1 = x;
        }
        vals.at(x-w1).push_back(y);
    }
    for (int i=0; i<4; ++i) sort(vals.at(i).begin(), vals.at(i).end());
    for (int i=0; i<4; ++i) reverse(vals.at(i).begin()+1, vals.at(i).end());
    int l0 = (int)vals.at(0).size();
    int l1 = (int)vals.at(1).size();
    int l2 = (int)vals.at(2).size();
    int l3 = (int)vals.at(3).size();
