			D[i][j].v = 0;
			for (int k = 0; k < 103; ++k)	D[i][j].pack[k] = false;
		}
	}

	// 表埋め
	for (int i = 1; i <= n; ++i)
	{
		for (int j = 0; j <= lim; ++j)
		{
