				if(D[i - 1][j].v < D[i - 1][j - w[i]].v + v[i]){
					D[i][j].w = D[i - 1][j - w[i]].w + w[i];
					D[i][j].v = D[i - 1][j - w[i]].v + v[i];
					for (int k = 0; k < 103; ++k)	D[i][j].pack[k] = D[i - 1][j - w[i]].pack[k];
					D[i][j].pack[i] = true;
				}
				else{
					D[i][j].w = D[i - 1][j].w;
					D[i][j].v = D[i - 1][j].v;
					for (int k = 0; k < 105; ++k)	D[i][j].pack[k] = D[i - 1][j].pack[k];
					D[i][j].pack[i] = true;
				}
			}

			// count up 'true'
			cnt = 0;
			for (int k = 0; k < 103; ++k)
			{
				if(D[i][j].pack[k])	++cnt;
			}

			// check weight
			if(D[i][j].w <= (lim - min * (TLong)cnt) && max < D[i][j].v)	max = D[i][j].v;

			// dbg.
