void solve_dp2() {
  for (int j = 0; j <= W; j++) {
    dp[n][j] = 0;
  }
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j <= W; j++) {
      if (j < w[i])
        dp[i][j] = dp[i + 1][j];
      else
        dp[i][j] = fmax(dp[i + 1][j], dp[i + 1][j - w[i]] + v[i]);
    }
  }
  printf("%d", dp[0][W]);
}

#include <stdio.h>
#define MAXN 110
#define MAXW 500
int max(int a, int b) { return a > b ? a : b; }
int solve(int* w, int* v, int N, int W) {
    static int m[MAXN][MAXW];
    int mi = w[0];
    for(int i = 0; i < N; i++) W -= mi, w[i] -= mi;
    for(int i = 1; i < N; i++)
        for(int j = 0; j < W; j++)
            if(w[i] > j) m[i][j] = m[i - 1][j];
            else m[i][j] = max(m[i - 1][j], m[i - 1][j - w[i]] + v[i]);
    return m[N][W];
}
int main(void) {
    int N, W, v[MAXN], w[MAXN];
    scanf("%d", &N);
    for(int i = 0; i < N; i++) scanf("%d%d", &w[i], &v[i]);
    printf("%d", solve(w, v, N, W));
    return 0;
}

