				}
			}
		}
	}
	for(i=0;i<=n;i++){
		for(j=0;j<=i*3;j++){
			if(w1*i+j>w) break;
			if(dp[n-1][i][j]!=-1) max=MAX(max,dp[n-1][i][j]);
		}
	}
