int search_max (double rate[], int weight[], int size, int line){
  int i;
  double max = 0;
  int max_num = -1;
  for(i=0;i<size;i++){
    if(rate[i]>max && weight[i]<=line){
      max = rate[i];
      max_num = i;
    }
  }
  return max_num;
}

