void solve_dp2() {
  for (int j = 0; j <= W; j++) {
    dp[n][j] = 0;
  }
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j <= W; j++) {
      if (j < w[i])
        dp[i][j] = dp[i + 1][j];
      else
        dp[i][j] = fmax(dp[i + 1][j], dp[i + 1][j - w[i]] + v[i]);
    }
  }
  printf("%d", dp[0][W]);
}

