fun yorukatsu18e() {
    val (n, w) = readLine()!!.split(' ').map { it.toInt() }.let { it[0] to it[1].toLong() }
    val items = (1..n).map {
        readLine()!!.split(' ').map { it.toLong() }.let { Item(it[0], it[1]) }
    }

    val a1 = items.first()

    val grouped = items.map { Item(it.weight, it.value - a1.value) }
        .groupBy { it.value }
        .mapValues {
            val cSum = LongArray(n + 1)
            for (i in 0 until n) cSum[i + 1] = cSum[i] + (it.value.getOrNull(i)?.weight ?: 0)
            it.value.size to cSum
        }.toList().sortedBy { it.first }

    var answer = 0L

    for (i in 0..n) for (j in 0..n - i) for (k in 0..n - i - j) for (l in 0..n - i - j - k) {
        var weightSum = 0L
        var priceSum = 0L
        listOf(i, j, k, l).take(grouped.size).forEachIndexed { index, take ->
            val (value, pair) = grouped[index]
            val (size, cSum) = pair
            weightSum += cSum[take]
            priceSum += (value + a1.value) * Math.min(take, size)
        }
        if (weightSum <= w)
            answer = Math.max(answer, priceSum)
    }

    println(answer)
}

