    var answer = 0L

    for (i in 0..n) for (j in 0..n-i) for (k in 0..n-i-j) for (l in 0..n-i-j-k) {
        val filtered = listOf(i, j, k, l).withIndex().mapNotNull {
            if (it.index !in grouped.indices) return@mapNotNull null
            val take = grouped[it.index].second.take(it.value)
            val weightSum = take.map { it.weight }.sum()
            weightSum to grouped[it.index].first * Math.min(it.value, take.size)
        }
        val weightSum = filtered.map { it.first }.sum()
        if (weightSum <= w)
            answer = Math.max(answer, filtered.map { it.second }.sum())
    }


    println(answer)
}

