fun solve() {
    val n = nextLong()
    val W = nextLong()
    val elem = longAry2(n, 2)
    val list: Array<MutableList<Long>> = Array(4) { mutableListOf<Long>() }
    val weight = longAry(4)
    for (i in 0 until n) {
        elem[i][0] = nextLong()
        elem[i][1] = nextLong()
    }
    elem.sortBy { it[0] }
    var nowweight = elem[0][0]
    weight[0] = nowweight
    var index = 0L
    for (i in 0 until n) {
        when (nowweight) {
            elem[i][0] -> {
                list[index].add(elem[i][1])
            }
            else -> {
                nowweight = elem[i][0]
                index++
                weight[index] = nowweight
                list[index].add(elem[i][1])
            }
        }
    }

    for (i in list.indices) {
        list[i].sortDescending()
    }


    var vsum1 = 0L
    var wsum1 = 0L
    var ans = 0L
    for (i in 0..list[0].siz) {

        if(i > 0) {
            vsum1 += list[0][i - 1]
            wsum1 += weight[0]
        }
        if(list[1].isEmpty() && wsum1 <= W) {
            ans = max(ans, vsum1)
            continue
        }
        var vsum2 = 0L
        var wsum2 = 0L
        for (j in 0..list[1].siz) {

            if(j > 0) {
                vsum2 += list[1][j - 1]
                wsum2 += weight[1]
            }
            if(list[2].isEmpty() && wsum1 + wsum2 <= W) {
                ans = max(ans, vsum1 + vsum2)
                continue
            }
