            for (k in 0..list[2].siz) {
                if(k > 0) {
                    vsum3 += list[2][k - 1]
                    wsum3 += weight[2]
                }
                if(list[3].isEmpty() && wsum1 + wsum2 + wsum3 <= W) {
                    ans = max(ans, vsum1 + vsum2 + vsum3)
