                for (l in 0..list[3].siz) {
                    if(l > 0) {
                        vsum4 += list[3][l - 1]
                        wsum4 += weight[3]
                    }
                    if(wsum1 + wsum2 + wsum3 + wsum4 <= W) {
                        ans = max(ans, vsum1 + vsum2 + vsum3 + vsum4)
                    }
                }
            }
        }
