        }
        int M = 1000;
        long[][][] dp = new long[2][N + 1][M + 10];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                for (int k = 0; k <= M; k++) {
                    if (k - w[i] >= 0) {
                        if ((long)j * base + k <= W && dp[i & 1][j + 1][k] < dp[i & 1][j][k - w[i]] + v[i]) {
                            dp[(i + 1) & 1][j + 1][k] = dp[i & 1][j][k - w[i]] + v[i];
