	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int N = in.nextInt();
			int W = in.nextInt();
			List<Integer>[] g = new ArrayList[4];
			g = Stream.generate(ArrayList::new).limit(4).toArray(List[]::new);

			int[] w = new int[N], v = new int[N];
			for (int i = 0; i < N; i++) {
				w[i] = in.nextInt();
				v[i] = in.nextInt();
				g[w[i]-w[0]].add(v[i]);
			}

			for (int i = 0; i < 4; i++) {
				Collections.sort(g[i], Comparator.reverseOrder());
			}

			long ans = 0;
			for (int i = 0; i <= g[0].size(); i++) {
				for (int j = 0; j <= g[1].size(); j++) {
					 for (int k = 0; k <= g[2].size(); k++) {
						for (int l = 0; l <= g[3].size(); l++) {
							if (i + j + k + l > N) continue;
							long tmp = 0;
							long tweight = w[0] * (long)(i + j + k + l);
							for (int m = 0; m < i; m++) {
								tmp += g[0].get(m);
							}
							for (int m = 0; m < j; m++) {
								tmp += g[1].get(m);
								tweight += 1;
							}
							for (int m = 0; m < k; m++) {
								tmp += g[2].get(m);
								tweight += 2;
							}
							for (int m = 0; m < l; m++) {
								tmp += g[3].get(m);
								tweight += 3;
							}
							if (tweight <= W) ans = Math.max(ans, tmp);
						}
					}
				}
			}

			out.println(ans);

		}
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public char nextChar() {
			while (true) {
				final int c = read();
				if (!isSpace[c]) {
					return (char) c;
				}
			}
		}

		public String nextString() {
			return new String(nextChars());
