        int n = sc.nextInt();
        long maxw = sc.nextLong();
        Sina sina[] = new Sina[n];
        for (int i = 0; i < n; i++) {
            sina[i] = new Sina(sc.nextLong(), sc.nextLong());
        }

        Arrays.sort(sina,
            (o1, o2) -> (o1.w == o2.w) ? Long.compare(o1.v, o2.v) : Long.compare(o1.w, o2.w));

        if (maxw < sina[0].w) {
            System.out.println(0);
            return;
        }

        Map<Long, Long> map = new HashMap<>();
        map.put(0L, 0L);
        for (int i = 0; i < n; i++) {
            long w = sina[i].w;
            long v = sina[i].v;

            List<Map.Entry<Long, Long>> list = map.entrySet().stream().collect(Collectors.toList());
            for (Map.Entry<Long, Long> e : list) {
