    Main(ConsoleIO io) {
        this.io = io;
    }

    long MOD = 1_000_000_007;
    List<List<Integer>> gr = new ArrayList<>();

    public void solve() {
        int N = io.ri();
        long W = io.ri();
        Piece[] all = new Piece[N];
        long sum = 0;
        for(int i =0;i<N;i++){
            int a = io.ri();
            int b= io.ri();
            all[i] = new Piece(b,a);
            sum+=a;
        }

        long res = 0;
        if(sum <= W) {
            for(int i = 0;i<N;i++)
                res+=all[i].c;
            io.writeLine(res+"");
            return;
        }

        if(N==1 || all[0].w>W) {
            io.writeLine("0");
            return;
        }

        if(W*N<=10_000_000L){
            res = calc(all, (int)W);
            io.writeLine(res+"");
            return;
        }

        int k1 = N, k2 = N;
        int w1 = (int)W, w2 = (int)W;

        if(all[0].w>1) {
            k1 = (int)W / (all[0].w - 1);
            w1 = (int)W % (all[0].w - 1);

            k2 = k1-1;
            w2 = (int)W - k2*(all[0].w - 1);

            for (int i = N; i >= 0; i--) {
                all[i].w -= all[0].w - 1;
            }
        }
        Arrays.sort(all, (p1, p2) -> p1.c > p2.c ? -1 : (p1.c < p2.c ? 1 : 0));
        io.writeLine(Math.max(ccc(all, w1, k1), ccc(all, k2,w2)) + "");
    }

    long ccc(Piece[] all, int W, int k){

        long sum = 0;
        long res=  0;
        for(int i = 0;i<k;i++) {
            sum += all[i].w;
            res+=all[i].c;
        }

        if(sum<=W){
            return res;
        }

        long[][] dp = new long[k+1][(int)W+1];
        for (int q = 0; q < all.length; q++) {
            Piece p = all[q];
            for(int i = Math.min(q+1,k);i>0;i--) {
                long[] wi = dp[i];
                long[] wi1 = dp[i - 1];
                for (int j = (int)W; j > 0; j--) {
                    wi[j] = Math.max(wi[j-1], wi1[j]);
                    if (p.w <= j) {
                        wi[j] = Math.max(wi[j], wi1[j - p.w] + p.c);
                    }
                }
            }
        }

        return dp[k][W];
    }

    long calc(Piece[] nums, int W){
        long[] dp = new long[W+1];
        for(int j = 0;j<nums.length;j++){
            Piece p = nums[j];
            for(int i = W;i>=0;i--){
                if(p.w<=i)
                    dp[i] = Math.max(dp[i], dp[i-p.w] + p.c);
            }
        }
        return dp[W];
    }


    class Piece {
        public Piece(int c, int w) {
            this.c = c;
            this.w = w;
        }

        public int c;
        public int w;
    }

}

class ConsoleIO {
