public void solve() {
	int num = ni();
	long w = nl();
	int item[][] = ni(num, 2);
	int minW = item[0][0];
	long value[][] = new long[4][num];
	fill(value, -INF);
	int index[] = {0, 0, 0, 0};
	for(int i = 0; i < num; i ++) {
		int indexW = item[i][0] - minW;
		value[indexW][index[indexW]] = item[i][1];
		index[indexW] ++;
	}
	for(int i = 0; i < 4; i ++) {
		Arrays.sort(value[i]);
		reverse(value[i]);
	}
	long sum[][] = new long[4][num + 1];
	fill(sum, 0);
	for(int i = 0; i < 4; i ++) {
		for(int j = 0; j < num; j ++) {
			sum[i][j + 1] = sum[i][j] + value[i][j];
		}
	}

	long max = 0;
	for(int i = 0; i <= index[0]; i ++) {
		for(int j = 0; j <= index[1]; j ++) {
			for(int k = 0; k <= index[2]; k ++) {
				for(int l = 0; l <= index[3]; l ++) {
					long res = w;
					res -= minW * i + (minW + 1) * j + (minW + 2) * k + (minW + 3) * l;
					if(res < 0) { continue; }
					long tmp = sum[0][i] + sum[1][j] + sum[2][k] + sum[3][l];
					max = max(max, tmp);
				}
			}
		}
	}
	prtln(max);
}



