			NavigableMap<Long, Long> tmp = new TreeMap<>(tm);
			for (Entry<Long, Long> e : tm.entrySet()) {
				long nw = e.getValue() + w[i];
				long nv = e.getKey() + v[i];

				if (nw > ww) {
					break;
				}

				Long tmpw = tmp.get(nv);
				if (tmpw != null) {
					if (tmpw > 0) {
						tmp.put(nv, nw);
					}
				} else {
					tmp.put(nv, nw);
				}
			}

			tm = tmp;
		}

		pr.println(tm.lastKey());
//		pr.println(tm.size());
	}

