        for (int i = 0; i < N; i++){
            long w = sc.nextInt();
            if (min_w == -1){
                min_w = w;
            }
            if (hash.get(w) == null) {
                hash.put(w, new ArrayList<Long>());
            }
            hash.get(w).add(sc.nextLong());
