				if (avail < 0) break;
//				for (int j = 0; j < choice[i]; j++) worth += (Integer) ws[i].get(ws[i].size() - 1 - j);
				worth += (long) prf[i].get(choice[i]);
			}
			if (avail >= 0) max.set(Math.max(worth, max.get()));
			return;
		}

		for (int i = 0; i <= ws[pos].size(); i++) {
			choice[pos] = i;
			doit(choice, ws, prf, pos + 1, max);
		}
	}
}

