long dfs(int num, int[] a, int len, List<List<Long>> vs, long w, long minW) {
	if(len == num) {
		long sumW = sum(a) * minW;
		for(int i = 0; i < 4; i ++) {
			sumW += a[i] * i;
		}
		if(sumW <= w) {
			long ans = 0;
			for(int i = 0; i < 4; i ++) {
				ans += vs.get(i).get(a[i]);
			}
			return ans;
		}
		return 0;
	}
	long max = 0;
	for(int i = 0; i < vs.get(len).size(); i ++) {
		a[len] = i;
		max = max(max, dfs(num, a, len + 1, vs, w, minW));
	}
	return max;
}

