import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Main {
    static Map<Integer, List<Integer>> map;
    static long ans = 0;
    static int[] keys;
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt(), W = in.nextInt();
        map = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int w = in.nextInt(), v = in.nextInt();
            List<Integer> vList = map.get(w);
            if(vList == null) {
                List<Integer> list = new ArrayList<>();
                list.add(v);
                map.put(w, list);
            } else {
                map.get(w).add(v);
            }
        }
        keys = new int[map.keySet().size()];
        int idx = 0;
        for (int key: map.keySet()) {
            keys[idx++] = key;
        }
        solve(W, 0, 0L , 0L);
        map.keySet().stream()
                .map(key -> map.get(key))
                .forEach(list -> Collections.sort(list, Collections.reverseOrder()));
        System.out.println(ans);
    }
    public static void solve(int W, int idx, long wsum, long vsum) {
        if(idx == keys.length) {
            if(wsum <= W) {
                ans = Math.max(ans, vsum);
            }
        } else {
            solve(W, idx+1, wsum, vsum);
          for(int v : map.get(keys[idx])) {
              wsum += keys[idx];
              vsum += v;
              solve(W, idx+1, wsum, vsum);
          }
        }
    }
}

import java.io.PrintWriter;
import java.util.*;

import static java.lang.Math.max;

/**
 * Created by shoya on 2017/04/30.
 */
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int N = sc.nextInt();
        int W = sc.nextInt();
        HashMap<Integer, ArrayList<Integer>> hash = new HashMap<Integer, ArrayList<Integer>>();

        int min_w = -1;
        for (int i = 0; i < N; i++){
            int w = sc.nextInt();
            if (min_w == -1){
                min_w = w;
            }
            if (hash.get(w) == null) {
                hash.put(w, new ArrayList<Integer>());
            }
            hash.get(w).add(sc.nextInt());
        }

        for (int i = min_w; i <= min_w + 3; i++){
            if (hash.get(i) != null) {
                Collections.sort(hash.get(i));
            }
        }

        long ans = 0;
        for (int i = 0; i <= 100; i++){
            if ( i * min_w > W){
                continue;
            }

            for (int j = 0; j <= 100; j++) {
                if (i + j > 100){
                    continue;
                }
                if ( i * min_w + j * (min_w + 1) > W){
                    continue;
                }

                for (int k = 0; k <= 100; k++) {
                    if (i + j + k > 100){
                        continue;
                    }
                    if ( i * min_w + j * (min_w + 1) + k * (min_w + 2) > W){
                        continue;
                    }

                    for (int l = 0; l <= 100; l++) {
                        if (i + j + k + l > 100){
                            continue;
                        }
                        if ( i * min_w + j * (min_w + 1) + k * (min_w + 2) + l * (min_w + 3) > W){
                            continue;
                        }

                        long sum = 0;
                        if (hash.get(min_w) != null) {
                            sum += hash.get(min_w).stream().limit(i).mapToInt(x -> x.intValue()).sum();
                        }
                        if (hash.get(min_w + 1) != null) {
                            sum += hash.get(min_w + 1).stream().limit(j).mapToInt(x -> x.intValue()).sum();
                        }
                        if (hash.get(min_w + 2) != null) {
                            sum += hash.get(min_w + 2).stream().limit(k).mapToInt(x -> x.intValue()).sum();
                        }
                        if (hash.get(min_w + 3) != null) {
                            sum += hash.get(min_w + 3).stream().limit(l).mapToInt(x -> x.intValue()).sum();
                        }
                        ans = max(ans, sum);
                    }
                }
            }
        }


        pw.println(ans);
        pw.flush();
        return;
    }
}

