public void solve() {
	int num = ni();
	long w = nl();
	int item[][] = ni(num, 2);
	int minW = item[0][0];
	long value[][] = new long[4][num];
	fill(value, -INF);
	int index[] = {0, 0, 0, 0};
	for(int i = 0; i < num; i ++) {
		int indexW = item[i][0] - minW;
		value[indexW][index[indexW]] = item[i][1];
		index[indexW] ++;
	}
	long sum[][] = new long[4][num + 1];
	fill(sum, 0);
	for(int i = 0; i < 4; i ++) {
		for(int j = 0; j < num; j ++) {
			sum[i][j + 1] = sum[i][j] + value[i][j];
		}
	}

	long dp[][][] = new long[num + 1][num + 1][num + 1];
	for(int i = 0; i <= index[1]; i ++) {
		fill(dp[i], 0);
		for(int j = 0; j <= index[2]; j ++) {
			for(int k = 0; k <= index[3]; k ++) {
				long res = w;
				res -= (minW + 1) * i + (minW + 2) * j + (minW + 3) * k;
				if(res < 0) { break; }
				int tmp = (int)min(index[0], res / minW);
				dp[i][j][k] = sum[0][tmp] + sum[1][i] + sum[2][j] + sum[3][k];
			}
		}
	}
	long max = 0;
	for(int i = 0; i <= num; i ++) {
		for(int j = 0; j <= num; j ++) {
			max = max(max, max(dp[i][j]));
		}
	}
	prtln(max);
}



