	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int W = sc.nextInt();
		int[] w = new int[n];
		int[] v = new int[n];

		ArrayList<Integer> arr0 = new ArrayList<Integer>();
		ArrayList<Integer> arr1 = new ArrayList<Integer>();
		ArrayList<Integer> arr2 = new ArrayList<Integer>();
		ArrayList<Integer> arr3 = new ArrayList<Integer>();

		arr0.add(0);
		arr1.add(0);
		arr2.add(0);
		arr3.add(0);

		for (int i = 0; i < n; i++) {
			w[i] = Integer.parseInt(sc.next());
			v[i] = Integer.parseInt(sc.next());
			if (w[i] - w[0] == 0)
				arr0.add(v[i]);
			if (w[i] - w[0] == 1)
				arr1.add(v[i]);
			if (w[i] - w[0] == 2)
				arr2.add(v[i]);
			if (w[i] - w[0] == 3)
				arr3.add(v[i]);
		}

		Collections.sort(arr0, Collections.reverseOrder());
		Collections.sort(arr1, Collections.reverseOrder());
		Collections.sort(arr2, Collections.reverseOrder());
		Collections.sort(arr3, Collections.reverseOrder());

		ArrayList<Long> arrsum0 = new ArrayList<Long>();
		ArrayList<Long> arrsum1 = new ArrayList<Long>();
		ArrayList<Long> arrsum2 = new ArrayList<Long>();
		ArrayList<Long> arrsum3 = new ArrayList<Long>();

		arrsum0.add(0l);
		arrsum1.add(0l);
		arrsum2.add(0l);
		arrsum3.add(0l);
		long sum = 0;

		for (int i = 0; i < arr0.size(); i++) {
			sum += arr0.get(i);
			arrsum0.add(sum);
		}

		sum = 0;

		for (int i = 0; i < arr1.size(); i++) {
			sum += arr1.get(i);
			arrsum1.add(sum);
		}

		sum = 0;

		for (int i = 0; i < arr2.size(); i++) {
			sum += arr2.get(i);
			arrsum2.add(sum);
		}

		sum = 0;

		for (int i = 0; i < arr3.size(); i++) {
			sum += arr3.get(i);
			arrsum3.add(sum);
		}

		long max = 0;

		for (int i = 0; i < arr0.size(); i++) {
			for (int j = 0; j < arr1.size(); j++) {
				for (int k = 0; k < arr2.size(); k++) {
					for (int m = 0; m < arr3.size(); m++) {
						if (i * w[0] + j * (w[0] + 1) + k * (w[0] + 2) + m * (w[0] + 3) > W)
							continue;
						max = Math.max(max, arrsum0.get(i) + arrsum1.get(j) + arrsum2.get(k) + arrsum3.get(m));
					}
				}
			}
		}

		System.out.println(max);

	}

}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

	void run() {
		try (Scanner sc = new Scanner(System.in)) {
			int n = sc.nextInt();
			long w = sc.nextLong();
			ArrayList<Long> ws = new ArrayList<Long>();
			List<Long>[] vs = new ArrayList[4];
			for (int i = 0; i < 4; i++) {
				vs[i] = new ArrayList<Long>();
			}

			for (int i = 0; i < n; i++) {
				long ww = sc.nextLong();
				long vv = sc.nextLong();
				int id = ws.indexOf(ww);
				if (id == -1) {
					vs[ws.size()].add(vv);
					ws.add(ww);
				} else {
					vs[id].add(vv);
				}
			}

			for (int i = 0; i < 4; i++) {
				Collections.sort(vs[i]);
			}

			while (ws.size() < 4) {
				ws.add(0L);
			}

			long[][] vSum = new long[4][n + 1];
			for (int i = 0; i < 4; i++) {
				for (int j = 1; j <= vs[i].size(); j++) {
					vSum[i][j] = vSum[i][j - 1] + vs[i].get(j - 1);
				}
			}

			long max = 0;
			for (int a = 0; a <= vs[0].size(); a++) {
				for (int b = 0; b <= vs[1].size(); b++) {
					for (int c = 0; c <= vs[2].size(); c++) {
						for (int d = 0; d <= vs[3].size(); d++) {
							long nSum = (long)ws.get(0) * a + (long)ws.get(1) * b + (long)ws.get(2) * c + (long)ws.get(3) * d;
							if (nSum > w) {
								continue;
							}

							max = Math.max(max, vSum[0][a] + vSum[1][b] + vSum[2][c] + vSum[3][d]);
						}
					}
				}
			}

			System.out.println(max);
		}
	}

	public static void main(String[] args) {
		new Main().run();
	}

}

import java.util.*;

public class Main {
    static final long TIME_LIMIT = System.currentTimeMillis() + 1900L;
    //-------------------------------------------------------------//
    public static final void main(String[] args) { new Main().solve(); }
    //-------------------------------------------------------------//
    Scanner sc = new Scanner(System.in);
    void solve() {
        int N = sc.nextInt();
        int W = sc.nextInt();
        List<Long>[] v = new ArrayList[4];
        for (int i = 0; i < 4; i++) v[i] = new ArrayList<>();
        long baseW = sc.nextLong();
        v[0].add(sc.nextLong());
        for (int i = 1; i < N; i++) {
            long w = sc.nextLong();
            v[(int)(w - baseW)].add(sc.nextLong());
        }

        if (baseW > W) {
            System.out.println(0);
            return;
        }

        for (int i = 0; i < 4; i++) Collections.sort(v[i], new Comparator<Long>() {
            @Override
            public int compare(Long o1, Long o2) {
                return Long.compare(o2, o1);
            }
        });

        int ans = 0;
        Random rnd = new Random();
        while (System.currentTimeMillis() < TIME_LIMIT) {
            int[] idx = new int[4];
            Arrays.fill(idx, 0);
            long cw = 0;
            int sum = 0;
            while (true) {
                int nxtIdx = rnd.nextInt(4);
                while (v[nxtIdx].size() <= idx[nxtIdx])
                    nxtIdx = rnd.nextInt(4);
                cw += nxtIdx + baseW;
                if (cw > W) break;
                sum += v[nxtIdx].get(idx[nxtIdx]);
                idx[nxtIdx]++;
                if (idx[0] == v[0].size() && idx[1] == v[1].size() && idx[2] == v[2].size() && idx[3] == v[3].size()) {
                    break;
                }
            }
            if (sum > ans) {
                ans = sum;
            }
        }
        System.out.println(ans);
    }
}

