class Solver extends Main{
	Solver(long v, long w ,boolean[] used, int[][] items, int lim, long[] acc){
		knapsack(v,w,used,items,lim,acc);
	}
	void knapsack(long v, long w ,boolean[] used, int[][] items, int lim,long[] acc){
		for(int i=0; i<items.length; i++){
			if(used[i]==false && w+items[i][0]<=lim){
				boolean[] nused=Arrays.copyOf(used,used.length);
				nused[i]=true;
				if(acc[0]<v+items[i][1]) acc[0]=v+items[i][1];
				knapsack(v+items[i][1],w+items[i][0],used,items,lim,acc);
			}
		}
	}
}

