    ConsoleIO io;
    Main(ConsoleIO io) {
        this.io = io;
    }

    long MOD = 1_000_000_007;
    List<List<Integer>> gr = new ArrayList<>();

    public void solve() {
        int N = io.ri();
        int W = io.ri();
        Piece[] all = new Piece[N];
        long sum = 0;
        for(int i =0;i<N;i++){
            int a = io.ri();
            int b= io.ri();
            all[i] = new Piece(b,a);
            sum+=a;
        }

        long res = 0;
        if(sum <= W) {
            for(int i = 0;i<N;i++)res+=all[i].c;
            io.writeLine(res+"");
            return;
        }

        if(W*N<=10000000){
            res = calc(all, W);
            io.writeLine(res+"");
            return;
        }

        int k = W/(all[0].w-1);
        W%=all[0].w-1;

        sum = 0;
        Arrays.sort(all, (p1, p2)->p1.c<p2.c?-1:(p1.c>p2.c?1:0));
        for(int i = N;i>=0;i--) {
            all[i].w -= all[0].w - 1;
            sum += all[i].w;
            res += all[i].c;
        }

        if(sum<=W){
            io.writeLine(res+"");
            return;
        }

        res=  0;

        long[][] dp = new long[k+1][W+1];
        for (int q = 0; q < N; q++) {
            Piece p = all[q];
            for(int i = q+1;i>0;i--) {
            long[] wi = dp[i];
            long[] wi1 = dp[i - 1];
            for (int j = W; j > 0; j--) {
                wi[j] = Math.max(wi[j-1], wi1[j]);
                    if (p.w <= j) {
                        wi[j] = Math.max(wi[j], wi1[j - p.w] + p.c);
                    }
                }
            }
        }

        io.writeLine(dp[k][W] + "");
    }

    long calc(Piece[] nums, int W){
        long[] dp = new long[W+1];
        for(int j = 0;j<nums.length;j++){
            Piece p = nums[j];
            for(int i = W;i>=0;i--){
                if(p.w<=i)
                    dp[i] = Math.max(dp[i], dp[i-p.w] + p.c);
            }
        }
        return dp[W];
    }


    class Piece {
        public Piece(int c, int w) {
            this.c = c;
            this.w = w;
        }

        public int c;
        public int w;
    }

}

