import java.util.*;

public class Main {
	static class pair implements Comparable<pair> {
		public final long left;
		public final long right;

		public pair(long left, long right) {
			this.left = left;
			this.right = right;
		}

		public int compareTo(pair p) {
			if (right < p.right)
				return 1;
			else if (right > p.right)
				return -1;
			else {
				if(left > p.left)return 1;
				else if(left < p.left)return -1;
				else
				return 0;
			}
		}

	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), w = sc.nextInt();
		pair goods[] = new pair[n];
		pair goodsw[] = new pair[n];
		for (int i = 0; i < n; ++i) {
			goods[i] = new pair(sc.nextLong(), sc.nextLong());
			goodsw[i] = new pair(goods[i].right, goods[i].left);
		}
		Arrays.sort(goods);
		Arrays.sort(goodsw);
		int ans = 0, weight = 0, tmp = 0;
		for (int i = 0; i < n; ++i) {
			tmp = 0;
			weight = 0;
			for (int j = i; j < n; ++j) {
				if (weight + goods[j].left > w)
					continue;
				tmp += goods[j].right;
				weight += goods[j].left;
			}
			ans = Math.max(ans, tmp);
		}
		for(int i = n - 1; i >= 0; --i) {
			tmp = 0; weight = 0;
			for(int j = i; j >= 0; --j) {
				if (weight + goods[j].left > w)
					continue;
				tmp += goods[j].right;
				weight += goods[j].left;
			}
			ans = Math.max(ans,  tmp);
		}
		System.out.println(ans);
		sc.close();

	}

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	private static List<Mono> maxList = new ArrayList<>();
	public static void main(String[] args)  {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int w = scanner.nextInt();
		List<Mono> list = new ArrayList<>();
		for(int i = 0; i < n; i++){
			list.add(new Mono(scanner.nextInt(), scanner.nextInt()));
		}
		souatari(list, new ArrayList<>(), w);
		int total = 0;
		for(Mono mono : maxList){
			total += mono.value;
		}
		System.out.println(total);
	}


	private static void souatari(List<Mono> list, List<Mono> bag, int maxWeight){
		for(Mono mono: list){
			if(weightCheck(bag, mono, maxWeight)){
				List<Mono> list2 = new ArrayList<>(list);
				List<Mono> bag2  = new ArrayList<>(bag);
				list2.remove(mono);
				bag2.add(mono);
				souatari(list2, bag2, maxWeight);
			}
		}
		maxComp(bag);
	}

	private static boolean weightCheck(List<Mono> list, Mono mono, int maxWeight){
		int total = mono.getWeight();
		for(Mono m: list){
			total += m.getWeight();
		}
		return total <= maxWeight; 
	}
	private static void maxComp(List<Mono> list){
		int totalA = 0;
		for(Mono mono: list){
			totalA += mono.value;
		}
		int totalB = 0;
		for(Mono mono: maxList){
			totalB += mono.value;
		}
		if(totalA > totalB){
			maxList = list;
		}
	}

	private static class Mono{ 
		private int weight = 0;
		private int value  = 0;
		public Mono(int weight, int value) {
			this.weight = weight;
			this.value = value;
		}
		public int getWeight() {
			return weight;
		}
		public int getValue() {
			return value;
		}
		public void setWeight(int weight) {
			this.weight = weight;
		}
		public void setValue(int value) {
			this.value = value;
		}
		@Override
		public String toString() {
			// TODO Auto-generated method stub
			return this.weight + " " + this.value;
		}

	}
}

