    //私が好きなアルゴリズム：：累積和・UF木
    //PriorityQueueは拡張for文で出すとsortされてない順番で出てくるよ
    //longのbit演算は1L<<posに注意

	public static void main(String[] args) throws Exception {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

	    int n = sc.nexI();
	    long Wmax = sc.nexL();

	    List<List<Integer>> dt = new ArrayList<>();
	    for(int i=0; i<4; i++){
	        dt.add(new ArrayList<Integer>());
	    }

	    long wmin = sc.nexL();
	    dt.get(0).add(sc.nexI());
	    for(int i=1; i<n; i++){
	        long w1 = sc.nexL();
	        dt.get((int)(w1-wmin)).add(sc.nexI());
	    }

	    int[] sz = new int[4];

	    for(int i=0; i<4; i++){
	        sz[i] = dt.get(i).size();

            Collections.sort(dt.get(i));
            dt.get(i).add(0);
            Collections.reverse(dt.get(i));

	        for(int j=1; j<=sz[i]; j++){
	            dt.get(i).set(j, dt.get(i).get(j-1)+dt.get(i).get(j));
	        }
	        //disp_list(dt.get(i));
	    }

        long[] walls = new long[4];
	    for(int i=0; i<4; i++){
	        walls[i] = (wmin+i)*sz[i];
	    }
        long[] valalls = new long[4];
	    for(int i=0; i<4; i++){
	        valalls[i] = dt.get(i).get(sz[i]);
	    }

	    if(sumA(walls)>Wmax){
	        long ans =0;
	        for(int i1=0; i1<=sz[0]; i1++){
	            long w1 = wmin*i1;
	            if(w1>Wmax) break;
	            if((w1+walls[1]+walls[2]+walls[3]) <= Wmax){
	                ans = max(ans, dt.get(0).get(i1)+valalls[1]+valalls[2]+valalls[3]);
	                continue;
	            }

    	        for(int i2=0; i2<=sz[1]; i2++){
    	            long w2 = (wmin+1)*i2;
    	            w2 += w1;
    	            if(w2>Wmax) break;
    	            if((w2+walls[2]+walls[3]) <= Wmax){
    	                ans = max(ans, dt.get(0).get(i1)+dt.get(1).get(i2)+valalls[2]+valalls[3]);
    	                continue;
    	            }

	                for(int i3=0; i3<=sz[2]; i3++){
	                    long w3 = (wmin+2)*i3;
	                    w3 += w2;
	                    if(w3>Wmax) break;
	                    if((w3+walls[3]) <= Wmax){
	                        ans = max(ans, dt.get(0).get(i1)+dt.get(1).get(i2)+dt.get(2).get(i3)+valalls[3]);
        	                continue;
        	            }

	                    for(int i4=0; i4<=sz[3]; i4++){
	                        long w4 = (wmin+3)*i4;
	                        w4 += w3;
	                        if(w4>Wmax) break;
	                        ans = max(ans, dt.get(0).get(i1)+dt.get(1).get(i2)+dt.get(2).get(i3)+dt.get(3).get(i4));
	                    }
	                }
    	        }
	        }
	        out.println(ans);
	    }else{
	        out.println(sumA(valalls));
	    }

	    //out.println(ans);
	    out.flush();
	}


