public class Main {

	void run() {
		try (Scanner sc = new Scanner(System.in)) {
			int n = sc.nextInt();
			int w = sc.nextInt();
			int[][] v = new int[n][2];
			for(int i=0;i<n;i++) {
				v[i][0] = sc.nextInt();
				v[i][1] = sc.nextInt();
			}

			Arrays.sort(v, new Comparator<int[]>(){
				public int compare(int[] o1, int[] o2) {
					double x1 = (double)o1[1]/o1[0];
