	 */

	int N, W;
	int[] weight;
	int[] value;

	Integer[][] memo;

	void input() {

		N = ni();
		W = ni();

		weight = new int[N];
		value  = new int[N];

		for (int i = 0; i < N; i ++) {
			weight[i] = ni();
			value[i]  = ni();
		}

		memo = new Integer[N + 1][W + 1];


	}

	int dfs(int i, int w) {


		int res = 0;

		if (i == N) {
			res = 0;
		}

		else if (memo[i][w] != null) {
			return memo[i][w];
		}

		else if (w > W - weight[i]) {

			res = dfs(i + 1, w);
		} else {

			int r1 = dfs(i + 1, w);
			int r2 = dfs(i + 1, w + weight[i]) + value[i];

			res = Math.max(r1, r2);
		}

		memo[i][w] = res;
		return res;		
	}	
}

