							while (0 < k && m < k) {
								tmpW += list[2].get(m).w;
								tmpV += list[2].get(m).v;
								m++;
							}

							m = 0;
							while (0 < l && m < l) {
								tmpW += list[3].get(m).w;
								tmpV += list[3].get(l).v;
								m++;
							}

							if (tmpW <= W) {
