                            dp[(i + 1) & 1][j + 1][k] = dp[i & 1][j][k - w[i]] + v[i];
                        } else {
                            if(dp[(i + 1) & 1][j][k] < dp[i&1][j][k]) dp[(i + 1) & 1][j][k] = dp[i & 1][j][k];
                        }
                    } else {
                        if(dp[(i + 1) & 1][j][k] < dp[i&1][j][k]) dp[(i + 1) & 1][j][k] = dp[i & 1][j][k];
                    }
                }
            }
        }
        long ans = 0;
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= N; j++) {
                for (int k = 0; k <= M; k++) {
                    if (dp[i][j][k] > ans && (long) j * base + k <= W) {
                        ans = Math.max(ans, dp[i][j][k]);
                    }
                }
            }
        }
        System.out.println(ans);
    }

