    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var W = RLong;

            List<long>[] vs = new List<long>[4].Select(x => new List<long>()).ToArray();
            long[] w = new long[N];
            long[] v = new long[N];
            for (int i = 0; i < N; i++)
            {
                w[i] = RInt;
                v[i] = RInt;
                vs[w[i] - w[0]].Add(v[i]);
            }

            for (int i = 0; i < 4; i++)
            {
                vs[i] = vs[i].OrderByDescending(x => x).ToList();
            }

            long ans = 0;
            for (int i = 0; i <= vs[0].Count; i++)
            {
                long v0 = vs[0].Take(i).Sum();
                long w0 = w[0] * i;
                for (int j = 0; j <= vs[1].Count; j++)
                {
                    long v1 = vs[1].Take(j).Sum();
                    long w1 = (w[0] + 1) * j;
                    for (int k = 0; k <= vs[2].Count; k++)
                    {
                        long v2 = vs[2].Take(k).Sum();
                        long w2 = (w[0] + 2) * k;
                        for (int l = 0; l <= vs[3].Count; l++)
                        {
                            long v3 = vs[3].Take(l).Sum();
                            long w3 = (w[0] + 3) * l;

                            long wSum = w0 + w1 + w2 + w3;
                            if (wSum > W) continue;

                            long cand = v0 + v1 + v2 + v3;
                            ans = Math.Max(ans, cand);
                        }
                    }
                }
            }

            Console.WriteLine(ans);
        }


    }


