            var wAry = new int[N];
            var vAry = new int[N];
            var firstW = NextInt;
            wAry[0] = 1;
            vAry[0] = NextInt;
            for (int i = 1; i < N; ++i)
            {
                wAry[i] = NextInt - firstW + 1;
                vAry[i] = NextInt;
            }
            var dp = new ulong[N + 1][];
            var dpc = new int[N + 1][];
            for (int i = 0; i <= N; ++i)
            {
                dp[i] = new ulong[wAry.Sum() + 1];
                dpc[i] = new int[wAry.Sum() + 1];
            }
            var sumW = 0;
            for (int i = 1; i <= N; ++i)
            {
                var w = wAry[i - 1];
                var v = (ulong)vAry[i - 1];
                sumW += w;
                for (int j = 0; j <= sumW; ++j)
                {
                    if (j >= w)
                    {
                        if (dp[i - 1][j] > dp[i - 1][j - w] + v)
                        {
                            dp[i][j] = dp[i - 1][j];
                            dpc[i][j] = dpc[i - 1][j];
                        }
                        else
                        {
                            dp[i][j] = dp[i - 1][j - w] + v;
                            dpc[i][j] = dpc[i - 1][j - w] + 1;
                        }
                    }
                    else
                    {
                        dp[i][j] = dp[i - 1][j];
                        dpc[i][j] = dpc[i - 1][j];
                    }
                }
            }

            var ans = (ulong)0;
            for (int i = 1; i <= N; ++i)
            {
                for (int j = 0; j <= sumW; ++j)
                {
