namespace AtCoderProject
{
    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var W = consoleReader.Int;

            var goods = consoleReader.Repeat(N).Select(cr => new Goods { weight = cr.Int, value = cr.Int }).ToArray();
            long weight1 = goods[0].weight;

            var values = Enumerable.Repeat(Array.Empty<int>(), 4).ToArray();

            foreach (var g in goods.GroupBy(g => g.weight - weight1, g => g.value))
            {
                values[g.Key] = g.OrderByDescending(i => i).ToArray();
            }


            var sums = new int[4][];
            for (int i = 0; i < 4; i++)
            {
                sums[i] = new int[values[i].Length + 1];
                for (int j = 0; j < values[i].Length; j++)
                    sums[i][j + 1] = sums[i][j] + values[i][j];
            }

            long max = 0;
            for (int w0 = 0; w0 < sums[0].Length; w0++)
                for (int w1 = 0; w1 < sums[1].Length; w1++)
                    for (int w2 = 0; w2 < sums[2].Length; w2++)
                    {
                        long weightSum = weight1 * (w0 + w1 + w2) + w1 + 2 * w2;
                        if (weightSum > W) continue;
                        int w3 = Math.Min((int)((W - weightSum) / (weight1 + 3)), values[3].Length);
                        max = Math.Max(max, +sums[0][w0] + sums[1][w1] + sums[2][w2] + sums[3][w3]);
                    }
            return max;
        }
        struct Goods
        {
            public int weight;
            public int value;
        }

        #region いつもの
#pragma warning disable
        private ConsoleReader consoleReader;
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc()); static string AllLines<T>(IEnumerable<T> source) => string.Join("\n", source);
    }
    static class Ext
    {
        public static Dictionary<TKey, int> GroupCount<TSource, TKey>(this IEnumerable<TSource> source, Func<TSource, TKey> keySelector) => source.GroupBy(keySelector).ToDictionary(g => g.Key, g => g.Count());
