        Cap = sc.ReadInt();
        W = new long[N];
        V = new long[N];
        for (int i = 0; i < N; i++)
        {
            var w = sc.ReadLong();
            var v = sc.ReadLong();
            W[i] = w;
            V[i] = v;
        }

        var ans = Rec(0, Cap);
        Console.WriteLine(ans);
    }
    static Dictionary<Tuple<int, long>, long> Memo = new Dictionary<Tuple<int, long>, long>();
    static long Rec(int n, long rem)
    {
        if (n == N) return 0;

        var key = Tuple.Create(n, rem);
        if (Memo.ContainsKey(key)) return Memo[key];

        long res1 = 0, res2 = 0;
        if (rem >= W[n]) res1 = Rec(n + 1, rem - W[n]) + V[n];
        res2 = Rec(n + 1, rem);

        var res = Math.Max(res1, res2);
        Memo[key] = res;
        return res;
    }

    static int N, Cap;
    static long[] W, V;
    static Scanner sc = new Scanner();
}
