                int[] input = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                values[input[0] - weight].Add(input[1]);
            }
            for (int i = 0; i < 4; i++) {
                values[i].Sort();
                values[i].Reverse();
            }
            List<long>[] valuesums = new List<long>[4];
