            for (int i = 0; i < Math.Min(valuesums[0].Count, div + 1); i++) {
                for (int j = 0; j < Math.Min(valuesums[1].Count, div + 1); j++) {
                    for (int k = 0; k < Math.Min(valuesums[2].Count, div + 1); k++) {
