                    break;
                }
                long sum3 = sum2;
                long nw3 = nw2;
                for(int k=0;k<=V[2].Length;k++){
                    if(nw3 > W){
                        break;
                    }
                    long sum4 = sum3;
                    long nw4 = nw3;
                    for(int l=0;l<=V[3].Length;l++){
                        if(nw4 > W){
                            break;
                        }
                        count = Math.Max(count,sum4);
                        if(l != V[3].Length){
                            sum4 += V[3][l];
                            nw4 += w1+3;
                        }
                    }
                    if(k != V[2].Length){
                        sum3 += V[2][k];
                        nw3 += w1+2;
                    }
                }
                if(j != V[1].Length){
                    sum2 += V[1][j];
                    nw2 += w1+1;
                }
            }
            if(i != V[0].Length){
                sum1 += V[0][i];
                nw1 += w1;
            }
        }
        sb.Append(count+"\n");
    }
}

using System;
