namespace AtCorders
{
	public class Program
	{
		static void Main(string[] args)
		{
			var nw = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nw[0];
			int w = nw[1];
			var knups = new Knup[n];
			for (int i = 0; i < n; i++) {
				var temp = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				knups[i] = new Knup { W = temp[0], V = temp[1] };
			}

			int w0 = knups[0].W;
			var c = new int[4];
			for (int i = 0; i < n; i++) {
				c[knups[i].W - w0]++;
			}

			for (int i = 0; i < 4; i++) {
				c[i]++;
			}

			var dp = new int[c[0], c[1], c[2], c[3]];
			for (int i = 0; i < n; i++) {
				int wi = knups[i].W - w0;

				var dst = new int[c[0], c[1], c[2], c[3]];
				for (int j0 = 0; j0 < c[0]; j0++) {
					for (int j1 = 0; j1 < c[1]; j1++) {
						for (int j2 = 0; j2 < c[2]; j2++) {
							for (int j3 = 0; j3 < c[3]; j3++) {
								if (dp[j0, j1, j2, j3] == 0) {
									continue;
								}

								dst[j0, j1, j2, j3] = Math.Max(
									dst[j0, j1, j2, j3],
									dp[j0, j1, j2, j3]);
								switch (wi) {
									case 0:
										dst[j0 + 1, j1, j2, j3] = Math.Max(
											dst[j0 + 1, j1, j2, j3],
											dp[j0, j1, j2, j3] + knups[i].V);
										break;
									case 1:
										dst[j0, j1 + 1, j2, j3] = Math.Max(
											dst[j0, j1 + 1, j2, j3],
											dp[j0, j1, j2, j3] + knups[i].V);
										break;
									case 2:
										dst[j0, j1, j2 + 1, j3] = Math.Max(
											dst[j0, j1, j2 + 1, j3],
											dp[j0, j1, j2, j3] + knups[i].V);
										break;
									case 3:
										dst[j0, j1, j2, j3 + 1] = Math.Max(
											dst[j0, j1, j2, j3 + 1],
											dp[j0, j1, j2, j3] + knups[i].V);
										break;
								}
							}
						}
					}
				}

				switch (wi) {
					case 0:
						dst[1, 0, 0, 0] = Math.Max(
							dst[1, 0, 0, 0],
							knups[i].V);
						break;
					case 1:
						dst[0, 1, 0, 0] = Math.Max(
							dst[0, 1, 0, 0],
							knups[i].V);
						break;
					case 2:
						dst[0, 0, 1, 0] = Math.Max(
							dst[0, 0, 1, 0],
							knups[i].V);
						break;
					case 3:
						dst[0, 0, 0, 1] = Math.Max(
							dst[0, 0, 0, 1],
							knups[i].V);
						break;
				}

				dp = dst;
			}

			int ans = 0;
			for (int j0 = 0; j0 < c[0]; j0++) {
				for (int j1 = 0; j1 < c[1]; j1++) {
					for (int j2 = 0; j2 < c[2]; j2++) {
						for (int j3 = 0; j3 < c[3]; j3++) {
							long weight = (long)w0 * j0
								+ (long)(w0 + 1) * j1
								+ (long)(w0 + 2) * j2
								+ (long)(w0 + 3) * j3;
							if (weight <= w) {
								ans = Math.Max(ans, dp[j0, j1, j2, j3]);
							}
						}
					}
				}
			}

			Console.WriteLine(ans);
		}

		struct Knup
		{
			public int W { get; set; }
			public int V { get; set; }
		}
	}
}

