		public class Calc {
			public void Solve() {
				int N = NextInt(), W = NextInt();
				var dp = Enumerable.Repeat(0, N+1).Select(i => new Map<long, long>()).ToArray(); // dp[i][j]=i個から重さjになるように選んだ価値の最大値

				dp[0][0] = 0;

