        //    var one = K < N ? Solve(W, K, N - 1): 0;
        //    var two = (W >= w[N - 1])? (v[N - 1] + Solve(W - w[N - 1], K - 1, N - 1)): 0;
        //    dim[N][K][W] = Math.Max(one, two) + 1;
        //    return dim[N][K][W] - 1;
        //}

        public void Do()
        {
            const int DELTA = 10;
            int N = reader.ReadInt();
            int W = reader.ReadInt();
            long[][][] dim = new long[N + 1][][];
            int[] w = new int[N];
            int[] v = new int[N];
            var w0 = int.MaxValue;
            for (int i = 0; i < N; ++i)
            {
                w[i] = reader.ReadInt();
                v[i] = reader.ReadInt();
                w0 = Math.Min(w0, w[i]);
            }
            for (int i = 0; i <= N; ++i)
            {
                dim[i] = new long[N + 1][];
                for (int j = 0; j <= N; ++j)
                    dim[i][j] = new long[DELTA * N + 1];
            }
            --w0;
            for (int i = 0; i < N; ++i)
                w[i] -= w0;
            for (int i = 1; i <= N; ++i)
                for (int j = 1; j <= i; ++j)
                    for (int k = 0; k <= DELTA * N; ++k)
                    {
                        if (k > 0)
                            dim[i][j][k] = dim[i][j][k - 1];
                        if (k - w[i - 1] >= 0 && dim[i][j][k] < v[i - 1] + dim[i - 1][j - 1][k - w[i - 1]])
                            dim[i][j][k] = v[i - 1] + dim[i - 1][j - 1][k - w[i - 1]];
                        if (i > j && dim[i][j][k] < dim[i - 1][j][k])
                            dim[i][j][k] = dim[i - 1][j][k];                        
                    }            
            long total = 0;
            for (int ii = 1; ii <= N; ++ii)
            {
                var WW = W - ii * w0;
                if (WW >= 0)
                {
                    WW = Math.Min(WW, DELTA * ii);
                    total = Math.Max(total, dim[N][ii][WW]);
                }
            }
            writer.WriteLine(total);
        }
    }
}

