namespace CodeChallenges
{
    using CodeChallenges.Boilerplate.IO;

    public class Solver
    {
        private readonly StreamReader reader;
        private readonly StreamWriter writer;

        public Solver(StreamReader reader, StreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }

        public int WW;
        public int[][][] dim = new int[101][][];

        public int Solve(int DEL, int K, int N, int[] v, int[] w)
        {
            if (K == 0)
                return 0;
            if (dim[N][K][DEL] != -1)
                return dim[N][K][DEL];
            var one = K < N ? Solve(DEL, K, N - 1, v, w): 0;
            var two = WW >= DEL + w[N - 1]? v[N - 1] + Solve(DEL + w[N - 1], K - 1, N - 1, v, w): 0;
            return dim[N][K][DEL] = Math.Max(one, two);
        }

        public void Do()
        {
            var N = reader.ReadInt();
            var W = reader.ReadInt();
            var w = new int[N];
            var v = new int[N];
            for (int i = 0; i < N; ++i)
            {
                w[i] = reader.ReadInt();
                v[i] = reader.ReadInt();
            }
            for (int i = 0; i <= N; ++i)
            {
                dim[i] = new int[101][];
                for (int j = 0; j <= N; ++j)
                {
                    dim[i][j] = new int[301];
                    for (int k = 0; k < 301; ++k)
                        dim[i][j][k] = -1;
                }
            }
            var w0 = w[0];
            for (int i = 0; i < N; ++i)
                w[i] -= w0;

            int total = 0;
            for (int ii = 1; ii <= N; ++ii)
            {
                WW = W - ii * w0;
                if (WW >= 0)
                {
                    for (int i = 0; i <= N; ++i)
                        for (int j = 0; j <= N; ++j)
                            for (int k = 0; k < 301; ++k)
                                dim[i][j][k] = -1;
                    total = Math.Max(total, Solve(0, ii, N, v, w));
                }
            }
            writer.WriteLine(total);
        }
    }
}

