        public static void Solve(Input input)
        {
            var n = input.NextInt();
            var wsize = input.NextInt();

            var w = new int[n];
            var v = new int[n];
            for (int i = 0; i < n; i++)
            {
                w[i] = input.NextInt();
                v[i] = input.NextInt();
            }

            var map = new Dictionary<int, List<int>>();
            for (int i = 0; i < n; i++)
            {
                if (!map.ContainsKey(w[i]))
                {
                    map.Add(w[i], new List<int>());
                }

                map[w[i]].Add(v[i]);
            }

            var items = new List<long[]>();
            foreach (var k in map.Keys)
            {
                items.Add(map[k]
                    .Select(x => (long)x)
                    .OrderByDescending(x => x).ToArray());
            }

            var keys = map.Keys.Select(x => (long)x).ToArray();
            var max = 0L;
            for (int i = 0; i <= items[0].Length; i++)
            {
                var imax = items[0].Take(i).Sum();
                if (i * keys[0] > wsize) continue;
                if (items.Count == 1)
                {

                    max = Math.Max(max, imax);
                    continue;
                }
                for (int j = 0; j <= items[1].Length; j++)
                {
                    var jmax = items[1].Take(j).Sum();
                    if (i * keys[0] + j * keys[1] > wsize) continue;
                    if (items.Count == 2)
                    {
                        max = Math.Max(max, imax + jmax);
                        continue;
                    }
                    for (int k = 0; k <= items[2].Length; k++)
                    {
                        var kmax = items[2].Take(k).Sum();
                        if (i * keys[0] + j * keys[1] + k * keys[2] > wsize) continue;
                        if (items.Count == 3)
                        {
                            max = Math.Max(max, imax + jmax + kmax);
                            continue;
                        }
                        for (int l = 0; l <= items[3].Length; l++)
                        {
                            var lmax = items[3].Take(l).Sum();
                            if (i * keys[0] + j * keys[1] + k * keys[2] + l * keys[3] > wsize) continue;
                            max = Math.Max(max, imax + jmax + kmax + lmax);

                        }
                    }
                }
            }

            Console.WriteLine(max);
        }

