    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadIntMatrix(n);

        long v = a[0][0];
        var b = Init<List<int>>(4);
        for (int i = 0; i < n; i++)
            b[a[i][0] - v].Add(a[i][1]);

        var sb = new long[4][];
        for (int i = 0; i < 4; i++)
        {
            b[i].Sort();
            b[i].Reverse();
            sb[i] = new long[b[i].Count + 1];
            for (int j = 0; j < b[i].Count; j++)
                sb[i][j + 1] = sb[i][j] + b[i][j];
        }

        long ans = 0;
        for (int i = 0; i <= b[0].Count; i++)
            for (int j = 0; j <= b[1].Count; j++)
                for (int k = 0; k <= b[2].Count; k++)
                {
                    long w = v * i + (v + 1) * j + (v + 2) * k;
                    if (w > m)
                        continue;
                    int l = (int)Math.Min(b[3].Count, (m - w) / (v + 3));
                    ans = Math.Max(ans, sb[0][i] + sb[1][j] + sb[2][k] + sb[3][l]);
                }

        Write(ans);
