class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var W = sc.ReadLong();
        var WV = sc.ReadTupLongArray(N);
        var awv = WV.GroupBy(wv => wv.Item1).ToArray();
        var sums = new long[4, 101];
        for (int i = 0; i < 4; i++)
        {
            if (i >= awv.Length) continue;
            var glist = awv[i].ToList().OrderByDescending(wv => wv.Item2).ToList();
            for (int j = 0; j < glist.Count(); j++)
            {
                sums[i, j + 1] = sums[i, j] + glist[j].Item2;
            }
        }

        var ans = 0L;
        for (int i = 0; i <= awv[0].Count(); i++)
        {
            var res = 0L;
            var rem = W;
            rem -= i * (awv[0].First().Item1);
            res += sums[0, i];
            if (rem < 0) break;
            ans = Math.Max(ans, res);
            if (awv.Length == 1) continue;
            for (int j = 0; j <= awv[1].Count(); j++)
            {
                var rem2 = rem - j * (awv[1].First().Item1);
                var res2 = res + sums[1, j];
                if (rem2 < 0) break;
                ans = Math.Max(ans, res2);
                if (awv.Length == 2) continue;
                for (int k = 0; k <= awv[2].Count(); k++)
                {
                    var rem3 = rem2 - k * (awv[2].First().Item1);
                    var res3 = res2 + sums[2, k];
                    if (rem3 < 0) break;
                    ans = Math.Max(ans, res3);
                    if (awv.Length == 3) continue;
                    for (int l = 0; l <= awv[3].Count(); l++)
                    {
                        var rem4 = rem3 - l * (awv[3].First().Item1);
                        var res4 = res3 + sums[3, l];
                        if (res4 < 0) break;
                        ans = Math.Max(ans, res4);
                    }
                }
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
