namespace CodeChallenges
{
    using CodeChallenges.Boilerplate.IO;

    public class Solver
    {
        private readonly StreamReader reader;
        private readonly StreamWriter writer;

        public Solver(StreamReader reader, StreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }

        public int[][][] dim = new int[101][][];

        public int Solve(int W, int DEL, int K, int N, int[] v, int[] w)
        {
            if (K == 0)
                return 0;
            if (dim[N][K][DEL] > 0)
                return dim[N][K][DEL] - 1;
            var one = K < N ? Solve(W, DEL, K, N - 1, v, w): 0;
            var two = (W >= DEL + w[N - 1])? (v[N - 1] + Solve(W, DEL + w[N - 1], K - 1, N - 1, v, w)): 0;
            dim[N][K][DEL] = Math.Max(one, two) + 1;
            return dim[N][K][DEL] - 1;
        }

        public void Do()
        {
            var N = reader.ReadInt();
            var W = reader.ReadInt();
            var w = new int[N];
            var v = new int[N];
            for (int i = 0; i < N; ++i)
            {
                w[i] = reader.ReadInt();
                v[i] = reader.ReadInt();
            }
            for (int i = 0; i < 101; ++i)
            {
                dim[i] = new int[101][];
                for (int j = 0; j < 101; ++j)
                    dim[i][j] = new int[301];
            }
            var w0 = w[0];
            for (int i = 0; i < N; ++i)
                w[i] -= w0;

            int total = 0;
            for (int ii = 1; ii <= N; ++ii)
            {
                var WW = W - ii * w0;
                if (WW >= 0)
                {
                    for (int i = 0; i < 101; ++i)
                        for (int j = 0; j < 101; ++j)
                            Array.Clear(dim[i][j], 0, 301);                            
                    total = Math.Max(total, Solve(WW, 0, ii, N, v, w));
                }
            }
            writer.WriteLine(total);
        }
    }
}

