class Program
{
    static void Main()
    {
        //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().Solve();
        Out.Flush();
    }
    Scanner cin = new Scanner();
    Random rnd = new Random();
    Stopwatch sw = new Stopwatch();
    readonly int[] dd = { 0, 1, 0, -1, 0 };
    readonly int mod = 1000000007;
    readonly string alfa = "abcdefghijklmnopqrstuvwxyz";

    int N, W;
    long we = 0;
    long ans = 0;
    void Solve()
    {
        N = cin.Nextint;
        W = cin.Nextint;
        var w = new int[N];
        var v = new int[N];
        for (int i = 0; i < N; i++)
        {
            w[i] = cin.Nextint;
            v[i] = cin.Nextint;
        }
        int w1 = w[0];
        var A = new List<int>();
        var B = new List<int>();
        var C = new List<int>();
        var D = new List<int>();
        for (int i = 0; i < N; i++)
        {
            if (w[i] == w1) A.Add(v[i]);
            else if (w[i] == w1 + 1) B.Add(v[i]);
            else if (w[i] == w1 + 2) C.Add(v[i]);
            else if (w[i] == w1 + 3) D.Add(v[i]);
        }
        A = A.OrderByDescending(i => i).ToList();
        B = B.OrderByDescending(i => i).ToList();
        C = C.OrderByDescending(i => i).ToList();
        D = D.OrderByDescending(i => i).ToList();

        long a = 0, b = 0, c = 0, d = 0;
        while (true)
        {
            a = Counter(A, w1);
            b = Counter(B, w1 + 1);
            c = Counter(C, w1 + 2);
            d = Counter(D, w1 + 3);
            if (a == 0 && b == 0 && c == 0 && d == 0) break;
            if (a >= b && a >= c && a >= d)
            {
                ans += A[0];
                A.RemoveAt(0);
                we += w1;
            }
            else if(b >= a && b >= c && b >= d)
            {
                ans += B[0];
                B.RemoveAt(0);
                we += w1 + 1;
            }
            else if (c >= a && c >= b && c >= d)
            {
                ans += C[0];
                C.RemoveAt(0);
                we += w1 + 2;
            }
            else
            {
                ans += D[0];
                D.RemoveAt(0);
                we += w1 + 3;
            }

        }
        WriteLine(ans);
    }
    long Counter(List<int> L, int weight)
    {
        int cnt = 0;
        long box = (W - we) / weight;
        if (box <= 0) return 0;
        long a = 0;
        for (int j = 0; j < L.Count; j++)
        {
            if (cnt == box) break;
            a += L[j];
            cnt++;
        }
        return a;
    }

}

