namespace CodeChallenges
{
    using CodeChallenges.Boilerplate.IO;

    public class Solver
    {
        private readonly StreamReader reader;
        private readonly StreamWriter writer;

        public Solver(StreamReader reader, StreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }

        public int[][][] dim = new int[101][][];
        public int[] w = new int[101];
        public int[] v = new int[101];

        public int Solve(int W, int K, int N)
        {
            if (K == 0)
                return 0;
            if (dim[N][K][W] > 0)
                return dim[N][K][W] - 1;
            var one = K < N ? Solve(W, K, N - 1): 0;
            var two = (W >= w[N - 1])? (v[N - 1] + Solve(W - w[N - 1], K - 1, N - 1)): 0;
            dim[N][K][W] = Math.Max(one, two) + 1;
            return dim[N][K][W] - 1;
        }

        public void Do()
        {
            var N = reader.ReadInt();
            var W = reader.ReadInt();
            for (int i = 0; i < N; ++i)
            {
                w[i] = reader.ReadInt();
                v[i] = reader.ReadInt();
            }
            for (int i = 0; i < 101; ++i)
            {
                dim[i] = new int[101][];
                for (int j = 0; j < 101; ++j)
                    dim[i][j] = new int[301];
            }
            var w0 = w[0];
            for (int i = 0; i < N; ++i)
                w[i] -= w0;

            int total = 0;
            for (int ii = 1; ii <= N; ++ii)
            {
                var WW = W - ii * w0;
                if (WW >= 0)
                {
                    WW = Math.Min(WW, 3 * ii);
                    for (int i = 0; i < 101; ++i)
                        for (int j = 0; j < 101; ++j)
                            Array.Clear(dim[i][j], 0, 301);                            
                    total = Math.Max(total, Solve(WW, ii, N));
                }
            }
            writer.WriteLine(total);
        }
    }
}

