        public void Do()
        {
            const int DELTA = 3;
            int N = reader.ReadInt();
            int W = reader.ReadInt();
            int[][][] dim = new int[N + 1][][];
            int[] w = new int[N];
            int[] v = new int[N];
            for (int i = 0; i < N; ++i)
            {
                w[i] = reader.ReadInt();
                v[i] = reader.ReadInt();
            }
            var w0 = w[0];
            for (int i = 0; i <= N; ++i)
            {
                dim[i] = new int[N + 1][];
                for (int j = 0; j <= N; ++j)
                {
                    dim[i][j] = new int[DELTA * N + 1];
                    for (int k = 0; k <= DELTA * N; ++k)
                        dim[i][j][k] = int.MinValue;
                }
            }            
            for (int i = 0; i <= N; ++i)
            {
                for (int k = 0; k <= DELTA * N; ++k)
                    dim[i][0][k] = 0;
                if (i > 0)
                    w[i - 1] -= w0;
                for (int j = 1; j <= i; ++j)
                    for (int k = 0; k <= DELTA * N; ++k)
                    {
                        if (k >= w[i - 1])
                            dim[i][j][k] = Math.Max(dim[i][j][k], v[i - 1] + dim[i - 1][j - 1][k - w[i - 1]]);
                        if (i > j)
                            dim[i][j][k] = Math.Max(dim[i][j][k], dim[i - 1][j][k]);
                    }
            }
            int total = int.MinValue;
            for (int ii = 1; ii <= N; ++ii)
                for (int j = Math.Min(W - ii * w0, ii * DELTA);j >= 0 ; --j)
