	    int ww = tmp[0], vv = tmp[1];

	    if      (ww == w1 + 0) vs0[nw0++] = vv;
	    else if (ww == w1 + 1) vs1[nw1++] = vv;
	    else if (ww == w1 + 2) vs2[nw2++] = vv;
	    else                   vs3[nw3++] = vv; 
	}

	Array.Resize(ref vs0, nw0); 
	Array.Resize(ref vs1, nw1);
	Array.Resize(ref vs2, nw2);
	Array.Resize(ref vs3, nw3);

	Array.Sort(vs0); Array.Reverse(vs0);
	Array.Sort(vs1); Array.Reverse(vs1);
	Array.Sort(vs2); Array.Reverse(vs2);
	Array.Sort(vs3); Array.Reverse(vs3);

	for (int i = 1; i < vs0.Length; i++){ vs0[i] += vs0[i-1]; }
	for (int i = 1; i < vs1.Length; i++){ vs1[i] += vs1[i-1]; }
	for (int i = 1; i < vs2.Length; i++){ vs2[i] += vs2[i-1]; }
	for (int i = 1; i < vs3.Length; i++){ vs3[i] += vs3[i-1]; }

	long ans = 0;

	for (int i = 0; i <= Math.Min(n, vs0.Length); i++)
	{
	    for (int j = 0; j <= Math.Min(n - i, vs1.Length); j++)
	    {
		for (int k = 0; k <= Math.Min(n - i - j, vs2.Length); k++)
		{
		    for (int l = 0; l <= Math.Min(n - i - j - k, vs3.Length); l++)
		    {
			long weight =
			    w1 * i + (w1+1)*j + (w1+2)*k + (w1+3)*l;
			if (weight <= w)
			{
			    long value = 0;
			    if (i > 0) value += vs0[i-1];
			    if (j > 0) value += vs1[j-1];
			    if (k > 0) value += vs2[k-1];
			    if (l > 0) value += vs3[l-1];
			    ans = Math.Max(ans, value);
			}
		    }
		}
	    }
	}

	WriteLine(ans);
    }
}

