            var dp = new ulong[N + 1][];
            var dpc = new int[N + 1][];
            var maxW = wAry.Sum();
            for (int i = 0; i <= N; ++i)
            {
                dp[i] = new ulong[maxW + 1];
                dpc[i] = new int[maxW + 1];
            }
