                for (int j = 0; j <= maxW; ++j)
                {
                    if (j >= w)
                    {
                        if (dp[i - 1][j] >= dp[i - 1][j - w] + v)
                        {
                            dp[i][j] = dp[i - 1][j];
                            dpc[i][j] = dpc[i - 1][j];
                        }
                        else
                        {
                            dp[i][j] = dp[i - 1][j - w] + v;
                            dpc[i][j] = dpc[i - 1][j - w] + 1;
                        }
                    }
