	static class Program
	{
		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var wAll = cin.ReadLong();
			var (w, v) = cin.ReadValueArray<int, long>(n);
			var wList = new List<List<long>>();
			for (int i = 0; i < 4; i++)
			{
				wList.Add(new List<long>());
			}
			for (int i = 0; i < n; i++)
			{
				wList[w[i] - w[0]].Add(v[i]);
			}
			for (int i = 0; i < 4; i++)
			{
				wList[i].Sort();
				wList[i].Reverse();
			}

			var sum = new List<List<long>>();
			for (int i = 0; i < 4; i++)
			{
				sum.Add(new List<long>());
				sum[i].Add(0);
				for (int j = 0; j < wList[i].Count; j++)
				{
					sum[i].Add(sum[i][j] + wList[i][j]);
				}
			}

			var ans = 0L;
			for (int i = 0; i <= wList[0].Count; i++)
			{
				for (int j = 0; j <= wList[1].Count; j++)
				{
					for (int k = 0; k <= wList[2].Count; k++)
					{
						var wSum = w[0] * (i + j + k) + j + 2 * k;
						var wLeft = wAll - wSum;
						if (wLeft < 0) continue;
						var avail = (int)Math.Min(n - i - j - k, wLeft / (w[0] + 3));
						var val = sum[0][i] + sum[1][j] + sum[2][k] + sum[3][Math.Min(wList[3].Count, avail)];
						Chmax(ref ans, val);
					}
				}
			}
			Console.WriteLine(ans);
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);
			var cin = new Scanner();
			Solve(cin);
			Console.Out.Flush();
		}

