namespace CodeChallenges
{
    using CodeChallenges.Boilerplate.IO;

    public class Solver
    {
        private readonly StreamReader reader;
        private readonly StreamWriter writer;

        public Solver(StreamReader reader, StreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }        

        //public int Solve(int W, int K, int N)
        //{
        //    if (K == 0)
        //        return 0;
        //    if (dim[N][K][W] > 0)
        //        return dim[N][K][W] - 1;
        //    var one = K < N ? Solve(W, K, N - 1): 0;
        //    var two = (W >= w[N - 1])? (v[N - 1] + Solve(W - w[N - 1], K - 1, N - 1)): 0;
        //    dim[N][K][W] = Math.Max(one, two) + 1;
        //    return dim[N][K][W] - 1;
        //}

        public void Do()
        {
            const int DELTA = 3;
            int N = reader.ReadInt();
            int W = reader.ReadInt();
            int[][][] dim = new int[N + 1][][];
            int[] w = new int[N];
            int[] v = new int[N];            
            for (int i = 0; i < N; ++i)
            {
                w[i] = reader.ReadInt();
                v[i] = reader.ReadInt();
            }
            var w0 = w[0];
            for (int i = 0; i <= N; ++i)
            {
                dim[i] = new int[N + 1][];
                for (int j = 0; j <= N; ++j)
                    dim[i][j] = new int[DELTA * N + 1];
            }
            for (int i = 1; i <= N; ++i)
            {
                w[i - 1] -= w0;
                for (int j = 1; j <= i; ++j)
                    for (int k = 0; k <= DELTA * N; ++k)
                    {
                        if (k >= w[i - 1] && dim[i][j][k] < v[i - 1] + dim[i - 1][j - 1][k - w[i - 1]])
                            dim[i][j][k] = v[i - 1] + dim[i - 1][j - 1][k - w[i - 1]];
                        if (i > j && dim[i][j][k] < dim[i - 1][j][k])
                            dim[i][j][k] = dim[i - 1][j][k];
                    }
            }
            long total = 0;
            for (int ii = 1; ii <= N; ++ii)
                for (int j = Math.Min(W - ii * w0, ii * DELTA);j >= 0 ; --j)
                    total = Math.Max(total, dim[N][ii][j]);
            writer.WriteLine(total);
        }
    }
}

