func solve(n int, w int) int {
	if n == 0 {
		return 0
	}
	if w == 0 {
		return 0
	}
	v := solve(n-1, w)
	if w-ws[n-1] >= 0 {
		v = Max(v, solve(n-1, w-ws[n-1])+vs[n-1])
	}
	return v
}

