func main() {
	sc = bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 0), 1000000001*3)
	sc.Split(bufio.ScanWords)
	n, W := nextInt(), nextInt()
	items := make([]item, n)
	for i := range items {
		w, v := nextInt(), nextInt()
		items[i] = item{w, v}
	}
	dp := make(map[int]int)
	dp[0] = 0
	for _, item := range items {
		dpNext := make(map[int]int)
		for w, v := range dp {
			wTmp, vTmp := w, v
			vNext, ok := dpNext[wTmp]
			if !ok || vTmp > vNext {
				dpNext[wTmp] = vTmp
			}

			wTmp, vTmp = w+item.w, v+item.v
			if wTmp > W {
				continue
			}
			vNext, ok = dpNext[wTmp]
			if !ok || vTmp > vNext {
				dpNext[wTmp] = vTmp
			}
		}
		dp = dpNext
	}

	ans := 0
	for _, v := range dp {
		if v > ans {
			ans = v
		}
	}
	fmt.Println(ans)
}

