var memo = make(map[int]map[int]int)

func solve(n int, w int) int {
	if n == 0 {
		return 0
	}
	if w == 0 {
		return 0
	}
	if _, ok := memo[n]; !ok {
		memo[n] = make(map[int]int)
	}
	if v, ok := memo[n][w]; ok {
		return v
	}
	v := solve(n-1, w)
	if w-ws[n-1] >= 0 {
		v = Max(v, solve(n-1, w-ws[n-1])+vs[n-1])
	}
	memo[n][w] = v
	return v
}

