alias Item = Tuple!(int, "weight", long[], "values");

long calc(int W, Item[] items) {

    long rec(int p, long weight, long value) {
        if (p == items.length) return value;

        long ans = rec(p + 1, weight, value); // p 番目は使わないときの解
        auto w = items[p].weight;
        auto v = items[p].values;
        for (int i = 0; i < v.length; i++) {
            long w2 = weight + w * (i + 1);
            if (w2 > W) break;

            long v2 = value + v[i];
            ans = max(ans, rec(p + 1, w2, v2));
        }
        return ans;
    }

    return rec(0, 0, 0);
}

void main() {
