        long[] t = v.dup.to!(long[]);
        t.sort();
        t.reverse();
        for (int i = 1; i < t.length; i++) {
            t[i] += t[i-1];
        }
        items ~= Item(k, t);
    }

    writeln(calc(W, items));
}

