    s = readln.split.map!(to!int);
    w1 = s[0];
    V[0] ~= s[1];
    foreach (i; 0..N-1) {
        s = readln.split.map!(to!int);
        V[s[0]-w1] ~= s[1];
    }

    foreach (i; 0..4) {
        V[i].sort!"a > b"();
