    }

    mem = new int[][][][](L[0]+1, L[1]+1, L[2]+1, L[3]+1);
    foreach (i; 0..L[0]+1) foreach (j; 0..L[1]+1) foreach (k; 0..L[2]+1) fill(mem[i][j][k], -1);

    dfs(0, 0, 0, 0, 0);
    ans.writeln;
}

