auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto nw = input.front.split.to!( long[] );
	auto wvs = new long[ 2 ][ nw[ 0 ] ];
	foreach( ref wv; wvs )
	{
		input.popFront;
		wv = input.front.split.to!( long[] );
	}
	return tuple( nw[ 1 ], wvs );
}

auto solve( long wt, long[ 2 ][] wvs )
{
	wvs.multiSort!( ( a, b ) => b[ 0 ] < a[ 0 ], ( a, b ) => b[ 1 ] < a[ 1 ] );

	// 重さごとに分けて、価値の高い順で累積和表を作成
	auto sss = new long[][ 4 ];
	auto wm = wvs[ 0 ][ 0 ];
	foreach( i, ref ss; sss )
	{
		ss = [ 0 ];
		while( !wvs.empty && wvs.front[ 0 ] == wm - i )
		{
			ss ~= ss[ $ - 1 ] + wvs.front[ 1 ];
			wvs.popFront;
		}
	}

	// 重さwt以内で価値が最大になるパターンを全検索
	auto ans = 0L;
	foreach( c1, s1; sss[ 0 ] )
	{
		auto w1 = wm * c1;
		if( wt < w1 ) break;

		foreach( c2, s2; sss[ 1 ] )
		{
			auto w2 = ( wm - 1 ) * c2;
			if( wt < w1 + w2 ) break;

			foreach( c3, s3; sss[ 2 ] )
			{
				auto w3 = ( wm - 2 ) * c3;
				if( wt < w1 + w2 + w3 ) break;

				foreach( c4, s4; sss[ 3 ] )
				{
					auto w4 = ( wm - 3 ) * c4;
					if( wt < w1 + w2 + w3 + w4 ) break;

					ans = max( ans, s1 + s2 + s3 + s4 );
				}
			}
		}
	}
	return ans;
}

void main()
{
    long n, w;
    rdVals(n, w);

    long[][] items = new long[][](4);
    long w0, v0;
    rdVals(w0, v0);
    items[0] ~= v0;
    foreach (i; 1 .. n)
    {
        long wi, vi;
        rdVals(wi, vi);
        items[wi-w0] ~= vi;
    }

    long[][] lists = new long[][](4);
    long[] len = new long[4];
    foreach (i; 0 .. 4)
    {
        items[i].sort!"a > b";
        lists[i].length = items[i].length + 1;
        len[i] = lists[i].length;
        foreach (j, x; items[i])
        {
            lists[i][j+1] = lists[i][j] + items[i][j];
        }
    }

    long result;
    foreach (i; 0 .. len[0])
    {
        long w1 = w0 * i;
        long v1 = lists[0][i];
        if (w1 > w) break;
        foreach (j; 0 .. len[1])
        {
            long w2 = w1 + (w0 + 1) * j;
            long v2 = v1 + lists[1][j];
            if (w2 > w) break;
            foreach (k; 0 .. len[2])
            {
                long w3 = w2 + (w0 + 2) * k;
                long v3 = v2 + lists[2][k];
                if (w3 > w) break;
                foreach (l; 0 .. len[3])
                {
                    long w4 = w3 + (w0 + 3) * l;
                    long v4 = v3 + lists[3][l];
                    if (w4 > w) break;
                    result = max(result, v4);
                }
            }
        }
    }

    result.writeln;
}

