int Knapsack(int pos, int pw)
{
    if(pos>=n)return 0;
    int p1 , p2;
    if(dp[pos][pw] !=  -1)return dp[pos][pw];
    if(pw + w[pos] <= W) p2 = Knapsack(pos + 1 , pw + w[pos]) + p[pos];
