def solve():
    from itertools import accumulate

    N, W = map(int, input().split())

    e = tuple([] for _ in range(4))
    w1, v1 = map(int, input().split())
    e[0].append(v1)

    for _ in range(N - 1):
        _w, _v = map(int, input().split())
        e[_w - w1].append(_v)

    g = [None for _ in range(4)]
    for j in range(4):
        e[j].sort(reverse=True)
        g[j] = (0,) + tuple(accumulate(e[j]))

    ret = 0
    for a in range(min(len(e[0]), N) + 1):
        for b in range(min(len(e[1]), N - a) + 1):
            for c in range(min(len(e[2]), N - a - b) + 1):
                for d in range(min(len(e[3]), N - a - b - c) + 1):
                    if w1 * a + (w1 + 1) * b + (w1 + 2) * c + (w1 + 3) * d > W:
                        break
                    ret = max(ret, g[0][a] + g[1][b] + g[2][c] + g[3][d])
    return ret


