    dp = [[-1] * (W + 1) for _ in range(N + 1)]
    dp[0][0] = 0
    for i in range(N):
        for j in [0] + list(range(w[0], min(100 * (w[0] + 3), W + 1))):
            if dp[i][j] < 0:
