import sys


def solve(N: int, W: int, w: "List[int]", v: "List[int]"):
    from itertools import groupby, product
    wv_list = [list(g) for k, g in groupby(sorted(zip(w, v), key=lambda x:(x[0],-x[1])), key=lambda x:x[0])]
    base_w = wv_list[0][0][0]
    acc_wv = [[0] * (N+1) for _ in range(4)]
    for wv in wv_list:
        i = wv[0][0] - base_w
        for j, (_, v) in enumerate(wv):
            acc_wv[i][j+1] = acc_wv[i][j] + v
    ans = 0
    for i, j, k, l in product(range(N+1), repeat=4):
        if i * base_w + j * (base_w + 1) + k * (base_w + 2)+ l * (base_w + 3) > W:
            continue
        ans = max(ans, acc_wv[0][i] + acc_wv[1][j] + acc_wv[2][k] + acc_wv[3][l])
    return ans

