import sys
from collections import defaultdict
import heapq
from copy import deepcopy

# 各重さごとに価値降順でソート
# とっていく
# 重さ合計は w0 * k ~ (w0 + 3) * kのどれか N=100だと15000通りくらい

def solve(N: int, W: int, ws: "List[int]", vs: "List[int]"):
    w0 = ws[0]
    dp = defaultdict(lambda: [-1, []]) # dp[w]: 重さ合計wでの[最大価値, [w, w+1, w+2, w+3の数のリスト]]
    dp[0] = [0, [[0, 0, 0, 0]]]
    Q = []
    items = defaultdict(list)
    for w, v in zip(ws, vs):
        items[w].append(v)
    for w in range(w0, w0+4):
        items[w].sort(reverse=True)
    heapq.heappush(Q, 0)
    while len(Q) > 0:
        w_c = heapq.heappop(Q)
        if w_c > W:
            break
        v_c = dp[w_c][0]
        w_counts = dp[w_c][1]
        for w_count in w_counts:
            for i in range(4):
                if w_count[i] >= len(items[w0+i]):
                    continue

                v_n = v_c + items[w0+i][w_count[i]]
                w_n = w_c + w0+i
                if v_n < dp[w_n][0]:
                    continue

                w_count_n = deepcopy(w_count)
                w_count_n[i] += 1
                if v_n == dp[w_n][0]:
                    if w_count_n not in dp[w_n][1]:
                        dp[w_n][1].append(w_count_n)
                elif v_n > dp[w_n][0]:
                    dp[w_n][1] = [w_count_n]
                    dp[w_n][0] = v_n
                if w_n not in Q:
                    heapq.heappush(Q, w_n)
