    dp = [[-1] * (maximum + 1) for _ in range(N + 1)]
    dp[0][0] = 0
    for i in range(N):
        if w[i] <= W:
            dp[i + 1][w[i]] = max(dp[i + 1][w[i]], dp[i][0] + v[i])
        dp[i + 1][0] = dp[i][0]

        for jj in list(range(w[0], maximum + 1)):
            j = jj - offset + 1
            if dp[i][j] < 0:
                continue
            if jj + w[i] <= W + 1:
                dp[i + 1][j + w[i]] = max(dp[i + 1][j + w[i]], dp[i][j] + v[i])
            dp[i + 1][j] = max(dp[i + 1][j], dp[i][j])
        # print(list(zip(*dp)))

    ans = 0
    for i in range(W + 1):
        ans = max(ans, dp[N][i])
    return ans

