fn main() {
    input! {
        n: usize, l: usize,
        p: [(usize, usize); n]
    }

    let base = p[0].0;
    let mut count = vec![0usize; 4];
    for &(i, _) in p.iter() {
        count[i - base] += 1;
    }

    let mut acs = vec![vec![0]; 4];
    let mut ws = vec![vec![0]; 4];
    for &(w, v) in p.iter().sorted_by_key(|x| Reverse(x.1)) {
        let k = w - base;
        let next = acs[k].last().unwrap() + v;
        let wn = ws[k].last().unwrap() + w;
        acs[k].push(next);
        ws[k].push(wn);
    }

    dbg!(&acs);

    let mut ans = 0usize;
    for a in 0..=count[0] {
        for b in 0..=count[1] {
            for c in 0..=count[2] {
                for d in 0..=count[3] {
                    let v = acs[0][a] + acs[1][b] + acs[2][c] + acs[3][d];
                    let w = ws[0][a] + ws[1][b] + ws[2][c] + ws[3][d];

                    if w <= l {
                        ans = max(ans, v);
                    }
                }
            }
        }
    }

    vis!(ans);
}

