    let wmax = line[1];

    let mut memo = vec![vec![0u64; n*3 + 1]; n+1];
    let mut wv = Vec::with_capacity(n);

    for i in 0..n {
        let line: Vec<u64> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();

