fn main() {
    let (n,w) = {
        let s = rv::<usize>();
        (s[0],s[1])
    };
    let mut wv = Vec::with_capacity(n);
    for _ in 0..n {
        let s = rv::<usize>();
        wv.push((s[0],s[1]));
    }
    let wm = wv.iter().map(|wv|wv.0).min().unwrap();
    let wn = wv.iter().map(|wv|wv.0-wm).max().unwrap();
    let mut dp = vec![vec![0;wn*n+1];n+1];
    for (i,(w,v)) in wv.into_iter().enumerate() {
        let w=w-wm;
        for j in (1..i+2).rev() {
            for k in 0..w {
                dp[j][k]=max(dp[j][k],dp[j-1][k]);
            }
            for k in 0..wn*(j-1)+1 {
                dp[j][k+w]=max(dp[j][k+w],dp[j-1][k]+v);
            }
            for k in wn*(j-1)+w+1..wn*j+1 {
                dp[j][k]=max(dp[j][k],dp[j][k-1]);
            }
        }
    }
    let mut t=0;
    for i in 1..n+1 {
        if wm*i>w {
            break;
        }
