use std::cmp::max;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, w) = parse!(it, 2);
    let mut wv = vec![];
    let mut w0 = 0;
    for _ in 0..n {
        let (w, v): (usize, usize) = parse!(it, 2);
        wv.push((w - w0, v));
    }
    let mut dp = vec![vec![vec![0usize; 3 * n + 1]; n + 1]; n + 1];
    for i in 1..(n + 1) {
        if i * w0 > w {
            break;
        }
        for j in 1..(n + 1) {
            for k in 0..(std::cmp::min(3 * n, w - i * w0) + 1) {
                let (wi, vi) = wv[j - 1];
                dp[i][j][k] = if k >= wi {
                    *[
                        dp[i][j - 1][k],
                        dp[i - 1][j - 1][k - wi] + vi,
                        dp[i - 1][j][k],
                    ]
                    .into_iter()
                    .max()
                    .unwrap()
                } else {
                    std::cmp::max(dp[i][j - 1][k], dp[i - 1][j][k])
                };
            }
        }
    }
    let mut ret = 0;
    for i in 1..(n + 1) {
        if i * w0 > w {
            break;
        }
        for k in 0..(std::cmp::min(3 * n, w - i * w0) + 1) {
            ret = std::cmp::max(ret, dp[i][n][k]);
        }
    }
    println!("{}", ret);
}

