// ABC086C - Traveling
// https://atcoder.jp/contests/abs/fasks/arc089_a

#[fastout]
fn main() {
    input! {
        n: usize,
        w: usize,
        wv: [(usize, usize); n],
    }

    let w1 = wv[0].0;
    let mut wv2: Vec<Vec<usize>> = vec![Vec::new(); 4];
    for (ww, v) in wv {
        wv2[ww - w1].push(v);
    }
    for i in 0..4 {
        wv2[i].sort_unstable_by_key(|&x| Reverse(x));
    }
    // precompute sums
    let mut wv3: Vec<Vec<usize>> = vec![Vec::new(); 4];
    for i in 0..4 {
        wv3[i].push(0);
        for &v in &wv2[i] {
            if let Some(&x) = &wv3[i].last() {
                wv3[i].push(x + v);
            }
        }
    }
    let mut maxval = 0;
    for n0 in 0..=wv2[0].len() {
        if n0 * w1 > w {
            break;
        }
        for n1 in 0..=wv2[1].len() {
            if n0 * w1 + n1 * (w1 + 1) > w {
                break;
            }
            for n2 in 0..=wv2[2].len() {
                if n0 * w1 + n1 * (w1 + 1) + n2 * (w1 + 2) > w {
                    break;
                }
                let wroom = w - n0 * w1 - n1 * (w1 + 1) - n2 * (w1 + 2);
                let n3 = (wroom / (w1 + 3)).min(wv2[3].len());
                let val = wv3[0][n0] + wv3[1][n1] + wv3[2][n2] + wv3[3][n3];
                maxval = maxval.max(val);
            }
        }
    }
    println!("{}", maxval);
}

