fn rec(cur: usize, rest: usize, base: usize, lim: usize, vals: &[Vec<i64>]) -> i64 {
    if cur == 0 {
        let num = min(rest, lim / base);
        return vals[0].iter().take(num).sum();
    }

    let num_lim = min(rest, lim / (base + cur));
    let mut res = 0;
    for num in 0..=num_lim {
        let res1: i64 = vals[cur].iter().take(num).sum();
        res = max(res, res1 + rec(cur - 1, rest - num, base, lim - num * (base + cur), vals));
    }
    res
}

