fn main() {
    input! {
        N: usize, W: usize,
        wv: [(usize, i64); N]
    }

    let mut ans = 0;
    for k in 1..=N {
        let w0 = wv[0].0;
        if W < k * w0 {
            continue;
        }
        let W = min(W - k * w0, 3 * k);
        let wv = wv.iter().map(|&(w, v)| (w - w0, v)).collect_vec();

        let mut dp = vec![vec![vec![0; 3 * k + 1]; k + 1]; N];
        let (w0, v0) = wv[0];
        dp[0][1][w0] = v0;
        for (i, (w, v)) in (0..).zip(wv).skip(1) {
            dp[i] = dp[i-1].clone();
            dp[i][1][w] = max(dp[i][1][w], v);
            for count in 1..k {
                for prev_w in (0..=3*k-w).rev() {
                    let prev_v = dp[i-1][count][prev_w];
                    dp[i][count+1][prev_w+w] = max(dp[i][count+1][prev_w+w], prev_v+v);
                }
            }

        }
        for w in 0..=W {
            ans = max(ans, dp[N-1][k][w]);
        }
    }
    println!("{}", ans);
}

