    }
    let mut ans = 0;
    for i in 0..(n + 1) {
        for j in 0..(3 * n + 1) {
            if p0 * i + j <= w {
                ans = std::cmp::max(ans, dp[i][j]);
            }
        }
    }
    println!("{}", ans);
}

