struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner { ptr: 0, length: 0, buf: vec![0; 1024], small_cache: vec![0; 1024] }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool { b == b'\n' || b == b'\r' || b == b'\t' || b == b' ' }

    fn read<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug, {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)]).parse().unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use std::cmp::max;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, w) = parse!(it, 2);
    let mut wv = vec![];
    let mut w0 = 0usize;
    for i in 0..n {
        let (w, v): (usize, usize) = parse!(it, 2);
        if i == 0 {
            w0 = w;
        }
        wv.push((w - w0, v));
    }
    let maxw = 3 * n;
    let mut dp = vec![vec![vec![0usize; maxw + 1]; n + 1]; n + 1];
    for i in 1..(n + 1) {
        if i * w0 > w {
            break;
        }
        for j in 1..(n + 1) {
            for k in 0..(std::cmp::min(maxw, w - i * w0) + 1) {
                let (wi, vi) = wv[j - 1];
                dp[i][j][k] = if k >= wi {
                    *[dp[i][j - 1][k], dp[i - 1][j - 1][k - wi] + vi]
                        .into_iter()
                        .max()
                        .unwrap()
                } else {
                    dp[i][j - 1][k]
                };
            }
        }
    }
    let mut ret = 0;
    for i in 1..(n + 1) {
        if i * w0 > w {
            break;
        }
        for k in 0..(std::cmp::min(maxw, w - i * w0) + 1) {
            ret = std::cmp::max(ret, dp[i][n][k]);
        }
    }
    println!("{}", ret);
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

