fn knapsack<T: Num + Copy + Ord>(
    a: impl AsRef<[(usize, T)]>, // (w, v)[]
    w: usize,
) -> T {
    let a = a.as_ref();
    let mut dp_last_row = vec![T::zero(); w + 1];
    for i in 0..a.len() {
        dp_last_row = (0..=w)
            .map(|w_iter| {
                if w_iter < a[i].0 {
                    dp_last_row[w_iter]
                } else {
                    dp_last_row[w_iter].max(dp_last_row[w_iter - a[i].0] + a[i].1)
                }
            })
            .collect();
    }
    *dp_last_row.last().unwrap()
}

