    if N == 1 {
        println!("{}", ans);
        return;
    }

    for k in 2..=N {
        let w0 = wv[0].0;
        if W < k * w0 {
            continue;
        }
        let W = W - k * w0;
        let wv = wv.iter().map(|&(w, v)| (w - w0, v)).collect_vec();

