            for count in 1..=k {
                dp[i][count] = dp[i-1][count].clone();
            }
            if W < w {
                continue;
            }
            for count in 1..=k {
                dp[i][count][w] = max(dp[i][count][w], v);
                if count == k {
                    continue;
                }
                for prev_w in (0..=min(3*k-w, W-w)).rev() {
                    let prev_v = dp[i-1][count][prev_w];
                    dp[i][count+1][prev_w+w] = max(dp[i][count+1][prev_w+w], prev_v+v);
                }
            }
