use std::collections::{HashSet, BinaryHeap, VecDeque};
use std::iter::FromIterator;
fn main() {
    input! {
        N: usize,
        W: usize,
        bud: [(usize, usize); N]
    }

    let mut ww = bud[0].0;
    let mut weight_list = vec![BinaryHeap::new(); 4];
    for &(w, v) in bud.iter() {
        weight_list[w-ww].push(v);
    }

    let mut values = vec![Vec::new(); 4];
    for ind in 0..4 {
        values[ind].push(0);
        for _ in 0..weight_list[ind].len() {
            let next = values[ind].last().unwrap() + weight_list[ind].pop().unwrap();
            values[ind].push(next);
        }
    }

    let mut max = 0_usize;
    for n0 in 0..cmp::min(N+1, values[0].len()) {
        for n1 in 0..cmp::min(N-n0+1, values[1].len()) {
            for n2 in 0..cmp::min(N-n0-n1+1, values[2].len()) {
                for n3 in 0..cmp::min(N-n0-n1+1, values[3].len()) {
                    if W >= n0*ww + n1*(ww+1) + n2*(ww+2) + n3*(ww+3){
                        max = cmp::max(max, 
                            values[0][n0]+values[1][n1]+values[2][n2]+values[3][n3]); 
                    }
                }
            }
        }
    }
    println!("{}", max);
}

