fn solve(vss: &Vec<Vec<usize>>, w: usize, W: usize) -> usize{
    if vss.len()==0 {
        0
    } else {
        let mut sum_w = 0;
        let mut sum_v = 0;
        let mut ans = solve(&vss[1..].to_vec(), w+1, (W as i64 - sum_w as i64) as usize);
        for v in &vss[0]{
            sum_w += w;
            if sum_w > W {
                break;
            } else {
                sum_v += *v;
                ans = max(ans, sum_v + solve(&vss[1..].to_vec(), w+1, (W as i64 - sum_w as i64) as usize));
            }
        }
        ans
    }
