use proconio::{fastout, input};
use std::cmp::{max, min};

#[fastout]
fn main() {
    input! {
        n :usize,
        w: i64,
        wv:[(i64, i64); n],
    }

    let w0 = wv[0].0;
    let mut vals = vec![vec![]; 4];
    for i in 0..n {
        vals[(wv[i].0 - w0) as usize].push(wv[i].1);
    }

    vals[0].sort_by_key(|t| -t);
    vals[1].sort_by_key(|t| -t);
    vals[2].sort_by_key(|t| -t);
    vals[3].sort_by_key(|t| -t);

    let mut res = 0;
    let mut zero = 0;
    let mut one = 0;
    let mut two = 0;

    for i in 0..=vals[0].len() {
        if i > 0 {
            zero += vals[0][i - 1];
        }
        for j in 0..=vals[1].len() {
            if j > 0 {
                one += vals[1][j - 1];
            } else {
                one = 0;
            }
            for k in 0..=vals[2].len() {
                if k > 0 {
                    two += vals[2][k - 1];
                } else {
                    two = 0;
                }
                let now = w0 * (i + j + k) as i64 + (j + 2 * k) as i64;
                let mut cmp = zero + one + two;
                if now > w {
                    continue;
                }
                let can_take = (w - now) / (w0 + 3);
                for l in 0..min(can_take as usize, vals[3].len()) {
                    cmp += vals[3][l];
                }
                res = max(res, cmp);
            }
        }
    }
    println!("{}", res);
}

