use std::collections::HashMap;

#[allow(unused_must_use)]
#[allow(unused_variables)]
fn solve() {
    let (n, weight) = input!(usize, u64);
    let mut items: HashMap<u64, Vec<u64>> = HashMap::new();

    let (w, v) = input!(u64, u64);

    let base_weight = w;

    items.insert(base_weight, vec![]);
    items.insert(base_weight + 1, vec![]);
    items.insert(base_weight + 2, vec![]);
    items.insert(base_weight + 3, vec![]);

    {
        let vec = items.entry(w).or_insert(vec![]);
        (*vec).push(v);
    }

    for _ in 0..(n-1) {
        let (w, v) = input!(u64, u64);
        let vec = items.entry(w).or_insert(vec![]);
        (*vec).push(v);
    }

    for v in items.values_mut() {
        v.sort();
        v.reverse();
    }

    let mut current_max = 0;
    for a in 0..(n + 1) {
        for b in 0..(n + 1 - a) {
            for c in 0..(n + 1 - a - b) {
                for d in 0..(n + 1 - a - b - c) {
                    let mut total_weight: u64 = 0;
                    let mut total_value: u64 = 0;

                    let v = items.get(&base_weight).unwrap();
                    if v.len() < a {
                        continue;
                    }
                    total_weight += base_weight * a as u64;
                    let sum: u64 = v[0..a].iter().sum();
                    total_value += sum;

                    let v = items.get(&(base_weight + 1)).unwrap();
                    if v.len() < b {
                        continue;
                    }
                    total_weight += (base_weight + 1) * b as u64;
                    let sum: u64 = v[0..b].iter().sum();
                    total_value += sum;

                    let v = items.get(&(base_weight + 2)).unwrap();
                    if v.len() < c {
                        continue;
                    }
                    total_weight += (base_weight + 2) * c as u64;
                    let sum: u64 = v[0..c].iter().sum();
                    total_value += sum; 

                    let v = items.get(&(base_weight + 3)).unwrap();
                    if v.len() < d {
                        continue;
                    }
                    total_weight += (base_weight + 3) * d as u64;
                    let sum: u64 = v[0..d].iter().sum();
                    total_value += sum;

                    if total_weight <= weight && total_value > current_max {
                        current_max = total_value;
                    }
                }
            }
        }
    }

    println!("{}", current_max);
}

