use std::io::{BufRead, Write};
use std::io;
use std::cmp;
use std::collections::HashMap;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let mut split = s.split_whitespace();
    let n = split.next().unwrap().parse::<u64>().unwrap();
    let w = split.next().unwrap().parse::<u64>().unwrap();
    let wv = (0..n)
        .map(|_| {
                 let mut s = String::new();
                 input.read_line(&mut s).unwrap();
                 let mut split = s.split_whitespace();
                 let w = split.next().unwrap().parse::<u64>().unwrap();
                 let v = split.next().unwrap().parse::<u64>().unwrap();
                 (w, v)
             })
        .collect::<Vec<_>>();
    let mut cache = HashMap::<(u64, u64), u64>::new();
    fn dp(i: u64, j: u64, cache: &mut HashMap<(u64, u64), u64>, wv: &[(u64, u64)]) -> u64 {
        if i == 0 {
            0
        } else {
            if let Some(&hit) = cache.get(&(i, j)) {
                hit
            } else {
                let val = cmp::max(dp(i - 1, j, cache, wv),
                                   if wv[i as usize - 1].0 <= j {
                                       dp(i - 1, j - wv[i as usize - 1].0, cache, wv) +
                                       wv[i as usize - 1].1
                                   } else {
                                       0
                                   });
                cache.insert((i, j), val);
                val
            }
        }
    }
    writeln!(output, "{}", dp(n, w, &mut cache, &wv)).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

