#![allow(unused_imports)]
#![allow(non_snake_case)]
use std::cmp::*;
use std::collections::*;
use std::ops::Bound::*;
use itertools::Itertools;
use num_traits::clamp;
use ordered_float::OrderedFloat;
use proconio::{input, marker::*, fastout};
use superslice::*;

#[fastout]
fn main() {
    input! {
        N: usize, W: usize,
        wv: [(usize, i64); N]
    }

    if N == 1 {
        let ans = if wv[0].0 <= W { wv[0].1 } else { 0 };
        println!("{}", ans);
        return;
    }

    let mut ans = 0;
    for k in 2..=N {
        let w0 = wv[0].0;
        if W < k * w0 {
            continue;
        }
        let W = W - k * w0;
        let wv = wv.iter().map(|&(w, v)| (w - w0, v)).collect_vec();

        let mut dp = vec![vec![vec![0; 3 * k + 1]; k + 1]; N];
        let (w0, v0) = wv[0];
        dp[0][1][w0] = v0;
        for (i, (w, v)) in (0..).zip(wv).skip(1) {
            for count in 1..=k {
                dp[i][count] = dp[i-1][count].clone();
            }
            for count in 1..=k {
                if W < w {
                    continue;
                }
                dp[i][count][w] = max(dp[i][count][w], v);
                if count == k {
                    continue;
                }
                for prev_w in (0..=min(3*k, W-w)).rev() {
                    let prev_v = dp[i-1][count][prev_w];
                    dp[i][count+1][prev_w+w] = max(dp[i][count+1][prev_w+w], prev_v+v);
                }
            }
        }
        for w in 0..=min(3*k, W) {
            ans = max(ans, dp[N-1][k][w]);
        }
    }
    println!("{}", ans);
}

