use std::io::stdin;

fn input_ints() -> Vec<i64> {
    let mut st = String::new();
    match stdin().read_line(&mut st) {
        Ok(_) => {
            st.split_whitespace()
                .map(|s| s.parse().unwrap())
                .collect()
        }
        Err(_) => panic!("err"),
    }
}

#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
struct Item {
    v: i64,
    w: i64,
}

impl Item {
    fn new(w: i64, v: i64) -> Item {
        Item { w: w, v: v }
    }
}

fn main() {
    let l = input_ints();
    let n = l[0];
    let weight = l[1];
    let mut items = Vec::new();

    for _ in 0..n {
        let l = input_ints();
        items.push(Item::new(l[0], l[1]))
    }

    let min_weight = items[0].w;

    let mut items_selected_by_weight = Vec::new();

    for w in min_weight..min_weight + 4 {
        let mut is: Vec<Item> = items.iter().filter(|x| x.w == w).cloned().collect();
        is.sort();
        is.reverse();
        items_selected_by_weight.push(is);
    }

    let mut v_max = 0;
    for i in 0..items_selected_by_weight[0].len() + 1 {
        let w1 = i as i64 * min_weight;
        if w1 > weight {
            continue;
        }
        let v1: i64 = items_selected_by_weight[0][0..i]
            .iter()
            .cloned()
            .map(|x| x.v)
            .sum();
        for j in 0..items_selected_by_weight[1].len() + 1 {
            let w2 = j as i64 * (min_weight + 1);
            if w1 + w2 > weight {
                continue;
            }
            let v2: i64 = items_selected_by_weight[1][0..j]
                .iter()
                .cloned()
                .map(|x| x.v)
                .sum();
            for k in 0..items_selected_by_weight[2].len() + 1 {
                let w3 = k as i64 * (min_weight + 2);
                if w1 + w2 + w3 > weight {
                    continue;
                }
                let v3: i64 = items_selected_by_weight[2][0..k]
                    .iter()
                    .cloned()
                    .map(|x| x.v)
                    .sum();
                for l in 0..items_selected_by_weight[3].len() + 1 {
                    let w4 = l as i64 * (min_weight + 3);
                    if w1 + w2 + w3 + w4 > weight {
                        continue;
                    }
                    let v4: i64 = items_selected_by_weight[3][0..l]
                        .iter()
                        .cloned()
                        .map(|x| x.v)
                        .sum();

                    if v_max < v1 + v2 + v3 + v4 {
                        v_max = v1 + v2 + v3 + v4;
                    }
                }
            }
        }
    }
    println!("{}", v_max);
}

#![allow(unused_imports, unused_variables, dead_code)]
use std::io::*;
use std::fmt::*;
use std::str::*;
use std::cmp::*;
use std::collections::*;

trait InputValue {
    fn parse(s: &str) -> Self;
}

fn read<T: InputValue>() -> T {
    let mut buf = String::new();
    let _ = stdin().read_line(&mut buf);
    T::parse(&buf.trim())
}

fn readnc<T: InputValue>() -> Vec<T> {
    let mut vec = vec![];
    let line: String = read();
    for token in line.split_whitespace() {
        vec.push(T::parse(token));
    }
    vec
}

fn readn<T: InputValue>(n: usize) -> Vec<T> {
    let mut vec = vec![];
    for _ in 0..n {
        vec.push(read());
    }
    vec
}

macro_rules! parse_single_value {
    ($($t:ty),*) => {
        $(
            impl InputValue for $t {
                fn parse(s: &str) -> $t { s.parse().unwrap() }
            }
        )*
	}
}
parse_single_value!(i32, i64, f32, f64, usize, String);

macro_rules! parse_tuple {
	($($t:ident),*) => {
		impl<$($t),*> InputValue for ($($t),*) where $($t: InputValue),* {
			fn parse(s: &str) -> ($($t),*) {
				let mut tokens = s.split_whitespace();
				let t = ($($t::parse(tokens.next().unwrap())),*);
				t
			}
		}
	}
}
parse_tuple!(A, B);
parse_tuple!(A, B, C);

