fn main() {
    let (n, w): (usize, usize) = read();
    let wv: Vec<(usize, i32)> = readn(n);

    let mw = n * 3;
    let mut dp: Vec<Vec<Vec<i32>>> = vec![vec![vec![-1; mw+1]; n+1]; n+1];
    dp[0][0][0] = 0;

    let basew = wv[0].0;
    for i in 0..n {
        let wi = wv[i].0 - basew;
        for j in 0..n {
            for k in 0..mw+1 {
                let base = dp[i][j][k];
                if base == -1 {
                    continue
                }
                dp[i+1][j][k] = max(dp[i+1][j][k], base);

                let tj = j+1;
                let tk = k+wi;
                dp[i+1][tj][tk] = max(dp[i+1][tj][tk], base + wv[i].1);
            }
        }
    }

    let mut ans = 0;
    for j in 0..n+1 {
        for k in 0..mw+1 {
            let weight = j * basew + k;
            if weight <= w {
                ans = max(ans, dp[n][j][k]);
            }
        }
    }
    println!("{}", ans);
}
